import React, { useState, useEffect } from 'react';
import { X, Calendar as CalendarIcon, User as UserIcon, Flag, CheckCircle2 } from 'lucide-react';
import { Task, User, TaskStatus, Priority, normalizeDate } from '../types';
import { USERS, STATUS_LABELS } from '../constants';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

interface TaskModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Task) => void;
  onDelete?: (taskId: string) => void;
  initialTask?: Task | null;
  selectedDate?: Date;
  currentUser: User;
}

const TaskModal: React.FC<TaskModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  onDelete, 
  initialTask, 
  selectedDate, 
  currentUser 
}) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [assigneeId, setAssigneeId] = useState(currentUser.id);
  const [priority, setPriority] = useState<Priority>('MEDIUM');
  const [status, setStatus] = useState<TaskStatus>('TODO');
  const [dateStr, setDateStr] = useState('');

  // Reset or populate form when modal opens
  useEffect(() => {
    if (isOpen) {
      if (initialTask) {
        setTitle(initialTask.title);
        setDescription(initialTask.description);
        setAssigneeId(initialTask.assigneeId);
        setPriority(initialTask.priority);
        setStatus(initialTask.status);
        setDateStr(format(initialTask.date, 'yyyy-MM-dd'));
      } else {
        // New Task
        setTitle('');
        setDescription('');
        setAssigneeId(USERS[1].id); // Default to first member
        setPriority('MEDIUM');
        setStatus('TODO');
        setDateStr(selectedDate ? format(selectedDate, 'yyyy-MM-dd') : format(new Date(), 'yyyy-MM-dd'));
      }
    }
  }, [isOpen, initialTask, selectedDate, currentUser]);

  if (!isOpen) return null;

  const handleSave = () => {
    if (!title.trim() || !dateStr) return;

    // Fix timezone offset issue by explicitly handling the date string
    const [year, month, day] = dateStr.split('-').map(Number);
    const localDate = new Date(year, month - 1, day);

    const newTask: Task = {
      id: initialTask?.id || crypto.randomUUID(),
      title,
      description,
      assigneeId,
      priority,
      status,
      date: normalizeDate(localDate),
    };
    onSave(newTask);
    onClose();
  };

  const isLeader = currentUser.role === 'LEADER';
  // Leader can edit everything. Members can only update status of their own tasks (or if it's a new task they are creating, though logic restricts creation to leaders mostly).
  // However, for UX, if a member opens a task assigned to them, they should be able to update Status.
  const canEditDetails = isLeader; 
  const canEditStatus = isLeader || (initialTask && initialTask.assigneeId === currentUser.id);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in duration-200">

        {/* Header */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 flex justify-between items-center">
          <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
            {initialTask ? 'Detalhes da Demanda' : 'Nova Demanda'}
          </h2>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 space-y-5">

          {/* Title */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Título</label>
            <input
              type="text"
              disabled={!canEditDetails}
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 disabled:bg-slate-100 disabled:text-slate-500 transition-all"
              placeholder="Ex: Entregar relatório de vendas"
            />
          </div>

          {/* Date & Priority Row */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <CalendarIcon size={14} /> Prazo
              </label>
              <input
                type="date"
                disabled={!canEditDetails}
                value={dateStr}
                onChange={(e) => setDateStr(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <Flag size={14} /> Prioridade
              </label>
              <select
                disabled={!canEditDetails}
                value={priority}
                onChange={(e) => setPriority(e.target.value as Priority)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100"
              >
                <option value="LOW">Baixa</option>
                <option value="MEDIUM">Média</option>
                <option value="HIGH">Alta</option>
              </select>
            </div>
          </div>

          {/* Assignee */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
              <UserIcon size={14} /> Responsável
            </label>
            <div className="relative">
              <select
                disabled={!canEditDetails}
                value={assigneeId}
                onChange={(e) => setAssigneeId(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 appearance-none disabled:bg-slate-100"
              >
                {USERS.map((user) => (
                  <option key={user.id} value={user.id}>
                    {user.name}
                  </option>
                ))}
              </select>
              <div className="absolute right-3 top-2.5 pointer-events-none text-slate-400">
                <UserIcon size={16} />
              </div>
            </div>
          </div>

          {/* Status - Available to assignee */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
              <CheckCircle2 size={14} /> Status
            </label>
            <div className="flex gap-2 p-1 bg-slate-100 rounded-lg">
              {(Object.keys(STATUS_LABELS) as TaskStatus[]).map((s) => (
                <button
                  key={s}
                  type="button"
                  disabled={!canEditStatus}
                  onClick={() => setStatus(s)}
                  className={`flex-1 py-2 text-xs font-medium rounded-md transition-all ${
                    status === s
                      ? 'bg-white text-indigo-600 shadow-sm border border-slate-200'
                      : 'text-slate-500 hover:text-slate-700'
                  } ${!canEditStatus ? 'opacity-50 cursor-not-allowed' : ''}`}
                >
                  {STATUS_LABELS[s]}
                </button>
              ))}
            </div>
          </div>

          {/* Description */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Descrição</label>
            <textarea
              disabled={!canEditDetails}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
              className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 resize-none"
              placeholder="Detalhes adicionais sobre a tarefa..."
            />
          </div>

        </div>

        {/* Footer */}
        <div className="bg-slate-50 border-t border-slate-100 px-6 py-4 flex justify-between">
           {initialTask && isLeader ? (
            <button
              onClick={() => {
                if (onDelete && initialTask) onDelete(initialTask.id);
                onClose();
              }}
              className="px-4 py-2 text-sm font-medium text-red-600 hover:bg-red-50 rounded-lg transition-colors"
            >
              Excluir
            </button>
           ) : <div></div>}

           <div className="flex gap-3">
             <button
               onClick={onClose}
               className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-200 rounded-lg transition-colors"
             >
               Cancelar
             </button>
             <button
               onClick={handleSave}
               className="px-4 py-2 text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-md shadow-indigo-200 transition-all hover:scale-105"
             >
               Salvar
             </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default TaskModal;

import React, { useState } from 'react';
import { 
  startOfMonth, endOfMonth, startOfWeek, endOfWeek, 
  eachDayOfInterval, isSameMonth, isSameDay, addMonths, subMonths, 
  format, isToday 
} from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { ChevronLeft, ChevronRight, Plus } from 'lucide-react';
import { Task, User, normalizeDate } from '../types';
import { STATUS_COLORS, USERS } from '../constants';

interface CalendarProps {
  tasks: Task[];
  currentUser: User;
  onAddTask: (date: Date) => void;
  onEditTask: (task: Task) => void;
}

const Calendar: React.FC<CalendarProps> = ({ tasks, currentUser, onAddTask, onEditTask }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const firstDayOfMonth = startOfMonth(currentDate);
  const lastDayOfMonth = endOfMonth(currentDate);
  const startDate = startOfWeek(firstDayOfMonth); // Start grid on Sunday/Monday
  const endDate = endOfWeek(lastDayOfMonth);

  const days = eachDayOfInterval({ start: startDate, end: endDate });

  const nextMonth = () => setCurrentDate(addMonths(currentDate, 1));
  const prevMonth = () => setCurrentDate(subMonths(currentDate, 1));
  const goToToday = () => setCurrentDate(new Date());

  const getTasksForDay = (date: Date) => {
    return tasks.filter(task => isSameDay(normalizeDate(task.date), normalizeDate(date)));
  };

  const isLeader = currentUser.role === 'LEADER';

  return (
    <div className="flex flex-col h-full bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">

      {/* Calendar Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 bg-white">
        <div className="flex items-center gap-4">
          <h2 className="text-2xl font-bold text-slate-800 capitalize">
            {format(currentDate, 'MMMM yyyy', { locale: ptBR })}
          </h2>
          <div className="flex items-center bg-slate-100 rounded-lg p-1">
            <button onClick={prevMonth} className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-slate-600">
              <ChevronLeft size={20} />
            </button>
            <button onClick={nextMonth} className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-slate-600">
              <ChevronRight size={20} />
            </button>
          </div>
        </div>

        <button 
          onClick={goToToday}
          className="px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-200 hover:bg-slate-50 hover:border-slate-300 rounded-lg transition-colors"
        >
          Hoje
        </button>
      </div>

      {/* Days of Week Header */}
      <div className="grid grid-cols-7 border-b border-slate-100 bg-slate-50">
        {['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'].map((day) => (
          <div key={day} className="py-3 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">
            {day}
          </div>
        ))}
      </div>

      {/* Calendar Grid */}
      <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-slate-100 gap-[1px]">
        {days.map((day) => {
          const dayTasks = getTasksForDay(day);
          const isCurrentMonth = isSameMonth(day, currentDate);
          const isDayToday = isToday(day);

          return (
            <div 
              key={day.toISOString()} 
              className={`
                bg-white relative flex flex-col min-h-[120px] p-2 group transition-colors
                ${!isCurrentMonth ? 'bg-slate-50/50' : ''}
              `}
            >
              {/* Day Number */}
              <div className="flex justify-between items-start mb-1">
                <span className={`
                  text-sm font-medium w-7 h-7 flex items-center justify-center rounded-full
                  ${isDayToday 
                    ? 'bg-indigo-600 text-white' 
                    : isCurrentMonth ? 'text-slate-700' : 'text-slate-400'}
                `}>
                  {format(day, 'd')}
                </span>

                {/* Add Button (Leader Only) - visible on hover */}
                {isLeader && (
                  <button 
                    onClick={() => onAddTask(day)}
                    className="opacity-0 group-hover:opacity-100 p-1 text-indigo-600 hover:bg-indigo-50 rounded transition-all"
                    title="Adicionar Demanda"
                  >
                    <Plus size={16} />
                  </button>
                )}
              </div>

              {/* Tasks List */}
              <div className="flex flex-col gap-1 overflow-y-auto max-h-[120px] custom-scrollbar">
                {dayTasks.map(task => {
                  const assignee = USERS.find(u => u.id === task.assigneeId);

                  return (
                    <button
                      key={task.id}
                      onClick={(e) => {
                        e.stopPropagation();
                        onEditTask(task);
                      }}
                      className={`
                        text-left text-xs p-1.5 rounded-md border shadow-sm transition-transform hover:scale-[1.02]
                        ${STATUS_COLORS[task.status]}
                      `}
                    >
                      <div className="font-semibold truncate leading-tight mb-0.5">{task.title}</div>
                      <div className="flex items-center justify-between opacity-80">
                        {assignee && (
                          <div className="flex items-center gap-1">
                             <img src={assignee.avatar} alt="" className="w-3.5 h-3.5 rounded-full" />
                             <span className="truncate max-w-[50px]">{assignee.name.split(' ')[0]}</span>
                          </div>
                        )}
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Calendar;

import React, { useState } from 'react';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import { User, Task, normalizeDate } from './types';
import { USERS, INITIAL_TASKS } from './constants';
import { Layout, Users, LogOut, CheckSquare } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User>(USERS[0]); // Default to Leader
  const [tasks, setTasks] = useState<Task[]>(INITIAL_TASKS);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  // Handlers
  const handleAddTask = (date: Date) => {
    setSelectedDate(date);
    setSelectedTask(null);
    setIsModalOpen(true);
  };

  const handleEditTask = (task: Task) => {
    setSelectedTask(task);
    setSelectedDate(task.date);
    setIsModalOpen(true);
  };

  const handleSaveTask = (taskToSave: Task) => {
    setTasks(prev => {
      const exists = prev.find(t => t.id === taskToSave.id);
      if (exists) {
        return prev.map(t => t.id === taskToSave.id ? taskToSave : t);
      }
      return [...prev, taskToSave];
    });
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
  };

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">

      {/* Sidebar Navigation */}
      <aside className="w-64 bg-slate-900 text-slate-300 flex flex-col flex-shrink-0 shadow-xl z-20">
        <div className="p-6 border-b border-slate-800">
          <div className="flex items-center gap-3 text-white">
            <div className="bg-indigo-600 p-2 rounded-lg">
               <Layout size={24} />
            </div>
            <h1 className="text-xl font-bold tracking-tight">GestorPro</h1>
          </div>
          <p className="text-xs text-slate-500 mt-2">Sistema de Gestão de Equipe</p>
        </div>

        <nav className="flex-1 p-4 space-y-2">
          <div className="bg-slate-800/50 text-indigo-400 px-4 py-3 rounded-lg flex items-center gap-3 font-medium cursor-pointer">
            <CheckSquare size={18} />
            <span>Calendário de Demandas</span>
          </div>
          <div className="px-4 py-3 rounded-lg flex items-center gap-3 hover:bg-slate-800 hover:text-white transition-colors cursor-not-allowed opacity-60">
            <Users size={18} />
            <span>Membros (Em breve)</span>
          </div>
        </nav>

        {/* User Switcher (Simulation) */}
        <div className="p-4 border-t border-slate-800 bg-slate-950">
          <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider block mb-2">
            Simular Acesso Como:
          </label>
          <div className="space-y-2">
            {USERS.map(u => (
              <button
                key={u.id}
                onClick={() => setCurrentUser(u)}
                className={`w-full flex items-center gap-2 p-2 rounded-md transition-all ${
                  currentUser.id === u.id 
                    ? 'bg-indigo-600 text-white shadow-md' 
                    : 'hover:bg-slate-800 text-slate-400'
                }`}
              >
                <img src={u.avatar} className="w-6 h-6 rounded-full border border-slate-600" alt="" />
                <div className="text-left overflow-hidden">
                  <div className="text-xs font-bold truncate">{u.name}</div>
                  <div className="text-[10px] opacity-80">{u.role === 'LEADER' ? 'Líder' : 'Membro'}</div>
                </div>
              </button>
            ))}
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        {/* Top Bar */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-8 shadow-sm z-10">
          <div className="flex items-center gap-4">
             <h2 className="text-xl font-bold text-slate-800">Panorama do Projeto</h2>
             <span className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-xs font-bold">
               {tasks.length} Demandas Ativas
             </span>
          </div>

          <div className="flex items-center gap-4">
            <div className="text-right mr-2 hidden sm:block">
              <div className="text-sm font-bold text-slate-800">{currentUser.name}</div>
              <div className="text-xs text-slate-500">{currentUser.role === 'LEADER' ? 'Acesso Administrativo' : 'Acesso de Membro'}</div>
            </div>
            <img src={currentUser.avatar} alt="User" className="w-10 h-10 rounded-full border-2 border-white shadow-sm" />
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 p-6 overflow-hidden flex flex-col">
          <div className="flex-1 h-full">
            <Calendar 
              tasks={tasks} 
              currentUser={currentUser}
              onAddTask={handleAddTask}
              onEditTask={handleEditTask}
            />
          </div>
        </div>
      </main>

      <TaskModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        initialTask={selectedTask}
        selectedDate={selectedDate}
        currentUser={currentUser}
      />
    </div>
  );
};

export default App;

export type Role = 'LEADER' | 'MEMBER';

export type TaskStatus = 'TODO' | 'IN_PROGRESS' | 'DONE';

export type Priority = 'LOW' | 'MEDIUM' | 'HIGH';

export interface User {
  id: string;
  name: string;
  email: string;
  role: Role;
  avatar: string;
}

export interface Task {
  id: string;
  title: string;
  description: string;
  assigneeId: string;
  date: Date; // Normalized to midnight
  startTime?: string; // Format "HH:mm"
  endTime?: string;   // Format "HH:mm"
  status: TaskStatus;
  priority: Priority;
}

export interface TransferRequest {
  id: string;
  taskId: string;
  requesterId: string;
  originalAssigneeId: string;
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
  taskTitle: string;
  requesterName: string;
}

// Helper to keep dates consistent
export const normalizeDate = (date: Date): Date => {
  const newDate = new Date(date);
  newDate.setHours(0, 0, 0, 0);
  return newDate;
};

