import React, { useState } from 'react';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import LoginScreen from './components/LoginScreen';
import TaskListView from './components/TaskListView';
import { User, Task, TransferRequest } from './types';
import { USERS, INITIAL_TASKS } from './constants';
import { Layout, LogOut, CheckSquare, List, Calendar as CalendarIcon, Bell } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [tasks, setTasks] = useState<Task[]>(INITIAL_TASKS);
  const [viewMode, setViewMode] = useState<'CALENDAR' | 'LIST'>('CALENDAR');

  // Requests System
  const [transferRequests, setTransferRequests] = useState<TransferRequest[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  // Handlers
  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setTransferRequests([]); // Clear requests on logout for demo purposes
  };

  const handleAddTask = (date: Date) => {
    setSelectedDate(date);
    setSelectedTask(null);
    setIsModalOpen(true);
  };

  const handleEditTask = (task: Task) => {
    setSelectedTask(task);
    setSelectedDate(task.date);
    setIsModalOpen(true);
  };

  const handleSaveTask = (taskToSave: Task) => {
    setTasks(prev => {
      const exists = prev.find(t => t.id === taskToSave.id);
      if (exists) {
        return prev.map(t => t.id === taskToSave.id ? taskToSave : t);
      }
      return [...prev, taskToSave];
    });
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
  };

  const handleRequestTransfer = (taskId: string, newAssigneeId: string) => {
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;

    const newRequest: TransferRequest = {
      id: crypto.randomUUID(),
      taskId,
      requesterId: newAssigneeId,
      originalAssigneeId: task.assigneeId,
      status: 'PENDING',
      taskTitle: task.title,
      requesterName: USERS.find(u => u.id === newAssigneeId)?.name || 'Unknown',
    };

    setTransferRequests(prev => [...prev, newRequest]);
    alert('Solicitação enviada para o Líder da equipe!');
  };

  const handleApproveRequest = (request: TransferRequest) => {
    // Update task assignee
    setTasks(prev => prev.map(t => {
      if (t.id === request.taskId) {
        return { ...t, assigneeId: request.requesterId };
      }
      return t;
    }));
    // Remove request
    setTransferRequests(prev => prev.filter(r => r.id !== request.id));
  };

  const handleRejectRequest = (requestId: string) => {
    setTransferRequests(prev => prev.filter(r => r.id !== requestId));
  };

  if (!currentUser) {
    return <LoginScreen onLogin={handleLogin} />;
  }

  const isLeader = currentUser.role === 'LEADER';

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">

      {/* Sidebar Navigation */}
      <aside className="w-20 lg:w-64 bg-slate-900 text-slate-300 flex flex-col flex-shrink-0 shadow-xl z-20 transition-all">
        <div className="p-4 lg:p-6 border-b border-slate-800 flex items-center justify-center lg:justify-start gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg text-white">
             <Layout size={24} />
          </div>
          <h1 className="hidden lg:block text-xl font-bold tracking-tight text-white">GestorPro</h1>
        </div>

        <nav className="flex-1 p-4 space-y-2">
          <div className="bg-slate-800/50 text-indigo-400 px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium cursor-pointer">
            <CheckSquare size={20} />
            <span className="hidden lg:inline">Minhas Demandas</span>
          </div>
        </nav>

        <div className="p-4 border-t border-slate-800 bg-slate-950">
          <button 
            onClick={handleLogout}
            className="w-full flex items-center justify-center lg:justify-start gap-2 text-slate-400 hover:text-white hover:bg-slate-800 p-2 rounded-lg transition-colors"
          >
            <LogOut size={20} />
            <span className="hidden lg:inline text-sm font-medium">Sair</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        {/* Top Bar */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shadow-sm z-10">

          {/* View Toggles */}
          <div className="flex bg-slate-100 p-1 rounded-lg">
            <button
              onClick={() => setViewMode('CALENDAR')}
              className={`flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-md transition-all ${
                viewMode === 'CALENDAR' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              <CalendarIcon size={16} />
              <span className="hidden sm:inline">Calendário</span>
            </button>
            <button
              onClick={() => setViewMode('LIST')}
              className={`flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-md transition-all ${
                viewMode === 'LIST' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              <List size={16} />
              <span className="hidden sm:inline">Lista de Demandas</span>
            </button>
          </div>

          <div className="flex items-center gap-6">

            {/* Notifications (Leader Only) */}
            {isLeader && (
              <div className="relative">
                <button 
                  onClick={() => setShowNotifications(!showNotifications)}
                  className="relative p-2 text-slate-500 hover:bg-slate-100 rounded-full transition-colors"
                >
                  <Bell size={20} />
                  {transferRequests.length > 0 && (
                    <span className="absolute top-1 right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white"></span>
                  )}
                </button>

                {showNotifications && (
                  <div className="absolute right-0 mt-2 w-80 bg-white border border-slate-200 shadow-xl rounded-xl z-50 overflow-hidden">
                    <div className="px-4 py-3 border-b border-slate-100 bg-slate-50 font-bold text-sm text-slate-700">
                      Solicitações ({transferRequests.length})
                    </div>
                    <div className="max-h-60 overflow-y-auto">
                      {transferRequests.length === 0 ? (
                        <div className="p-4 text-center text-xs text-slate-500">Nenhuma solicitação pendente.</div>
                      ) : (
                        transferRequests.map(req => (
                          <div key={req.id} className="p-3 border-b border-slate-50 hover:bg-slate-50">
                            <p className="text-xs text-slate-500 mb-1">
                              <span className="font-bold text-slate-700">{req.requesterName}</span> quer assumir:
                            </p>
                            <p className="text-sm font-semibold text-indigo-700 mb-2 truncate">"{req.taskTitle}"</p>
                            <div className="flex gap-2">
                              <button 
                                onClick={() => handleApproveRequest(req)}
                                className="flex-1 bg-indigo-600 text-white text-xs py-1 rounded hover:bg-indigo-700"
                              >
                                Aprovar
                              </button>
                              <button 
                                onClick={() => handleRejectRequest(req.id)}
                                className="flex-1 bg-white border border-slate-300 text-slate-600 text-xs py-1 rounded hover:bg-slate-50"
                              >
                                Rejeitar
                              </button>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}

            <div className="flex items-center gap-3 pl-6 border-l border-slate-200">
              <div className="text-right hidden sm:block">
                <div className="text-sm font-bold text-slate-800">{currentUser.name}</div>
                <div className="text-xs text-slate-500">{currentUser.role === 'LEADER' ? 'Líder da Equipe' : 'Colaborador'}</div>
              </div>
              <img src={currentUser.avatar} alt="User" className="w-9 h-9 rounded-full border border-slate-200 shadow-sm" />
            </div>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 p-6 overflow-hidden flex flex-col bg-slate-50">
          <div className="flex-1 h-full">
            {viewMode === 'CALENDAR' ? (
              <Calendar 
                tasks={tasks} 
                currentUser={currentUser}
                onAddTask={handleAddTask}
                onEditTask={handleEditTask}
              />
            ) : (
              <TaskListView 
                tasks={tasks}
                currentUser={currentUser}
                onEditTask={handleEditTask}
              />
            )}
          </div>
        </div>
      </main>

      <TaskModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        onRequestTransfer={handleRequestTransfer}
        initialTask={selectedTask}
        selectedDate={selectedDate}
        currentUser={currentUser}
      />
    </div>
  );
};

export default App;

export type Role = 'LEADER' | 'MEMBER';

export type TaskStatus = 'TODO' | 'IN_PROGRESS' | 'DONE';

export type Priority = 'LOW' | 'MEDIUM' | 'HIGH';

export interface User {
  id: string;
  name: string;
  email: string;
  role: Role;
  avatar: string;
  isPresent?: boolean; // For attendance tracking
}

export interface Task {
  id: string;
  title: string;
  description: string;
  assigneeId: string;
  date: Date; // Normalized to midnight
  startTime?: string; // Format "HH:mm"
  endTime?: string;   // Format "HH:mm"
  status: TaskStatus;
  priority: Priority;
}

export interface TransferRequest {
  id: string;
  taskId: string;
  requesterId: string;
  originalAssigneeId: string;
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
  taskTitle: string;
  requesterName: string;
}

export interface AlertPeriod {
  id: string;
  startDate: Date;
  endDate: Date;
  label: string;
  type: 'CLOSING' | 'SCALE'; // Fechamento or Escala
}

// Helper to keep dates consistent
export const normalizeDate = (date: Date): Date => {
  const newDate = new Date(date);
  newDate.setHours(0, 0, 0, 0);
  return newDate;
};

import React, { useState } from 'react';
import { 
  startOfMonth, endOfMonth, startOfWeek, endOfWeek, 
  eachDayOfInterval, isSameMonth, isSameDay, addMonths, subMonths, 
  format, isToday, isWithinInterval 
} from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { ChevronLeft, ChevronRight, Plus, AlertTriangle } from 'lucide-react';
import { Task, User, normalizeDate, AlertPeriod } from '../types';
import { STATUS_COLORS } from '../constants';

interface CalendarProps {
  tasks: Task[];
  users: User[];
  alertPeriods: AlertPeriod[];
  currentUser: User;
  onAddTask: (date: Date) => void;
  onEditTask: (task: Task) => void;
}

const Calendar: React.FC<CalendarProps> = ({ tasks, users, alertPeriods, currentUser, onAddTask, onEditTask }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const firstDayOfMonth = startOfMonth(currentDate);
  const lastDayOfMonth = endOfMonth(currentDate);
  const startDate = startOfWeek(firstDayOfMonth); 
  const endDate = endOfWeek(lastDayOfMonth);

  const days = eachDayOfInterval({ start: startDate, end: endDate });

  const nextMonth = () => setCurrentDate(addMonths(currentDate, 1));
  const prevMonth = () => setCurrentDate(subMonths(currentDate, 1));
  const goToToday = () => setCurrentDate(new Date());

  const getTasksForDay = (date: Date) => {
    return tasks
      .filter(task => isSameDay(normalizeDate(task.date), normalizeDate(date)))
      .sort((a, b) => (a.startTime || '').localeCompare(b.startTime || ''));
  };

  const getAlertForDay = (date: Date) => {
    return alertPeriods.find(period => 
      isWithinInterval(normalizeDate(date), { 
        start: normalizeDate(period.startDate), 
        end: normalizeDate(period.endDate) 
      })
    );
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">

      {/* Calendar Header */}
      <div className="flex-none flex items-center justify-between px-6 py-4 border-b border-slate-100 bg-white z-10">
        <div className="flex items-center gap-4">
          <h2 className="text-2xl font-bold text-slate-800 capitalize">
            {format(currentDate, 'MMMM yyyy', { locale: ptBR })}
          </h2>
          <div className="flex items-center bg-slate-100 rounded-lg p-1">
            <button onClick={prevMonth} className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-slate-600">
              <ChevronLeft size={20} />
            </button>
            <button onClick={nextMonth} className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-slate-600">
              <ChevronRight size={20} />
            </button>
          </div>
        </div>

        <button 
          onClick={goToToday}
          className="px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-200 hover:bg-slate-50 hover:border-slate-300 rounded-lg transition-colors"
        >
          Hoje
        </button>
      </div>

      {/* Days of Week Header */}
      <div className="flex-none grid grid-cols-7 border-b border-slate-100 bg-slate-50">
        {['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'].map((day) => (
          <div key={day} className="py-3 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">
            {day}
          </div>
        ))}
      </div>

      {/* Calendar Grid - Scrollable Area */}
      <div className="flex-1 overflow-y-auto custom-scrollbar">
        <div className="grid grid-cols-7 min-h-full auto-rows-[minmax(120px,1fr)] bg-slate-100 gap-[1px]">
          {days.map((day) => {
            const dayTasks = getTasksForDay(day);
            const isCurrentMonth = isSameMonth(day, currentDate);
            const isDayToday = isToday(day);
            const alert = getAlertForDay(day);

            return (
              <div 
                key={day.toISOString()} 
                className={`
                  relative flex flex-col p-2 group transition-colors min-h-[140px]
                  ${!isCurrentMonth ? 'bg-slate-50/50' : 'bg-white'}
                  ${alert ? (alert.type === 'CLOSING' ? 'bg-red-50/70' : 'bg-orange-50/70') : ''}
                `}
              >
                {/* Alert Background Label */}
                {alert && (
                   <div className={`absolute top-0 left-0 w-full h-1 ${alert.type === 'CLOSING' ? 'bg-red-400' : 'bg-orange-400'}`}></div>
                )}

                {/* Day Number */}
                <div className="flex justify-between items-start mb-1">
                  <span className={`
                    text-sm font-medium w-7 h-7 flex items-center justify-center rounded-full z-10
                    ${isDayToday 
                      ? 'bg-indigo-600 text-white' 
                      : isCurrentMonth ? 'text-slate-700' : 'text-slate-400'}
                  `}>
                    {format(day, 'd')}
                  </span>

                   {/* Alert Icon */}
                   {alert && (
                     <div className="flex items-center gap-1">
                       <span className={`text-[10px] font-bold uppercase tracking-tighter ${alert.type === 'CLOSING' ? 'text-red-600' : 'text-orange-600'}`}>
                         {alert.label}
                       </span>
                       <AlertTriangle size={12} className={alert.type === 'CLOSING' ? 'text-red-500' : 'text-orange-500'} />
                     </div>
                   )}

                  {/* Add Button */}
                  <button 
                    onClick={() => onAddTask(day)}
                    className="opacity-0 group-hover:opacity-100 p-1 text-indigo-600 hover:bg-indigo-50 rounded transition-all"
                    title="Nova Demanda"
                  >
                    <Plus size={16} />
                  </button>
                </div>

                {/* Tasks List */}
                <div className="flex flex-col gap-1 overflow-y-auto max-h-[120px] custom-scrollbar z-0">
                  {dayTasks.map(task => {
                    const assignee = users.find(u => u.id === task.assigneeId);

                    return (
                      <button
                        key={task.id}
                        onClick={(e) => {
                          e.stopPropagation();
                          onEditTask(task);
                        }}
                        className={`
                          text-left text-[10px] p-1.5 rounded-md border shadow-sm transition-transform hover:scale-[1.02]
                          ${STATUS_COLORS[task.status]}
                        `}
                      >
                        <div className="flex justify-between items-center mb-0.5 opacity-75">
                           <span>{task.startTime || '??:??'}</span>
                        </div>
                        <div className="font-semibold truncate leading-tight mb-0.5">{task.title}</div>
                        <div className="flex items-center justify-between opacity-80">
                          {assignee && (
                            <div className="flex items-center gap-1">
                               <img src={assignee.avatar} alt="" className="w-3 h-3 rounded-full" />
                               <span className="truncate max-w-[40px]">{assignee.name.split(' ')[0]}</span>
                            </div>
                          )}
                        </div>
                      </button>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Calendar;

import React from 'react';
import { Task, User, TaskStatus } from '../types';
import { STATUS_LABELS, STATUS_COLORS } from '../constants';
import { isSameDay } from 'date-fns';
import { PieChart, List, UserCheck, AlertCircle } from 'lucide-react';

interface DashboardViewProps {
  tasks: Task[];
  users: User[];
  currentDate?: Date; // Default to today
}

const DashboardView: React.FC<DashboardViewProps> = ({ tasks, users, currentDate = new Date() }) => {
  const todayTasks = tasks.filter(t => isSameDay(new Date(t.date), currentDate));

  const stats = {
    TODO: todayTasks.filter(t => t.status === 'TODO'),
    IN_PROGRESS: todayTasks.filter(t => t.status === 'IN_PROGRESS'),
    DONE: todayTasks.filter(t => t.status === 'DONE'),
  };

  const total = todayTasks.length;
  const presentMembers = users.filter(u => u.isPresent !== false); // Default everyone present for demo logic

  return (
    <div className="bg-slate-50 h-full overflow-y-auto custom-scrollbar p-6 space-y-6">
      <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
        <PieChart className="text-indigo-600" /> Painel de Indicadores (Hoje)
      </h2>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200">
           <div className="text-sm text-slate-500 mb-1">Total Demandas</div>
           <div className="text-3xl font-bold text-slate-800">{total}</div>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-l-4 border-l-slate-400 border-slate-200">
           <div className="text-sm text-slate-500 mb-1">Não Iniciado</div>
           <div className="text-3xl font-bold text-slate-600">{stats.TODO.length}</div>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-l-4 border-l-amber-400 border-slate-200">
           <div className="text-sm text-slate-500 mb-1">Em Andamento</div>
           <div className="text-3xl font-bold text-amber-600">{stats.IN_PROGRESS.length}</div>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-l-4 border-l-emerald-400 border-slate-200">
           <div className="text-sm text-slate-500 mb-1">Concluídas</div>
           <div className="text-3xl font-bold text-emerald-600">{stats.DONE.length}</div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Activity Report */}
        <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
          <div className="p-4 border-b border-slate-100 font-bold text-slate-700 flex items-center gap-2">
            <List size={18} /> Detalhamento de Atividades
          </div>
          <div className="p-4 overflow-y-auto max-h-96">
            {todayTasks.length === 0 ? (
               <div className="text-center text-slate-400 py-8">Sem atividades hoje.</div>
            ) : (
               <div className="space-y-4">
                 {(Object.keys(stats) as TaskStatus[]).map(status => {
                    const statusTasks = stats[status];
                    if (statusTasks.length === 0) return null;
                    return (
                       <div key={status} className="space-y-2">
