import React, { useState } from 'react';
import { X, AlertTriangle, Calendar } from 'lucide-react';
import { AlertPeriod, normalizeDate } from '../types';

interface AlertModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (alert: AlertPeriod) => void;
}

const AlertModal: React.FC<AlertModalProps> = ({ isOpen, onClose, onSave }) => {
  const [label, setLabel] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [type, setType] = useState<'CLOSING' | 'SCALE'>('CLOSING');

  if (!isOpen) return null;

  const handleSave = () => {
    if (!label || !startDate || !endDate) return;

    const [sy, sm, sd] = startDate.split('-').map(Number);
    const [ey, em, ed] = endDate.split('-').map(Number);

    const newAlert: AlertPeriod = {
      id: crypto.randomUUID(),
      startDate: normalizeDate(new Date(sy, sm - 1, sd)),
      endDate: normalizeDate(new Date(ey, em - 1, ed)),
      label,
      type
    };
    onSave(newAlert);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden">
        <div className="bg-orange-50 border-b border-orange-100 px-6 py-4 flex justify-between items-center">
          <h2 className="text-lg font-bold text-orange-800 flex items-center gap-2">
             <AlertTriangle size={20} /> Criar Alerta
          </h2>
          <button onClick={onClose} className="text-orange-400 hover:text-orange-600">
            <X size={20} />
          </button>
        </div>

        <div className="p-6 space-y-4">
           <div>
             <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Motivo</label>
             <input 
               type="text" 
               value={label}
               onChange={e => setLabel(e.target.value)}
               placeholder="Ex: Fechamento Mensal"
               className="w-full px-3 py-2 border border-slate-300 rounded text-sm"
             />
           </div>

           <div>
             <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Tipo</label>
             <div className="flex gap-2">
                <button 
                  onClick={() => setType('CLOSING')}
                  className={`flex-1 py-2 text-sm font-medium rounded border ${type === 'CLOSING' ? 'bg-red-100 text-red-700 border-red-300' : 'bg-white text-slate-600 border-slate-200'}`}
                >
                   Fechamento
                </button>
                <button 
                  onClick={() => setType('SCALE')}
                  className={`flex-1 py-2 text-sm font-medium rounded border ${type === 'SCALE' ? 'bg-orange-100 text-orange-700 border-orange-300' : 'bg-white text-slate-600 border-slate-200'}`}
                >
                   Escalas
                </button>
             </div>
           </div>

           <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Início</label>
                <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded text-sm"/>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Fim</label>
                <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded text-sm"/>
              </div>
           </div>

           <button 
             onClick={handleSave}
             className="w-full bg-orange-600 hover:bg-orange-700 text-white font-medium py-2 rounded shadow-sm mt-2"
           >
             Definir Período
           </button>
        </div>
      </div>
    </div>
  );
};

export default AlertModal;

import React from 'react';
