import React, { useState } from 'react';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import LoginScreen from './components/LoginScreen';
import TaskListView from './components/TaskListView';
import TeamModal from './components/TeamModal';
import AlertModal from './components/AlertModal';
import DashboardView from './components/DashboardView';
import PresencialModal from './components/PresencialModal';

import { User, Task, TransferRequest, AlertPeriod } from './types';
import { USERS, INITIAL_TASKS } from './constants';
import { Layout, LogOut, CheckSquare, List, Calendar as CalendarIcon, Bell, Settings, PieChart, MapPin, AlertTriangle } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [tasks, setTasks] = useState<Task[]>(INITIAL_TASKS);
  const [teamUsers, setTeamUsers] = useState<User[]>(USERS);
  const [alertPeriods, setAlertPeriods] = useState<AlertPeriod[]>([]);

  const [viewMode, setViewMode] = useState<'CALENDAR' | 'LIST' | 'DASHBOARD'>('CALENDAR');

  // Requests System
  const [transferRequests, setTransferRequests] = useState<TransferRequest[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);

  // Modals State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [isAlertModalOpen, setIsAlertModalOpen] = useState(false);
  const [isPresencialModalOpen, setIsPresencialModalOpen] = useState(false);

  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  // Handlers
  const handleLogin = (user: User) => {
    setCurrentUser(user);
    // In a real app with Google Auth:
    // const googleLogin = useGoogleLogin({ ... });
    // This is where you would handle the auth code.
  };

  const handleLogout = () => {
    setCurrentUser(null);
    // Note: We do NOT clear requests here, so the state persists for the session demonstration
  };

  const handleAddTask = (date: Date) => {
    setSelectedDate(date);
    setSelectedTask(null);
    setIsModalOpen(true);
  };

  const handleEditTask = (task: Task) => {
    setSelectedTask(task);
    setSelectedDate(task.date);
    setIsModalOpen(true);
  };

  const handleSaveTask = (taskToSave: Task) => {
    setTasks(prev => {
      const exists = prev.find(t => t.id === taskToSave.id);
      if (exists) {
        return prev.map(t => t.id === taskToSave.id ? taskToSave : t);
      }
      return [...prev, taskToSave];
    });
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
  };

  const handleRequestTransfer = (taskId: string, newAssigneeId: string) => {
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;

    const newRequest: TransferRequest = {
      id: crypto.randomUUID(),
      taskId,
      requesterId: newAssigneeId,
      originalAssigneeId: task.assigneeId,
      status: 'PENDING',
      taskTitle: task.title,
      requesterName: teamUsers.find(u => u.id === newAssigneeId)?.name || 'Unknown',
    };

    setTransferRequests(prev => [...prev, newRequest]);
    alert('Solicitação enviada para o Líder da equipe!');
  };

  const handleApproveRequest = (request: TransferRequest) => {
    setTasks(prev => prev.map(t => {
      if (t.id === request.taskId) {
        return { ...t, assigneeId: request.requesterId };
      }
      return t;
    }));
    setTransferRequests(prev => prev.filter(r => r.id !== request.id));
  };

  const handleRejectRequest = (requestId: string) => {
    setTransferRequests(prev => prev.filter(r => r.id !== requestId));
  };

  const handleAddUser = (newUser: User) => {
    setTeamUsers(prev => [...prev, newUser]);
  };

  const handleRemoveUser = (userId: string) => {
    setTeamUsers(prev => prev.filter(u => u.id !== userId));
  };

  const handleSaveAlert = (newAlert: AlertPeriod) => {
    setAlertPeriods(prev => [...prev, newAlert]);
  };

  if (!currentUser) {
    return <LoginScreen onLogin={handleLogin} />;
  }

  const isLeader = currentUser.role === 'LEADER';

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">

      {/* Sidebar Navigation */}
      <aside className="w-16 lg:w-64 bg-slate-900 text-slate-300 flex flex-col flex-shrink-0 shadow-xl z-20 transition-all">
        <div className="p-4 lg:p-6 border-b border-slate-800 flex items-center justify-center lg:justify-start gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg text-white">
             <Layout size={24} />
          </div>
          <h1 className="hidden lg:block text-xl font-bold tracking-tight text-white">GestorPro</h1>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          <button onClick={() => setViewMode('CALENDAR')} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'CALENDAR' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <CheckSquare size={20} />
            <span className="hidden lg:inline">Minhas Demandas</span>
          </button>

          <button onClick={() => setViewMode('DASHBOARD')} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'DASHBOARD' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <PieChart size={20} />
            <span className="hidden lg:inline">Indicadores</span>
          </button>

          <button onClick={() => setIsPresencialModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
            <MapPin size={20} />
            <span className="hidden lg:inline">Escala Presencial</span>
          </button>

          {isLeader && (
            <>
              <div className="my-2 border-t border-slate-800"></div>
              <button onClick={() => setIsTeamModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
                <Settings size={20} />
                <span className="hidden lg:inline">Gerenciar Equipe</span>
              </button>
              <button onClick={() => setIsAlertModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-orange-400">
                <AlertTriangle size={20} />
                <span className="hidden lg:inline">Criar Alerta</span>
              </button>
            </>
          )}
        </nav>

        <div className="p-4 border-t border-slate-800 bg-slate-950">
          <button 
            onClick={handleLogout}
            className="w-full flex items-center justify-center lg:justify-start gap-2 text-slate-400 hover:text-white hover:bg-slate-800 p-2 rounded-lg transition-colors"
          >
            <LogOut size={20} />
            <span className="hidden lg:inline text-sm font-medium">Sair</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        {/* Top Bar */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shadow-sm z-10">

          {/* View Toggles */}
          <div className="flex bg-slate-100 p-1 rounded-lg">
            <button
              onClick={() => setViewMode('CALENDAR')}
              className={`flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-md transition-all ${
                viewMode === 'CALENDAR' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              <CalendarIcon size={16} />
              <span className="hidden sm:inline">Calendário</span>
            </button>
            <button
              onClick={() => setViewMode('LIST')}
              className={`flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-md transition-all ${
                viewMode === 'LIST' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              <List size={16} />
              <span className="hidden sm:inline">Lista</span>
            </button>
          </div>

          <div className="flex items-center gap-6">

            {/* Notifications (Leader Only) */}
            {isLeader && (
              <div className="relative">
                <button 
                  onClick={() => setShowNotifications(!showNotifications)}
                  className="relative p-2 text-slate-500 hover:bg-slate-100 rounded-full transition-colors"
                >
                  <Bell size={20} />
                  {transferRequests.length > 0 && (
                    <span className="absolute top-1 right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white"></span>
                  )}
                </button>

                {showNotifications && (
                  <div className="absolute right-0 mt-2 w-80 bg-white border border-slate-200 shadow-xl rounded-xl z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-100">
                    <div className="px-4 py-3 border-b border-slate-100 bg-slate-50 font-bold text-sm text-slate-700">
                      Solicitações ({transferRequests.length})
                    </div>
                    <div className="max-h-60 overflow-y-auto">
                      {transferRequests.length === 0 ? (
                        <div className="p-4 text-center text-xs text-slate-500">Nenhuma solicitação pendente.</div>
                      ) : (
                        transferRequests.map(req => (
                          <div key={req.id} className="p-3 border-b border-slate-50 hover:bg-slate-50">
                            <p className="text-xs text-slate-500 mb-1">
                              <span className="font-bold text-slate-700">{req.requesterName}</span> deseja assumir:
                            </p>
                            <p className="text-sm font-semibold text-indigo-700 mb-2 truncate">"{req.taskTitle}"</p>
                            <div className="flex gap-2">
                              <button 
                                onClick={() => handleApproveRequest(req)}
                                className="flex-1 bg-indigo-600 text-white text-xs py-1 rounded hover:bg-indigo-700"
                              >
                                Aprovar
                              </button>
                              <button 
                                onClick={() => handleRejectRequest(req.id)}
                                className="flex-1 bg-white border border-slate-300 text-slate-600 text-xs py-1 rounded hover:bg-slate-50"
                              >
                                Rejeitar
                              </button>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}

            <div className="flex items-center gap-3 pl-6 border-l border-slate-200">
              <div className="text-right hidden sm:block">
                <div className="text-sm font-bold text-slate-800">{currentUser.name}</div>
                <div className="text-xs text-slate-500">{currentUser.role === 'LEADER' ? 'Líder' : 'Membro'}</div>
              </div>
              <img src={currentUser.avatar} alt="User" className="w-9 h-9 rounded-full border border-slate-200 shadow-sm" />
            </div>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 p-4 lg:p-6 overflow-hidden flex flex-col bg-slate-50">
          <div className="flex-1 h-full min-h-0">
            {viewMode === 'CALENDAR' ? (
              <Calendar 
                tasks={tasks} 
                users={teamUsers}
                alertPeriods={alertPeriods}
                currentUser={currentUser}
                onAddTask={handleAddTask}
                onEditTask={handleEditTask}
              />
            ) : viewMode === 'LIST' ? (
              <TaskListView 
                tasks={tasks}
                currentUser={currentUser}
                onEditTask={handleEditTask}
              />
            ) : (
              <DashboardView 
                tasks={tasks}
                users={teamUsers}
              />
            )}
          </div>
        </div>
      </main>

      {/* Modals */}
      <TaskModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        onRequestTransfer={handleRequestTransfer}
        initialTask={selectedTask}
        selectedDate={selectedDate}
        currentUser={currentUser}
      />

      <TeamModal 
        isOpen={isTeamModalOpen}
        onClose={() => setIsTeamModalOpen(false)}
        users={teamUsers}
        onAddUser={handleAddUser}
        onRemoveUser={handleRemoveUser}
      />

      <AlertModal 
        isOpen={isAlertModalOpen}
        onClose={() => setIsAlertModalOpen(false)}
        onSave={handleSaveAlert}
      />

      <PresencialModal 
        isOpen={isPresencialModalOpen}
        onClose={() => setIsPresencialModalOpen(false)}
        users={teamUsers}
      />
    </div>
  );
};

export default App;

