import { Task, User, AlertPeriod } from '../types';

// This will be set by the user in the UI
let API_URL = localStorage.getItem('GESTOR_PRO_API_URL') || '';

export const setApiUrl = (url: string) => {
  API_URL = url;
  localStorage.setItem('GESTOR_PRO_API_URL', url);
};

export const getApiUrl = () => API_URL;

const sendRequest = async (action: string, data?: any) => {
  if (!API_URL) throw new Error('API URL not configured');

  // Google Apps Script requires a specific way to handle POST for CORS in some environments,
  // typically sending text/plain prevents preflight options issues in simple scripts.
  const options: RequestInit = {
    method: 'POST',
    body: JSON.stringify(data || {}),
  };

  // If we are just reading, we can technically use GET, but sticking to one method 
  // with a query param for action is robust for GAS Web Apps.
  // Actually, for "doPost" in GAS to capture data, we usually send it as a POST.
  // However, fetching data is often easier via GET to avoid body payload parsing issues on read.

  if (action === 'read') {
    const response = await fetch(`${API_URL}?action=read`);
    return response.json();
  } else {
    // For writes, we use the Web App URL with the action parameter for routing consistency, 
    // but pass data in body.
    const response = await fetch(`${API_URL}?action=${action}`, {
      method: 'POST',
      body: JSON.stringify(data),
      // 'Content-Type': 'text/plain' is often needed for GAS to avoid CORS preflight blocks 
      // when 'Anyone' access is set.
      headers: { 'Content-Type': 'text/plain' } 
    });
    return response.json();
  }
};

export const api = {
  sync: async (): Promise<{ tasks: any[], users: any[], alerts: any[] }> => {
    return sendRequest('read');
  },

  saveTask: async (task: Task) => {
    return sendRequest('saveTask', {
      ...task,
      date: task.date.toISOString(), // Ensure dates are strings
    });
  },

  deleteTask: async (taskId: string) => {
    return sendRequest('deleteTask', { id: taskId });
  },

  saveUser: async (user: User) => {
    return sendRequest('saveUser', user);
  },

  deleteUser: async (userId: string) => {
    return sendRequest('deleteUser', { id: userId });
  },

  saveAlert: async (alert: AlertPeriod) => {
    return sendRequest('saveAlert', {
      ...alert,
      startDate: alert.startDate.toISOString(),
      endDate: alert.endDate.toISOString(),
    });
  }
};

import React, { useState, useEffect, useRef } from 'react';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import TaskListView from './components/TaskListView';
import TeamModal from './components/TeamModal';
import AlertModal from './components/AlertModal';
import DashboardView from './components/DashboardView';
import PresencialModal from './components/PresencialModal';

import { User, Task, AlertPeriod, normalizeDate } from './types';
import { USERS, INITIAL_TASKS } from './constants';
import { api, setApiUrl, getApiUrl } from './services/api';
import { Layout, CheckSquare, List, Calendar as CalendarIcon, Settings, PieChart, MapPin, AlertTriangle, Users, User as UserIcon, Database, Link as LinkIcon, RefreshCw, Loader2 } from 'lucide-react';

const App: React.FC = () => {
  // Config State
  const [isConfigOpen, setIsConfigOpen] = useState(!getApiUrl());
  const [apiUrlInput, setApiUrlInput] = useState(getApiUrl());
  const [isSyncing, setIsSyncing] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'DISCONNECTED' | 'CONNECTED' | 'ERROR'>('DISCONNECTED');

  const [currentUser, setCurrentUser] = useState<User>(USERS[0]); 

  // Data State (Initially empty if connecting to DB, or fallback to constants for demo until connected)
  const [tasks, setTasks] = useState<Task[]>([]);
  const [teamUsers, setTeamUsers] = useState<User[]>([]);
  const [alertPeriods, setAlertPeriods] = useState<AlertPeriod[]>([]);

  const [viewMode, setViewMode] = useState<'CALENDAR' | 'LIST' | 'DASHBOARD'>('CALENDAR');
  const [filterScope, setFilterScope] = useState<'TEAM' | 'ME'>('TEAM');

  // Modals State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [isAlertModalOpen, setIsAlertModalOpen] = useState(false);
  const [isPresencialModalOpen, setIsPresencialModalOpen] = useState(false);
  const [isUserSwitcherOpen, setIsUserSwitcherOpen] = useState(false);

  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  // --- API & SYNC LOGIC ---

  const fetchData = async () => {
    if (!getApiUrl()) return;

    try {
      setIsSyncing(true);
      const data = await api.sync();

      // Parse dates from strings back to Date objects
      const parsedTasks: Task[] = data.tasks.map((t: any) => ({
        ...t,
        date: new Date(t.date),
      }));

      const parsedAlerts: AlertPeriod[] = data.alerts.map((a: any) => ({
        ...a,
        startDate: new Date(a.startDate),
        endDate: new Date(a.endDate),
      }));

      // Users come with presencialDates which might be JSON string or array depending on sheet parsing
      const parsedUsers: User[] = data.users.map((u: any) => ({
        ...u,
        // Ensure presencialDates is an array
        presencialDates: Array.isArray(u.presencialDates) ? u.presencialDates : []
      }));

      setTasks(parsedTasks);
      setTeamUsers(parsedUsers.length > 0 ? parsedUsers : USERS); // Fallback to avoid empty user list on first load
      setAlertPeriods(parsedAlerts);

      // Update current user reference if it exists in the fetched list
      const foundCurrent = parsedUsers.find(u => u.id === currentUser.id);
      if (foundCurrent) {
        setCurrentUser(foundCurrent);
      } else if (parsedUsers.length > 0 && !teamUsers.find(u => u.id === currentUser.id)) {
        setCurrentUser(parsedUsers[0]);
      }

      setConnectionStatus('CONNECTED');
    } catch (error) {
      console.error("Sync Error", error);
      setConnectionStatus('ERROR');
    } finally {
      setIsSyncing(false);
    }
  };

  // Initial Load & Polling
  useEffect(() => {
    if (getApiUrl()) {
      fetchData(); // Fetch immediately

      const intervalId = setInterval(() => {
        fetchData(); // Poll every 5 seconds
      }, 5000);

      return () => clearInterval(intervalId);
    } else {
      // If no API, load dummy data so app looks usable
      setTasks(INITIAL_TASKS);
      setTeamUsers(USERS);
