    if (getApiUrl()) {
      await api.saveAlert(newAlert);
      fetchData();
    }
  };

  const handleTogglePresence = async (userId: string, dateStr: string) => {
     let updatedUser: User | undefined;

     setTeamUsers(prev => prev.map(user => {
       if (user.id === userId) {
         const isPresent = user.presencialDates.includes(dateStr);
         let newDates;
         if (isPresent) {
            newDates = user.presencialDates.filter(d => d !== dateStr);
         } else {
            newDates = [...user.presencialDates, dateStr];
         }
         updatedUser = { ...user, presencialDates: newDates };
         return updatedUser;
       }
       return user;
     }));

     if (updatedUser && getApiUrl()) {
       await api.saveUser(updatedUser);
       // We don't force immediate fetch here to keep UI snappy, polling will catch it
     }
  };

  const isLeader = currentUser.role === 'LEADER';

  // Filter tasks based on scope
  const displayedTasks = tasks.filter(task => {
