                        placeholder="https://script.google.com/macros/s/..."
                        className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500"
                      />
                   </div>
                 </div>
              </div>

              <div className="flex gap-3">
                 <button 
                   onClick={() => setIsConfigOpen(false)}
                   className="flex-1 py-2 text-sm font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
                 >
                   Usar Offline (Demo)
                 </button>
                 <button 
                   onClick={handleConnect}
                   disabled={!apiUrlInput || isSyncing}
                   className="flex-1 py-2 text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-lg shadow-indigo-200 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                 >
                   {isSyncing ? <Loader2 size={16} className="animate-spin" /> : 'Conectar e Sincronizar'}
                 </button>
              </div>

              <div className="mt-6 pt-6 border-t border-slate-100 text-xs text-slate-400 text-left">
                 <p className="mb-2 font-bold">Instruções:</p>
                 <ol className="list-decimal pl-4 space-y-1">
                    <li>No editor de script, clique em <strong>Executar</strong> para autorizar o acesso.</li>
                    <li>Vá em <strong>Implantar</strong> {'>'} <strong>Nova implantação</strong>.</li>
                    <li>Em "Quem pode acessar", selecione <strong>Qualquer pessoa</strong>.</li>
                    <li>Copie a <strong>NOVA URL</strong> gerada e cole acima.</li>
                 </ol>
              </div>
           </div>
        </div>
      )}

      {/* Other Modals */}
      <TaskModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        onRequestTransfer={() => {}} 
        initialTask={selectedTask}
        selectedDate={selectedDate}
        currentUser={currentUser}
      />

      <TeamModal 
        isOpen={isTeamModalOpen}
        onClose={() => setIsTeamModalOpen(false)}
        users={teamUsers}
        onAddUser={handleAddUser}
        onRemoveUser={handleRemoveUser}
      />

      <AlertModal 
        isOpen={isAlertModalOpen}
        onClose={() => setIsAlertModalOpen(false)}
        onSave={handleSaveAlert}
      />

      <PresencialModal 
        isOpen={isPresencialModalOpen}
        onClose={() => setIsPresencialModalOpen(false)}
        users={teamUsers}
        onTogglePresence={handleTogglePresence}
      />
    </div>
  );
};

export default App;

payload.text:
Geralmente esse erro acontece por dois motivos:
1.  **Abas Inexistentes:** O script tenta ler as abas "Tasks", "Users", "Alerts" e se elas não existirem exatamente com esse nome (maiúsculas/minúsculas importam), o script quebra (Erro 500) e o front recebe um erro.
2.  **URL Errada:** Você pode estar usando a URL de desenvolvimento (termina em `/dev`) ao invés da executável (termina em `/exec`).

Vou atualizar o código do **Front-end** para nos dar mais detalhes do erro no console, e vou te passar um **código novo para o Apps Script** que é "à prova de falhas" (ele cria as abas sozinho se elas não existirem).

### 1. Atualize o Código do Apps Script (Google Sheets)

Apague todo o código que está lá e cole este novo. Ele tem uma proteção para criar as abas automaticamente.

```javascript
function doGet(e) {
  return handleRequest(e);
}

function doPost(e) {
  return handleRequest(e);
}

function handleRequest(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const action = e && e.parameter ? e.parameter.action : 'read'; // Fallback seguro

    // Ler Dados
    if (action === 'read') {
      const data = {
        tasks: readSheet(getOrCreateSheet(ss, 'Tasks')),
        users: readSheet(getOrCreateSheet(ss, 'Users')),
        alerts: readSheet(getOrCreateSheet(ss, 'Alerts'))
      };
      return responseJSON(data);
    }

    // Ações de Escrita
    const body = e.postData ? JSON.parse(e.postData.contents) : {};

    if (action === 'saveTask') {
      saveRow(getOrCreateSheet(ss, 'Tasks'), body);
    } else if (action === 'deleteTask') {
      deleteRow(getOrCreateSheet(ss, 'Tasks'), body.id);
    } else if (action === 'saveUser') {
      saveRow(getOrCreateSheet(ss, 'Users'), body);
    } else if (action === 'deleteUser') {
      deleteRow(getOrCreateSheet(ss, 'Users'), body.id);
    } else if (action === 'saveAlert') {
      saveRow(getOrCreateSheet(ss, 'Alerts'), body);
    }

    return responseJSON({ success: true });

  } catch (err) {
    return responseJSON({ error: err.toString() });
  } finally {
    lock.releaseLock();
  }
}

// Helper para garantir que a aba existe
function getOrCreateSheet(ss, name) {
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    // Cria cabeçalhos padrão dependendo do nome
    if (name === 'Tasks') sheet.appendRow(['id', 'title', 'description', 'assigneeId', 'date', 'startTime', 'endTime', 'status', 'priority']);
    if (name === 'Users') sheet.appendRow(['id', 'name', 'email', 'role', 'avatar', 'presencialDates']);
    if (name === 'Alerts') sheet.appendRow(['id', 'startDate', 'endDate', 'label', 'color']);
  }
  return sheet;
}

function readSheet(sheet) {
  const rows = sheet.getDataRange().getValues();
  if (rows.length < 2) return [];
  const headers = rows[0];
  const data = [];

  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    const obj = {};
    for (let j = 0; j < headers.length; j++) {
      let val = row[j];
      if (headers[j] === 'presencialDates' && typeof val === 'string' && val.startsWith('[')) {
        try { val = JSON.parse(val); } catch(e) {}
      }
      obj[headers[j]] = val;
    }
    data.push(obj);
  }
  return data;
}

function saveRow(sheet, data) {
  const rows = sheet.getDataRange().getValues();
  // Se estiver vazio (só cabeçalho recém criado), pegamos as chaves do objeto
  let headers = rows.length > 0 ? rows[0] : Object.keys(data);

  // Garantir que temos cabeçalhos se a planilha estiver zerada
  if (rows.length === 0) {
    headers = Object.keys(data);
    sheet.appendRow(headers);
  }

  const rowData = headers.map(h => {
    let val = data[h];
    if (Array.isArray(val)) return JSON.stringify(val);
    if (val && typeof val === 'object' && val.toISOString) return val.toISOString(); // Handle Dates likely
    return val;
  });

  const idIndex = headers.indexOf('id');
  let rowIndex = -1;

  if (idIndex > -1 && rows.length > 1) {
    for (let i = 1; i < rows.length; i++) {
      if (rows[i][idIndex] == data.id) {
        rowIndex = i + 1;
        break;
      }
    }
  }

  if (rowIndex > -1) {
    sheet.getRange(rowIndex, 1, 1, rowData.length).setValues([rowData]);
  } else {
    sheet.appendRow(rowData);
  }
}

function deleteRow(sheet, id) {
  const rows = sheet.getDataRange().getValues();
  const idIndex = rows[0].indexOf('id');
  if (idIndex === -1) return;

  for (let i = 1; i < rows.length; i++) {
    if (rows[i][idIndex] == id) {
      sheet.deleteRow(i + 1);
      return;
    }
  }
}

function responseJSON(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}
```

**IMPORTANTE:** Após colar o código novo, clique em **Implantar > Nova implantação** novamente para gerar uma URL atualizada. Certifique-se que o final da URL é `/exec` e não `/dev`.

### 2. Atualização do Frontend

Vou atualizar o serviço de API para lidar melhor com respostas de erro (caso o Google retorne um HTML de erro em vez de JSON) e facilitar o diagnóstico.

