import { Task, User, AlertPeriod } from '../types';

// This will be set by the user in the UI
let API_URL = localStorage.getItem('GESTOR_PRO_API_URL') || '';

export const setApiUrl = (url: string) => {
  // Simple validation to warn about dev URLs
  if (url.includes('/dev')) {
    console.warn("Warning: You are using a deployment '/dev' URL. This usually fails due to CORS/Auth. Use '/exec'.");
  }
  API_URL = url;
  localStorage.setItem('GESTOR_PRO_API_URL', url);
};

export const getApiUrl = () => API_URL;

const sendRequest = async (action: string, data?: any) => {
  if (!API_URL) throw new Error('API URL not configured');

  try {
    let response;

    if (action === 'read') {
      response = await fetch(`${API_URL}?action=read`);
    } else {
      response = await fetch(`${API_URL}?action=${action}`, {
        method: 'POST',
        body: JSON.stringify(data),
        headers: { 'Content-Type': 'text/plain' } 
      });
    }

    const text = await response.text();

    // Try parsing JSON
    try {
      const json = JSON.parse(text);
      if (json.error) {
        throw new Error("Server Error: " + json.error);
      }
      return json;
    } catch (e) {
      // If parsing fails, it's likely an HTML error page from Google (404, 500, Permission)
      console.error("API Error (Raw Response):", text);
      throw new Error("Falha na comunicação com o Google Sheets. Verifique o console para detalhes (CORS ou Permissão).");
    }

  } catch (error) {
    console.error("Network/Script Error:", error);
    throw error;
  }
};

export const api = {
  sync: async (): Promise<{ tasks: any[], users: any[], alerts: any[] }> => {
    return sendRequest('read');
  },

  saveTask: async (task: Task) => {
    return sendRequest('saveTask', {
      ...task,
      date: task.date.toISOString(),
    });
  },

  deleteTask: async (taskId: string) => {
    return sendRequest('deleteTask', { id: taskId });
  },

  saveUser: async (user: User) => {
    return sendRequest('saveUser', user);
  },

  deleteUser: async (userId: string) => {
    return sendRequest('deleteUser', { id: userId });
  },

  saveAlert: async (alert: AlertPeriod) => {
    return sendRequest('saveAlert', {
      ...alert,
      startDate: alert.startDate.toISOString(),
      endDate: alert.endDate.toISOString(),
    });
  }
};

import React, { useState, useEffect, useRef } from 'react';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import TaskListView from './components/TaskListView';
import TeamModal from './components/TeamModal';
import AlertModal from './components/AlertModal';
import DashboardView from './components/DashboardView';
import PresencialModal from './components/PresencialModal';

import { User, Task, AlertPeriod, normalizeDate } from './types';
import { USERS, INITIAL_TASKS } from './constants';
import { api, setApiUrl, getApiUrl } from './services/api';
import { Layout, CheckSquare, List, Calendar as CalendarIcon, Settings, PieChart, MapPin, AlertTriangle, Users, User as UserIcon, Database, Link as LinkIcon, RefreshCw, Loader2, XCircle } from 'lucide-react';

const App: React.FC = () => {
  // Config State
  const [isConfigOpen, setIsConfigOpen] = useState(!getApiUrl());
  const [apiUrlInput, setApiUrlInput] = useState(getApiUrl());
  const [isSyncing, setIsSyncing] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'DISCONNECTED' | 'CONNECTED' | 'ERROR'>('DISCONNECTED');
  const [configError, setConfigError] = useState<string | null>(null);

  const [currentUser, setCurrentUser] = useState<User>(USERS[0]); 

  // Data State (Initially empty if connecting to DB, or fallback to constants for demo until connected)
  const [tasks, setTasks] = useState<Task[]>([]);
  const [teamUsers, setTeamUsers] = useState<User[]>([]);
  const [alertPeriods, setAlertPeriods] = useState<AlertPeriod[]>([]);

  const [viewMode, setViewMode] = useState<'CALENDAR' | 'LIST' | 'DASHBOARD'>('CALENDAR');
  const [filterScope, setFilterScope] = useState<'TEAM' | 'ME'>('TEAM');

  // Modals State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [isAlertModalOpen, setIsAlertModalOpen] = useState(false);
  const [isPresencialModalOpen, setIsPresencialModalOpen] = useState(false);
  const [isUserSwitcherOpen, setIsUserSwitcherOpen] = useState(false);

  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  // --- API & SYNC LOGIC ---

  const fetchData = async (): Promise<boolean> => {
    if (!getApiUrl()) return false;

    try {
      setIsSyncing(true);
      const data = await api.sync();

      // Parse dates from strings back to Date objects
      const parsedTasks: Task[] = data.tasks.map((t: any) => ({
        ...t,
        date: new Date(t.date),
      }));

      const parsedAlerts: AlertPeriod[] = data.alerts.map((a: any) => ({
        ...a,
        startDate: new Date(a.startDate),
        endDate: new Date(a.endDate),
      }));

      // Users come with presencialDates which might be JSON string or array depending on sheet parsing
      const parsedUsers: User[] = data.users.map((u: any) => ({
        ...u,
        // Ensure presencialDates is an array
        presencialDates: Array.isArray(u.presencialDates) ? u.presencialDates : []
      }));

      setTasks(parsedTasks);
      setTeamUsers(parsedUsers.length > 0 ? parsedUsers : USERS); // Fallback to avoid empty user list on first load
      setAlertPeriods(parsedAlerts);

      // Update current user reference if it exists in the fetched list
      const foundCurrent = parsedUsers.find(u => u.id === currentUser.id);
      if (foundCurrent) {
        setCurrentUser(foundCurrent);
      } else if (parsedUsers.length > 0 && !teamUsers.find(u => u.id === currentUser.id)) {
        setCurrentUser(parsedUsers[0]);
      }

      setConnectionStatus('CONNECTED');
      return true;
    } catch (error) {
      console.error("Sync Error", error);
      setConnectionStatus('ERROR');
      return false;
    } finally {
      setIsSyncing(false);
    }
  };

  // Initial Load & Polling
  useEffect(() => {
    if (getApiUrl()) {
      fetchData(); // Fetch immediately

      const intervalId = setInterval(() => {
        fetchData(); // Poll every 5 seconds
      }, 5000);

      return () => clearInterval(intervalId);
    } else {
      // If no API, load dummy data so app looks usable
      setTasks(INITIAL_TASKS);
      setTeamUsers(USERS);
    }
  }, []); 

  const handleConnect = async () => {
    setConfigError(null);
    setIsSyncing(true);
    setApiUrl(apiUrlInput);

    // Attempt to fetch immediately to validate URL
    const success = await fetchData();

    if (success) {
      setIsConfigOpen(false);
    } else {
      setConfigError("Não foi possível conectar. Verifique se autorizou o script e se a permissão de acesso está definida como 'Qualquer pessoa'.");
      setConnectionStatus('ERROR');
    }
    setIsSyncing(false);
  };

  // --- HANDLERS WRAPPED WITH API ---

  const handleAddTask = (date: Date) => {
    setSelectedDate(date);
    setSelectedTask(null);
    setIsModalOpen(true);
  };

  const handleEditTask = (task: Task) => {
    setSelectedTask(task);
    setSelectedDate(task.date);
    setIsModalOpen(true);
  };

  const handleSaveTask = async (taskToSave: Task) => {
    // Optimistic Update
    setTasks(prev => {
      const exists = prev.find(t => t.id === taskToSave.id);
      if (exists) return prev.map(t => t.id === taskToSave.id ? taskToSave : t);
      return [...prev, taskToSave];
    });

    if (getApiUrl()) {
      await api.saveTask(taskToSave);
      fetchData(); // Refresh to ensure sync
    }
  };

  const handleDeleteTask = async (taskId: string) => {
    // Optimistic Update
    setTasks(prev => prev.filter(t => t.id !== taskId));

    if (getApiUrl()) {
      await api.deleteTask(taskId);
      fetchData();
    }
  };

  const handleAddUser = async (newUser: User) => {
    setTeamUsers(prev => [...prev, newUser]);
    if (getApiUrl()) {
      await api.saveUser(newUser);
      fetchData();
    }
  };

  const handleRemoveUser = async (userId: string) => {
    setTeamUsers(prev => prev.filter(u => u.id !== userId));
    if (getApiUrl()) {
      await api.deleteUser(userId);
      fetchData();
    }
  };

  const handleSaveAlert = async (newAlert: AlertPeriod) => {
    setAlertPeriods(prev => [...prev, newAlert]);
    if (getApiUrl()) {
      await api.saveAlert(newAlert);
      fetchData();
    }
  };

  const handleTogglePresence = async (userId: string, dateStr: string) => {
     let updatedUser: User | undefined;

     setTeamUsers(prev => prev.map(user => {
       if (user.id === userId) {
         const isPresent = user.presencialDates.includes(dateStr);
         let newDates;
         if (isPresent) {
            newDates = user.presencialDates.filter(d => d !== dateStr);
         } else {
            newDates = [...user.presencialDates, dateStr];
         }
         updatedUser = { ...user, presencialDates: newDates };
         return updatedUser;
       }
       return user;
     }));

     if (updatedUser && getApiUrl()) {
       await api.saveUser(updatedUser);
       // We don't force immediate fetch here to keep UI snappy, polling will catch it
     }
  };

  const isLeader = currentUser.role === 'LEADER';

  // Filter tasks based on scope
  const displayedTasks = tasks.filter(task => {
    if (filterScope === 'ME') {
      return task.assigneeId === currentUser.id;
    }
    return true; // Show all for TEAM
  });

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">

      {/* Sidebar Navigation */}
      <aside className="w-16 lg:w-64 bg-slate-900 text-slate-300 flex flex-col flex-shrink-0 shadow-xl z-20 transition-all">
        <div className="p-4 lg:p-6 border-b border-slate-800 flex items-center justify-center lg:justify-start gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg text-white">
             <Layout size={24} />
          </div>
          <h1 className="hidden lg:block text-xl font-bold tracking-tight text-white">GestorPro</h1>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          <button onClick={() => setViewMode('CALENDAR')} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'CALENDAR' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <CheckSquare size={20} />
            <span className="hidden lg:inline">Minhas Demandas</span>
          </button>

          <button onClick={() => setViewMode('DASHBOARD')} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'DASHBOARD' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <PieChart size={20} />
            <span className="hidden lg:inline">Indicadores</span>
          </button>

          <button onClick={() => setIsPresencialModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
            <MapPin size={20} />
            <span className="hidden lg:inline">Escala Presencial</span>
          </button>

          {isLeader && (
            <>
              <div className="my-2 border-t border-slate-800"></div>
              <button onClick={() => setIsTeamModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
                <Settings size={20} />
                <span className="hidden lg:inline">Gerenciar Equipe</span>
              </button>
              <button onClick={() => setIsAlertModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-orange-400">
                <AlertTriangle size={20} />
                <span className="hidden lg:inline">Criar Alerta</span>
              </button>
            </>
          )}
        </nav>

        {/* Database Config Button (Bottom) */}
        <div className="p-2 bg-slate-950">
           <button 
             onClick={() => { setIsConfigOpen(true); setConfigError(null); }}
             className="w-full flex items-center justify-center lg:justify-start gap-3 p-3 rounded-lg hover:bg-slate-800 transition-colors group"
             title={connectionStatus === 'CONNECTED' ? 'Conexão Ativa' : 'Sem Conexão'}
           >
              <div className="relative">
                 <Database size={20} className="text-slate-400 group-hover:text-white transition-colors" />
                 {/* Status LED */}
