Aqui estão as alterações para atender a todas as suas solicitações:

1.  **Botão Fechar no Banco de Dados:** Adicionado o "X" no modal.
2.  **Novos Níveis de Acesso:** Adicionado o cargo `COORDINATOR` (Coordenador), além de `LEADER` e `MEMBER`.
3.  **Gestão de Equipes (Setores):**
    *   Agora é possível criar Equipes (ex: Folha, Ponto, TI).
    *   Ao cadastrar um usuário, você define o **Cargo** e a **Equipe**.
4.  **Segregação de Visualização:**
    *   **Membro/Líder:** Vê apenas as demandas da sua própria equipe.
    *   **Coordenador:** Tem um filtro no topo para ver "Todas as Equipes" ou selecionar uma específica para auditar.
5.  **Google Apps Script Atualizado:** Reescrevi o código do backend para suportar a nova aba "Teams" e os novos campos de usuário.

### 1. Atualize o Código do Google Apps Script

Substitua **todo** o código no editor do Google Apps Script por este abaixo. Ele criará automaticamente a aba "Teams" e atualizará as colunas da aba "Users" na próxima execução.

```javascript
function doGet(e) {
  return handleRequest(e);
}

function doPost(e) {
  return handleRequest(e);
}

function handleRequest(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const action = e && e.parameter ? e.parameter.action : 'read';

    // Ler Dados
    if (action === 'read') {
      const data = {
        tasks: readSheet(getOrCreateSheet(ss, 'Tasks')),
        users: readSheet(getOrCreateSheet(ss, 'Users')),
        teams: readSheet(getOrCreateSheet(ss, 'Teams')), // Nova aba
        alerts: readSheet(getOrCreateSheet(ss, 'Alerts'))
      };
      return responseJSON(data);
    }

    const body = e.postData ? JSON.parse(e.postData.contents) : {};

    if (action === 'saveTask') {
      saveRow(getOrCreateSheet(ss, 'Tasks'), body);
    } else if (action === 'deleteTask') {
      deleteRow(getOrCreateSheet(ss, 'Tasks'), body.id);
    } else if (action === 'saveUser') {
      saveRow(getOrCreateSheet(ss, 'Users'), body);
    } else if (action === 'deleteUser') {
      deleteRow(getOrCreateSheet(ss, 'Users'), body.id);
    } else if (action === 'saveTeam') {
      saveRow(getOrCreateSheet(ss, 'Teams'), body);
    } else if (action === 'deleteTeam') {
      deleteRow(getOrCreateSheet(ss, 'Teams'), body.id);
    } else if (action === 'saveAlert') {
      saveRow(getOrCreateSheet(ss, 'Alerts'), body);
    }

    return responseJSON({ success: true });

  } catch (err) {
    return responseJSON({ error: err.toString() });
  } finally {
    lock.releaseLock();
  }
}

function getOrCreateSheet(ss, name) {
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    if (name === 'Tasks') sheet.appendRow(['id', 'title', 'description', 'assigneeId', 'date', 'startTime', 'endTime', 'status', 'priority']);
    // Atualizado com teamId e role
    if (name === 'Users') sheet.appendRow(['id', 'name', 'email', 'role', 'teamId', 'avatar', 'presencialDates']);
    // Nova tabela de times
    if (name === 'Teams') sheet.appendRow(['id', 'name', 'color']);
    if (name === 'Alerts') sheet.appendRow(['id', 'startDate', 'endDate', 'label', 'color']);
  }

  // Migração simples para garantir que colunas novas existam em planilhas velhas (Users)
  if (name === 'Users') {
    const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
    if (!headers.includes('teamId')) {
       sheet.getRange(1, headers.length + 1).setValue('teamId');
    }
  }

  return sheet;
}

function readSheet(sheet) {
  const rows = sheet.getDataRange().getValues();
  if (rows.length < 2) return [];
  const headers = rows[0];
  const data = [];

  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    const obj = {};
    for (let j = 0; j < headers.length; j++) {
      let val = row[j];
      if (headers[j] === 'presencialDates' && typeof val === 'string' && val.startsWith('[')) {
        try { val = JSON.parse(val); } catch(e) {}
      }
      obj[headers[j]] = val;
    }
    data.push(obj);
  }
  return data;
}

function saveRow(sheet, data) {
  const rows = sheet.getDataRange().getValues();
  let headers = rows.length > 0 ? rows[0] : Object.keys(data);

  if (rows.length === 0) {
    headers = Object.keys(data);
    sheet.appendRow(headers);
  } else {
    // Verifica se precisa adicionar coluna nova dinamicamente
    const newKeys = Object.keys(data).filter(k => !headers.includes(k));
    if (newKeys.length > 0) {
      const startCol = headers.length + 1;
      sheet.getRange(1, startCol, 1, newKeys.length).setValues([newKeys]);
      headers = [...headers, ...newKeys];
    }
  }

  const rowData = headers.map(h => {
    let val = data[h];
    if (Array.isArray(val)) return JSON.stringify(val);
    if (val && typeof val === 'object' && val.toISOString) return val.toISOString();
    return val === undefined ? '' : val;
  });

  const idIndex = headers.indexOf('id');
  let rowIndex = -1;

  if (idIndex > -1 && rows.length > 1) {
    for (let i = 1; i < rows.length; i++) {
      if (rows[i][idIndex] == data.id) {
        rowIndex = i + 1;
        break;
      }
    }
  }

  if (rowIndex > -1) {
    sheet.getRange(rowIndex, 1, 1, rowData.length).setValues([rowData]);
  } else {
    sheet.appendRow(rowData);
  }
}

function deleteRow(sheet, id) {
  const rows = sheet.getDataRange().getValues();
  const idIndex = rows[0].indexOf('id');
  if (idIndex === -1) return;

  for (let i = 1; i < rows.length; i++) {
    if (rows[i][idIndex] == id) {
      sheet.deleteRow(i + 1);
      return;
    }
  }
}

function responseJSON(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}
```
*Lembre-se de clicar em **Implantar > Gerenciar implantações > Editar > Nova versão** para garantir que o código novo rode na URL antiga, ou crie uma nova implantação.*

### 2. Atualizações do Frontend

Aqui estão as mudanças no App React para suportar Equipes, Cargo de Coordenador e o botão Fechar.

