    if (!newName || !newEmail || !selectedTeamId) return;
    const newUser: User = {
      id: crypto.randomUUID(),
      name: newName,
      email: newEmail,
      role: newRole,
      teamId: selectedTeamId,
      avatar: `https://ui-avatars.com/api/?name=${encodeURIComponent(newName)}&background=random`,
      presencialDates: []
    };
    onAddUser(newUser);
    setNewName('');
    setNewEmail('');
    setNewRole('MEMBER');
  };

  const handleAddTeam = () => {
    if (!newTeamName) return;
    const newTeam: Team = {
      id: 'team_' + crypto.randomUUID().slice(0, 8),
      name: newTeamName,
      color: 'slate' // Default color for now
    };
    onAddTeam(newTeam);
    setNewTeamName('');
    // Auto-select if it's the first team
    if (teams.length === 0) setSelectedTeamId(newTeam.id);
  };

  const getRoleLabel = (r: Role) => {
    if (r === 'COORDINATOR') return 'Coordenador';
    if (r === 'LEADER') return 'Líder';
    return 'Membro';
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
