### 2. Novo Código do Google Apps Script

Copie e cole este código no seu projeto do Google Apps Script (`Code.gs`). Ele substitui o anterior.

**Importante:** Antes de rodar, vá na sua planilha e adicione manualmente as colunas novas nas respectivas abas (na linha 1, cabeçalho), caso não existam:
*   Aba **Tasks**: adicione `targetTeamId` e `isNudged`.
*   Aba **Alerts**: adicione `targetTeamId`.
*   Aba **Users**: certifique-se de que existe a coluna `password`.

```javascript
// --- CONFIGURAÇÃO ---
const SHEET_ID = ""; // Opcional: Se deixar vazio, usa a planilha ativa vinculada
const TABS = {
  TASKS: "Tasks",
  USERS: "Users",
  TEAMS: "Teams",
  ALERTS: "Alerts"
};

// --- FUNÇÕES PRINCIPAIS ---

function doGet(e) {
  return handleRequest(e);
}

function doPost(e) {
  return handleRequest(e);
}

function handleRequest(e) {
  const lock = LockService.getScriptLock();
  // Aguarda até 30s para evitar conflitos de gravação simultânea
  lock.tryLock(30000); 

  try {
    const action = e.parameter.action;
    const data = e.postData ? JSON.parse(e.postData.contents) : null;
    const ss = SHEET_ID ? SpreadsheetApp.openById(SHEET_ID) : SpreadsheetApp.getActiveSpreadsheet();

    let result = {};

    if (action === "read") {
      result = readAllData(ss);
    } else if (action === "saveTask") {
      saveRow(ss, TABS.TASKS, data);
      result = { success: true };
    } else if (action === "deleteTask") {
      deleteRow(ss, TABS.TASKS, data.id);
      result = { success: true };
    } else if (action === "saveUser") {
      saveRow(ss, TABS.USERS, data);
      result = { success: true };
    } else if (action === "saveUsersBatch") {
      // Salva múltiplos usuários de uma vez
      if (Array.isArray(data)) {
        data.forEach(user => saveRow(ss, TABS.USERS, user));
      }
      result = { success: true };
    } else if (action === "deleteUser") {
      deleteRow(ss, TABS.USERS, data.id);
      result = { success: true };
    } else if (action === "saveTeam") {
      saveRow(ss, TABS.TEAMS, data);
      result = { success: true };
    } else if (action === "deleteTeam") {
      deleteRow(ss, TABS.TEAMS, data.id);
      result = { success: true };
    } else if (action === "saveAlert") {
      saveRow(ss, TABS.ALERTS, data);
      result = { success: true };
    } else {
      throw new Error("Ação desconhecida: " + action);
    }

    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({ error: error.message }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

// --- AUXILIARES DE BANCO DE DADOS ---

function readAllData(ss) {
  return {
    tasks: getSheetData(ss, TABS.TASKS),
    users: getSheetData(ss, TABS.USERS),
    teams: getSheetData(ss, TABS.TEAMS),
    alerts: getSheetData(ss, TABS.ALERTS)
  };
}

function getSheetData(ss, sheetName) {
  const sheet = ss.getSheetByName(sheetName);
  if (!sheet) return [];

  const data = sheet.getDataRange().getValues();
  if (data.length < 2) return []; // Só cabeçalho

  const headers = data[0];
  const rows = data.slice(1);

  return rows.map(row => {
    const obj = {};
    headers.forEach((header, index) => {
      let value = row[index];
      // Tratamento especial para arrays/JSON
      if (header === 'presencialDates' && typeof value === 'string' && value.startsWith('[')) {
        try { value = JSON.parse(value); } catch(e) {}
      }
      // Tratamento especial para Datas: converte para String ISO se for objeto Date
      if (value instanceof Date) {
        value = Utilities.formatDate(value, ss.getSpreadsheetTimeZone(), "yyyy-MM-dd");
      }
      obj[header] = value;
    });
    return obj;
  });
}

function saveRow(ss, sheetName, dataObj) {
  let sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
    // Cria cabeçalhos baseados nas chaves do objeto se for sheet nova
    const headers = Object.keys(dataObj);
    sheet.appendRow(headers);
  }

  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
  const allData = sheet.getDataRange().getValues();

  // Mapeia os dados para a ordem das colunas
  const rowData = headers.map(header => {
    let val = dataObj[header];

    // Converte arrays para string JSON (ex: presencialDates)
    if (Array.isArray(val)) {
      val = JSON.stringify(val);
    }
    // Garante que booleanos virem string ou fiquem legíveis
    if (typeof val === 'boolean') {
      val = val; 
    }
    // Garante que senha seja tratada como string (adiciona aspas simples forçadas se for numérico puro)
    if (header === 'password' && val !== undefined && val !== null) {
       return "'" + val; 
    }

    return val === undefined || val === null ? "" : val;
  });

  // Procura pelo ID para atualizar
  const idIndex = headers.indexOf('id');
  if (idIndex === -1) throw new Error("Coluna 'id' não encontrada na aba " + sheetName);

  let rowIndex = -1;
  // Começa do 1 pois 0 é cabeçalho. allData[i] é a linha i+1 na planilha
  for (let i = 1; i < allData.length; i++) {
    if (String(allData[i][idIndex]) === String(dataObj.id)) {
      rowIndex = i + 1;
      break;
    }
  }

  if (rowIndex > 0) {
    // Atualiza
    sheet.getRange(rowIndex, 1, 1, rowData.length).setValues([rowData]);
  } else {
    // Insere
    sheet.appendRow(rowData);
  }
}

function deleteRow(ss, sheetName, id) {
  const sheet = ss.getSheetByName(sheetName);
  if (!sheet) return;

  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const idIndex = headers.indexOf('id');

  if (idIndex === -1) return;

  // Deleta de baixo para cima para não bagunçar índices se houver duplicatas (raro)
  for (let i = data.length - 1; i >= 1; i--) {
    if (String(data[i][idIndex]) === String(id)) {
      sheet.deleteRow(i + 1);
      return; // Assume ID único, para e retorna
    }
  }
}

