                </div>
             </div>
          </div>
        </div>

      </div>
    </div>
  );
};

export default DashboardView;

import React, { useState } from 'react';
import { X, AlertTriangle, Check, Users, Trash2, Pencil } from 'lucide-react';
import { AlertPeriod, AlertColor, normalizeDate, ALERT_COLOR_MAP, Team } from '../types';
import { format } from 'date-fns';

interface AlertModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (alert: AlertPeriod) => void;
  onDelete?: (alertId: string) => void;
  teams: Team[];
  alertPeriods?: AlertPeriod[];
}

const AlertModal: React.FC<AlertModalProps> = ({ isOpen, onClose, onSave, onDelete, teams, alertPeriods = [] }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [label, setLabel] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [color, setColor] = useState<AlertColor>('ORANGE');
  const [targetTeamId, setTargetTeamId] = useState<string>('ALL');

  if (!isOpen) return null;

  const handleEdit = (alert: AlertPeriod) => {
     setEditingId(alert.id);
     setLabel(alert.label);
     setStartDate(format(alert.startDate, 'yyyy-MM-dd'));
     setEndDate(format(alert.endDate, 'yyyy-MM-dd'));
     setColor(alert.color);
     setTargetTeamId(alert.targetTeamId || 'ALL');
  };

  const resetForm = () => {
    setEditingId(null);
    setLabel('');
    setStartDate('');
    setEndDate('');
    setColor('ORANGE');
    setTargetTeamId('ALL');
  };

  const handleSave = () => {
    if (!label || !startDate || !endDate) return;

    const [sy, sm, sd] = startDate.split('-').map(Number);
    const [ey, em, ed] = endDate.split('-').map(Number);

    const newAlert: AlertPeriod = {
      id: editingId || crypto.randomUUID(),
      startDate: normalizeDate(new Date(sy, sm - 1, sd)),
      endDate: normalizeDate(new Date(ey, em - 1, ed)),
      label,
      color,
      targetTeamId
    };
    onSave(newAlert);

    onClose();
    resetForm();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-200 flex flex-col max-h-[90vh]">
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 flex justify-between items-center shrink-0">
          <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
             <AlertTriangle size={20} className="text-orange-500" /> Gerenciar Alertas
          </h2>
          <button onClick={() => { onClose(); resetForm(); }} className="text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="p-6 space-y-4 overflow-y-auto custom-scrollbar">
           {/* Form Section */}
           <div className={`space-y-4 border-b border-slate-100 pb-6 rounded-lg p-2 ${editingId ? 'bg-indigo-50 border border-indigo-100' : ''}`}>
             <h3 className={`text-sm font-bold flex items-center gap-2 ${editingId ? 'text-indigo-700' : 'text-slate-700'}`}>
               {editingId ? <Pencil size={14} /> : <AlertTriangle size={14}/>}
               {editingId ? 'Editar Alerta' : 'Novo Alerta'}
             </h3>
             <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Motivo</label>
               <input 
                 type="text" 
                 value={label}
                 onChange={e => setLabel(e.target.value)}
                 placeholder="Ex: Fechamento, Escala de Fim de Ano..."
                 className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 bg-white"
               />
             </div>

             <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Visibilidade</label>
                <div className="relative">
                   <select
                     value={targetTeamId}
                     onChange={e => setTargetTeamId(e.target.value)}
                     className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm appearance-none bg-white"
                   >
                     <option value="ALL">Todas as Equipes</option>
                     {teams.map(t => (
                       <option key={t.id} value={t.id}>{t.name}</option>
                     ))}
                   </select>
                   <Users size={14} className="absolute right-3 top-3 text-slate-400 pointer-events-none"/>
                </div>
             </div>

             <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Cor</label>
               <div className="flex gap-3">
                  {(Object.keys(ALERT_COLOR_MAP) as AlertColor[]).map((c) => (
                    <button
                      key={c}
                      onClick={() => setColor(c)}
                      className={`w-8 h-8 rounded-full flex items-center justify-center transition-transform hover:scale-110 ${ALERT_COLOR_MAP[c].bg.replace('50', '500')}`}
                    >
                      {color === c && <Check size={16} className="text-white" />}
                    </button>
                  ))}
               </div>
             </div>

             <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Início</label>
                  <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 bg-white"/>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Fim</label>
                  <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 bg-white"/>
                </div>
             </div>

             <div className="flex gap-2">
                {editingId && (
                  <button onClick={resetForm} className="flex-1 bg-white border border-slate-300 text-slate-700 text-sm font-medium py-2 rounded-lg hover:bg-slate-50">
                    Cancelar
                  </button>
                )}
                <button 
                  onClick={handleSave}
                  className="flex-1 bg-slate-900 hover:bg-black text-white font-medium py-2 rounded-lg shadow-sm transition-colors"
                >
                  {editingId ? 'Salvar Alterações' : 'Criar Alerta'}
                </button>
             </div>
           </div>

           {/* List Section */}
           {alertPeriods.length > 0 && (
              <div className="space-y-2">
                 <h3 className="text-sm font-bold text-slate-700 mt-2">Alertas Ativos (Clique para editar)</h3>
                 {alertPeriods.map(alert => {
                   const styles = ALERT_COLOR_MAP[alert.color];
                   const isEditing = editingId === alert.id;
                   return (
                     <div 
                        key={alert.id} 
                        className={`flex items-center justify-between p-3 rounded-lg border transition-all cursor-pointer hover:shadow-md ${styles.bg} ${isEditing ? 'border-indigo-500 ring-1 ring-indigo-500' : styles.border}`}
                        onClick={() => handleEdit(alert)}
                     >
                        <div>
                           <div className={`text-sm font-bold ${styles.text}`}>{alert.label}</div>
                           <div className="text-xs text-slate-500">
                             {format(alert.startDate, 'dd/MM')} até {format(alert.endDate, 'dd/MM')}
                             {alert.targetTeamId && alert.targetTeamId !== 'ALL' && (
                               <span className="ml-1 opacity-75">• Equipe Específica</span>
                             )}
                           </div>
                        </div>
                        {onDelete && (
                          <button 
                             onClick={(e) => {
                                e.stopPropagation(); // Prevent edit click
                                if(window.confirm('Excluir este alerta?')) onDelete(alert.id);
                             }}
                             className="p-1.5 text-slate-400 hover:text-red-500 transition-colors"
                          >
                             <Trash2 size={16} />
                          </button>
                        )}
                     </div>
                   );
                 })}
              </div>
           )}
        </div>
      </div>
    </div>
  );
};

export default AlertModal;

import React, { useState, useEffect } from 'react';
import { X, Calendar as CalendarIcon, User as UserIcon, Flag, CheckCircle2, Clock, AlertCircle, Megaphone } from 'lucide-react';
import { Task, User, Team, TaskStatus, Priority, normalizeDate } from '../types';
import { STATUS_LABELS } from '../constants';
import { format } from 'date-fns';

interface TaskModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Task) => void;
  onDelete?: (taskId: string) => void;
  onRequestTransfer?: (taskId: string, newAssigneeId: string) => void; // Kept for interface compatibility but unused
  initialTask?: Task | null;
  selectedDate?: Date;
  currentUser: User;
  users: User[]; // Dynamic users list
  teams: Team[]; // Dynamic teams list
}

const TaskModal: React.FC<TaskModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  onDelete, 
  initialTask, 
  selectedDate, 
  currentUser,
  users,
  teams
}) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [assigneeId, setAssigneeId] = useState(currentUser.id);
  const [targetTeamId, setTargetTeamId] = useState<string>(''); // For filtering task per team
  const [priority, setPriority] = useState<Priority>('MEDIUM');
  const [status, setStatus] = useState<TaskStatus>('TODO');
  const [dateStr, setDateStr] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [isNudged, setIsNudged] = useState(false);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [pendingNudge, setPendingNudge] = useState(false);

  // Reset or populate form when modal opens
  useEffect(() => {
    if (isOpen) {
      setHasUnsavedChanges(false);
      setPendingNudge(false);
      if (initialTask) {
        setTitle(initialTask.title);
        setDescription(initialTask.description);
        setAssigneeId(initialTask.assigneeId);
        setPriority(initialTask.priority);
        setStatus(initialTask.status);
        setDateStr(format(initialTask.date, 'yyyy-MM-dd'));
        setStartTime(initialTask.startTime || '');
        setEndTime(initialTask.endTime || '');
        setTargetTeamId(initialTask.targetTeamId || '');
        setIsNudged(initialTask.isNudged || false);

        // Auto-set team based on assignee if missing
        if (!initialTask.targetTeamId) {
            const assignee = users.find(u => u.id === initialTask.assigneeId);
            if (assignee) setTargetTeamId(assignee.teamId);
        }

      } else {
        // New Task
        setTitle('');
        setDescription('');
        setAssigneeId(currentUser.id); // Default to current user
        setTargetTeamId(currentUser.teamId || teams[0]?.id || '');
        setPriority('MEDIUM');
        setStatus('TODO');
        setDateStr(selectedDate ? format(selectedDate, 'yyyy-MM-dd') : format(new Date(), 'yyyy-MM-dd'));
        setStartTime('08:00');
        setEndTime('09:00');
        setIsNudged(false);
      }
    }
  }, [isOpen, initialTask, selectedDate, currentUser, users, teams]);

  // Track changes to show save button prompt
  useEffect(() => {
     if(isOpen) setHasUnsavedChanges(true);
  }, [title, description, assigneeId, targetTeamId, priority, status, dateStr, startTime, endTime, isNudged]);


  if (!isOpen) return null;

  const buildTaskObject = (overrides: Partial<Task> = {}): Task | null => {
    if (!title.trim() || !dateStr) return null;

    const [year, month, day] = dateStr.split('-').map(Number);
    const localDate = new Date(year, month - 1, day);

    return {
      id: initialTask?.id || crypto.randomUUID(),
      title,
      description,
      assigneeId,
      targetTeamId,
      priority,
      status,
      date: normalizeDate(localDate),
      startTime,
      endTime,
      isNudged,
      ...overrides
    };
  };

  const handleSave = () => {
    const task = buildTaskObject();
    if (task) {
      onSave(task);
      onClose();
    }
  };

  const handleNudge = () => {
       // Just update local state immediately to show visual feedback
       if (!description.includes('[COBRANÇA]')) {
         setDescription(`[COBRANÇA]: Solicitada prioridade em ${format(new Date(), 'dd/MM HH:mm')}.\n` + description);
       }
       setPriority('HIGH');
       setIsNudged(true);
       setPendingNudge(true); // Triggers visual warning to save
  };

  const handleClaimTask = () => {
    const confirmed = window.confirm("Você tem certeza que deseja assumir a responsabilidade por esta demanda?\n\nO responsável será alterado para você. Clique em 'Salvar' para confirmar.");
    if (confirmed) {
       // Just update local state
       setAssigneeId(currentUser.id);
       setTargetTeamId(currentUser.teamId); // Update team to my team as well
    }
  };

  const isLeader = currentUser.role === 'LEADER';
  const isCoordinator = currentUser.role === 'COORDINATOR';
  const isOwner = initialTask ? initialTask.assigneeId === currentUser.id : true; // True if creating new
  const isCreating = !initialTask;

  // Permissions Logic
  const canEditDetails = isCoordinator || isLeader || isOwner || isCreating;
  const canEditStatus = isCoordinator || isLeader || isOwner;
  const canNudge = (isLeader || isCoordinator) && !isOwner && initialTask;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in duration-200">

        {/* Header */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 flex justify-between items-center">
          <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
            {initialTask ? 'Detalhes da Demanda' : 'Nova Demanda'}
            {isNudged && <span className="bg-red-100 text-red-600 text-[10px] px-2 py-0.5 rounded-full border border-red-200 animate-pulse">URGENTE / COBRADO</span>}
          </h2>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 space-y-5">

          {/* View Only Warning for non-owners */}
          {!canEditDetails && (
             <div className="bg-blue-50 border border-blue-200 text-blue-800 p-3 rounded-lg text-sm flex items-start gap-2">
                <AlertCircle size={16} className="mt-0.5" />
                <div>
                   Visualizando demanda de outro membro.
                </div>
             </div>
          )}

          {/* Nudge Warning */}
          {pendingNudge && (
             <div className="bg-amber-50 border border-amber-200 text-amber-800 p-3 rounded-lg text-sm flex items-start gap-2 animate-in slide-in-from-top-2">
                <Megaphone size={16} className="mt-0.5" />
                <div>
                   <strong>Cobrança registrada!</strong> A prioridade foi alterada para ALTA e uma nota foi adicionada à descrição. <br/>
                   Clique em <strong>Salvar</strong> para confirmar.
                </div>
             </div>
          )}

          {/* Title */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Título</label>
            <input
              type="text"
              disabled={!canEditDetails}
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 disabled:text-slate-500"
              placeholder="Ex: Entregar relatório de vendas"
            />
          </div>

          {/* Date & Time Row */}
          <div className="grid grid-cols-3 gap-3">
            <div className="col-span-1">
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <CalendarIcon size={14} /> Data
              </label>
              <input
                type="date"
                disabled={!canEditDetails}
                value={dateStr}
                onChange={(e) => setDateStr(e.target.value)}
                className="w-full px-2 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 text-sm"
              />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <Clock size={14} /> Início
              </label>
              <input
                type="time"
                disabled={!canEditDetails}
                value={startTime}
                onChange={(e) => setStartTime(e.target.value)}
                className="w-full px-2 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 text-sm"
              />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <Clock size={14} /> Fim
              </label>
              <input
                type="time"
                disabled={!canEditDetails}
                value={endTime}
                onChange={(e) => setEndTime(e.target.value)}
                className="w-full px-2 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 text-sm"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
             {/* Assignee (Grouped by Team) */}
             <div>
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <UserIcon size={14} /> Responsável
              </label>
              <div className="relative">
                <select
                  disabled={!canEditDetails} 
                  value={assigneeId}
                  onChange={(e) => {
                     setAssigneeId(e.target.value);
                     // Auto-update team ID based on user
                     const u = users.find(u => u.id === e.target.value);
                     if(u) setTargetTeamId(u.teamId);
                  }}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 appearance-none disabled:bg-slate-100 disabled:text-slate-500"
                >
                  {teams.map(team => {
                    const teamMembers = users.filter(u => u.teamId === team.id);
                    if (teamMembers.length === 0) return null;
                    return (
                      <optgroup key={team.id} label={team.name}>
                        {teamMembers.map((user) => (
                          <option key={user.id} value={user.id}>
                            {user.name}
                          </option>
                        ))}
                      </optgroup>
                    );
                  })}
                  <optgroup label="Sem Setor">
                    {users.filter(u => !u.teamId).map(user => (
                       <option key={user.id} value={user.id}>{user.name}</option>
                    ))}
                  </optgroup>
                </select>
                <div className="absolute right-3 top-2.5 pointer-events-none text-slate-400">
                  <UserIcon size={16} />
                </div>
              </div>
            </div>

            {/* Target Team Selection (Explicit) */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <Flag size={14} /> Equipe da Demanda
              </label>
              <select
                disabled={!canEditDetails}
                value={targetTeamId}
                onChange={(e) => setTargetTeamId(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100"
              >
                 <option value="" disabled>Selecione...</option>
                 {teams.map(t => (
                   <option key={t.id} value={t.id}>{t.name}</option>
                 ))}
              </select>
            </div>
          </div>

          {/* Status and Priority */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <Flag size={14} /> Prioridade
              </label>
              <select
                disabled={!canEditDetails}
                value={priority}
                onChange={(e) => setPriority(e.target.value as Priority)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100"
              >
                <option value="LOW">Baixa</option>
                <option value="MEDIUM">Média</option>
                <option value="HIGH">Alta</option>
              </select>
            </div>

            <div>
               <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                 <CheckCircle2 size={14} /> Status
               </label>
               <select
                 disabled={!canEditStatus}
                 value={status}
                 onChange={(e) => setStatus(e.target.value as TaskStatus)}
                 className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100"
               >
                 {Object.keys(STATUS_LABELS).map((s) => (
                    <option key={s} value={s}>{STATUS_LABELS[s as TaskStatus]}</option>
                 ))}
               </select>
            </div>
          </div>

          {/* Description */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Descrição</label>
            <textarea
              disabled={!canEditDetails}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
              className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 resize-none text-sm"
              placeholder="Detalhes adicionais..."
            />
          </div>

        </div>

        {/* Footer */}
        <div className="bg-slate-50 border-t border-slate-100 px-6 py-4 flex justify-between items-center">
           {/* Left Action: Delete or Claim or Nudge */}
           <div className="flex gap-2">
             {initialTask && (isLeader || isCoordinator) && (
                <button
                  onClick={() => {
                    if (onDelete && initialTask) onDelete(initialTask.id);
                    onClose();
                  }}
                  className="px-3 py-2 text-sm font-medium text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                >
                  Excluir
                </button>
             )}

             {canNudge && !isNudged && (
                <button
                  onClick={handleNudge}
                  disabled={pendingNudge}
                  className="px-3 py-2 text-sm font-medium text-amber-700 bg-amber-50 hover:bg-amber-100 border border-amber-200 rounded-lg transition-colors flex items-center gap-1 disabled:opacity-50"
                  title="Atualizará prioridade para Alta e adicionará flag de Cobrança. Requer salvar."
                >
                  <Megaphone size={14} /> {pendingNudge ? 'Cobrança Pendente' : 'Cobrar Entrega'}
                </button>
             )}

             {!isOwner && initialTask && (
               <button
                 onClick={handleClaimTask}
                 className="px-3 py-2 text-sm font-medium text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                 title="Tornar-se o responsável. Requer salvar."
               >
                 Assumir
               </button>
             )}
           </div>

           <div className="flex gap-3">
             <button
               onClick={onClose}
               className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-200 rounded-lg transition-colors"
             >
               Cancelar
             </button>
             {canEditDetails && (
               <button
                 onClick={handleSave}
                 className="px-4 py-2 text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-md shadow-indigo-200 transition-all hover:scale-105"
               >
                 Salvar
               </button>
             )}
           </div>
        </div>
      </div>
    </div>
  );
};

export default TaskModal;

export type Role = 'COORDINATOR' | 'LEADER' | 'MEMBER';

export type TaskStatus = 'TODO' | 'IN_PROGRESS' | 'DONE';

export type Priority = 'LOW' | 'MEDIUM' | 'HIGH';

export type AlertColor = 'RED' | 'ORANGE' | 'BLUE' | 'PURPLE' | 'GREEN';

export interface Team {
  id: string;
  name: string;
  color: string; // Hex or tailwind class reference
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: Role;
  teamId: string;
  avatar: string;
  presencialDates: string[]; // Array of ISO date strings (yyyy-MM-dd)
  password?: string; 
}

export interface Task {
  id: string;
  title: string;
  description: string;
  assigneeId: string;
  targetTeamId?: string; // Optional: If specific to a team context
  date: Date; // Normalized to midnight
  startTime?: string; // Format "HH:mm"
  endTime?: string;   // Format "HH:mm"
  status: TaskStatus;
  priority: Priority;
  isNudged?: boolean; // If true, it was "Cobrada"
}

export interface AlertPeriod {
  id: string;
  startDate: Date;
  endDate: Date;
  label: string;
  color: AlertColor;
  targetTeamId?: string | 'ALL'; // Filter alert by team
}

export interface Notification {
  id: string;
  targetUserId: string; // Who should see this
  message: string;
  date: Date;
  read: boolean;
  type: 'TASK_ASSIGNED' | 'NUDGE';
}

// Helper to keep dates consistent
export const normalizeDate = (date: Date): Date => {
  const newDate = new Date(date);
  newDate.setHours(0, 0, 0, 0);
  return newDate;
};

// Helper for colors
export const ALERT_COLOR_MAP: Record<AlertColor, { bg: string, border: string, text: string, icon: string }> = {
  RED: { bg: 'bg-red-50', border: 'border-red-200', text: 'text-red-700', icon: 'text-red-500' },
  ORANGE: { bg: 'bg-orange-50', border: 'border-orange-200', text: 'text-orange-700', icon: 'text-orange-500' },
  BLUE: { bg: 'bg-blue-50', border: 'border-blue-200', text: 'text-blue-700', icon: 'text-blue-500' },
  PURPLE: { bg: 'bg-purple-50', border: 'border-purple-200', text: 'text-purple-700', icon: 'text-purple-500' },
  GREEN: { bg: 'bg-emerald-50', border: 'border-emerald-200', text: 'text-emerald-700', icon: 'text-emerald-500' },
};

import React, { useState, useEffect, useRef } from 'react';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import TaskListView from './components/TaskListView';
import TeamModal from './components/TeamModal';
import AlertModal from './components/AlertModal';
import DashboardView from './components/DashboardView';
import ReportsView from './components/ReportsView';
import PresencialModal from './components/PresencialModal';
import UserAuthModal from './components/UserAuthModal'; 

import { User, Task, AlertPeriod, normalizeDate, Team, Notification, TaskStatus } from './types';
import { USERS, INITIAL_TASKS, INITIAL_TEAMS } from './constants';
import { api, setApiUrl, getApiUrl } from './services/api';
import { Layout, CheckSquare, List, Calendar as CalendarIcon, Settings, PieChart, MapPin, AlertTriangle, Users, User as UserIcon, Database, Link as LinkIcon, RefreshCw, Loader2, XCircle, X, Filter, KeyRound, Bell, FileBarChart } from 'lucide-react';
import { format, isValid } from 'date-fns';

const App: React.FC = () => {
  // Config State
  const [isConfigOpen, setIsConfigOpen] = useState(!getApiUrl());
  const [apiUrlInput, setApiUrlInput] = useState(getApiUrl());
  const [isSyncing, setIsSyncing] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'DISCONNECTED' | 'CONNECTED' | 'ERROR'>('DISCONNECTED');
  const [configError, setConfigError] = useState<string | null>(null);

  const [currentUser, setCurrentUser] = useState<User>(USERS[0]); 

  // Data State
  const [tasks, setTasks] = useState<Task[]>([]);
  const [teamUsers, setTeamUsers] = useState<User[]>([]);
  const [teams, setTeams] = useState<Team[]>([]);
  const [alertPeriods, setAlertPeriods] = useState<AlertPeriod[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const [viewMode, setViewMode] = useState<'CALENDAR' | 'LIST' | 'DASHBOARD' | 'REPORTS'>('CALENDAR');
  const [filterScope, setFilterScope] = useState<string>('MY_TEAM'); 
  const [filterStatus, setFilterStatus] = useState<TaskStatus | 'ALL'>('ALL'); // For Dashboard filtering

  // Modals State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [isAlertModalOpen, setIsAlertModalOpen] = useState(false);
  const [isPresencialModalOpen, setIsPresencialModalOpen] = useState(false);
  const [isUserSwitcherOpen, setIsUserSwitcherOpen] = useState(false);
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);

  // Auth Modal State
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authTargetUser, setAuthTargetUser] = useState<User | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'CHANGE_PASSWORD'>('LOGIN');

  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  // Refs for click outside
  const userSwitcherRef = useRef<HTMLDivElement>(null);
  const notificationRef = useRef<HTMLDivElement>(null);

  // Ref for notifications comparison (to avoid stale state in interval)
  const tasksRef = useRef<Task[]>([]);
  const isFirstLoadRef = useRef(true);

  // Keep refs synced
  useEffect(() => {
    tasksRef.current = tasks;
  }, [tasks]);

  // --- CLICK OUTSIDE HANDLER ---
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (userSwitcherRef.current && !userSwitcherRef.current.contains(event.target as Node)) {
        setIsUserSwitcherOpen(false);
      }
      if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // --- API & SYNC LOGIC ---

  const fetchData = async (): Promise<boolean> => {
    if (!getApiUrl()) return false;

    try {
      setIsSyncing(true);
      const data = await api.sync();

      // PARSE TASKS
      const parsedTasks: Task[] = data.tasks.map((t: any) => {
        let dateObj;
        if (typeof t.date === 'string' && t.date.includes('-') && !t.date.includes('T')) {
           const [y, m, d] = t.date.split('-').map(Number);
           dateObj = new Date(y, m - 1, d);
        } else if (typeof t.date === 'string') {
           const datePart = t.date.substring(0, 10);
           if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
             const [y, m, d] = datePart.split('-').map(Number);
             dateObj = new Date(y, m - 1, d);
           } else {
             dateObj = new Date(t.date);
           }
        } else {
           dateObj = new Date(t.date);
        }

        const cleanTime = (val: any) => {
          if (!val) return '';
          const strVal = String(val);
          if (strVal.match(/^\d{1,2}:\d{2}$/)) return strVal;
          const d = new Date(strVal);
          if (isValid(d)) return format(d, 'HH:mm');
          return strVal;
        };

        return { 
          ...t, 
          date: dateObj,
          startTime: cleanTime(t.startTime),
          endTime: cleanTime(t.endTime)
        };
      });

      const parsedAlerts: AlertPeriod[] = data.alerts.map((a: any) => {
         let start, end;
         if (typeof a.startDate === 'string') {
            const datePart = a.startDate.substring(0, 10);
            if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
               const [y, m, d] = datePart.split('-').map(Number);
               start = new Date(y, m - 1, d);
            } else start = new Date(a.startDate);
         } else start = new Date(a.startDate);

         if (typeof a.endDate === 'string') {
             const datePart = a.endDate.substring(0, 10);
             if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
                const [y, m, d] = datePart.split('-').map(Number);
                end = new Date(y, m - 1, d);
             } else end = new Date(a.endDate);
         } else end = new Date(a.endDate);

         return { ...a, startDate: start, endDate: end };
      });

      const parsedUsers: User[] = data.users.map((u: any) => ({
        ...u,
        presencialDates: Array.isArray(u.presencialDates) ? u.presencialDates : [],
        password: (u.password !== undefined && u.password !== null && u.password !== '') ? String(u.password) : undefined
      }));

      const parsedTeams: Team[] = data.teams || [];

      // CHECK NOTIFICATIONS (Improved Logic)
      if (!isFirstLoadRef.current && tasksRef.current.length > 0) {
         parsedTasks.forEach(newTask => {
             const oldTask = tasksRef.current.find(t => t.id === newTask.id);

             // 1. New Assignment
             if ((!oldTask || oldTask.assigneeId !== newTask.assigneeId) && newTask.assigneeId) {
                // Avoid duplicates
                setNotifications(prev => {
                    const exists = prev.some(n => n.type === 'TASK_ASSIGNED' && n.message.includes(newTask.title) && n.targetUserId === newTask.assigneeId);
                    if (exists) return prev;
                    return [
                        { 
                          id: crypto.randomUUID(), 
                          targetUserId: newTask.assigneeId,
                          message: `Nova demanda atribuída: ${newTask.title}`, 
                          date: new Date(), 
                          read: false, 
                          type: 'TASK_ASSIGNED' 
                        },
                        ...prev
                    ];
                });
             }

             // 2. Nudge (Cobrança) - If isNudged changed to true
             if (newTask.isNudged && (!oldTask || !oldTask.isNudged)) {
                 setNotifications(prev => {
                     const exists = prev.some(n => n.type === 'NUDGE' && n.message.includes(newTask.title) && n.targetUserId === newTask.assigneeId);
                     if (exists) return prev;
                     return [
                         {
                           id: crypto.randomUUID(),
                           targetUserId: newTask.assigneeId,
                           message: `⚠️ URGENTE / COBRANÇA: A demanda "${newTask.title}" foi sinalizada.`,
                           date: new Date(),
                           read: false,
                           type: 'NUDGE'
                         },
                         ...prev
                     ]
                 });
             }
         });
      }
      isFirstLoadRef.current = false;

      setTasks(parsedTasks);

      if (parsedUsers.length > 0) {
        setTeamUsers(prevUsers => {
            return parsedUsers.map(serverUser => {
                const localUser = prevUsers.find(u => u.id === serverUser.id);
                if (localUser?.password && !serverUser.password) {
                    return { ...serverUser, password: localUser.password };
                }
                return serverUser;
            });
        });
      } else {
        setTeamUsers(USERS);
      }

      if (parsedTeams.length > 0) setTeams(parsedTeams);
      else setTeams(INITIAL_TEAMS);

      setAlertPeriods(parsedAlerts);

      setTeamUsers(currentList => {
         const foundCurrent = currentList.find(u => u.id === currentUser.id);
         if (foundCurrent) {
            if (foundCurrent.name !== currentUser.name || foundCurrent.role !== currentUser.role || foundCurrent.teamId !== currentUser.teamId) {
               setCurrentUser(prev => ({ ...prev, ...foundCurrent }));
            }
         } else if (currentList.length > 0 && !currentList.find(u => u.id === currentUser.id)) {
            setCurrentUser(currentList[0]);
         }
         return currentList; 
      });

      setConnectionStatus('CONNECTED');
      return true;
    } catch (error) {
      console.error("Sync Error", error);
      setConnectionStatus('ERROR');
      return false;
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (getApiUrl()) {
      fetchData();
      const intervalId = setInterval(fetchData, 5000);
      return () => clearInterval(intervalId);
    } else {
      setTasks(INITIAL_TASKS);
      setTeamUsers(USERS);
      setTeams(INITIAL_TEAMS);
      isFirstLoadRef.current = false; // For demo mode, enable notifications immediately
    }
  }, []); 

  useEffect(() => {
    setFilterScope('MY_TEAM');
  }, [currentUser.id]);

  const handleConnect = async () => {
    setConfigError(null);
    setIsSyncing(true);
    setApiUrl(apiUrlInput);
    isFirstLoadRef.current = true; // Reset first load on new connection

    const success = await fetchData();

    if (success) {
      setIsConfigOpen(false);
    } else {
      setConfigError("Não foi possível conectar. Verifique se autorizou o script e se a permissão de acesso está definida como 'Qualquer pessoa'.");
      setConnectionStatus('ERROR');
    }
    setIsSyncing(false);
  };

  // --- AUTH HANDLERS ---

  const handleUserSwitchClick = (user: User) => {
    setAuthTargetUser(user);
    setAuthMode('LOGIN');
    setIsAuthModalOpen(true);
    setIsUserSwitcherOpen(false); 
  };

  const handleChangePasswordClick = () => {
    setAuthTargetUser(currentUser);
    setAuthMode('CHANGE_PASSWORD');
    setIsAuthModalOpen(true);
  };

  const handleAuthSuccess = async (updatedUser?: User) => {
    if (updatedUser) {
        setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
        setCurrentUser(updatedUser);
        if (getApiUrl()) await api.saveUser(updatedUser);
    } else if (authTargetUser) {
        setCurrentUser(authTargetUser);
    }
    if (authMode === 'CHANGE_PASSWORD') alert("Senha alterada com sucesso!");
  };

  // --- DATA HANDLERS ---

  const handleAddTask = (date: Date) => {
    setSelectedDate(date);
    setSelectedTask(null);
    setIsModalOpen(true);
  };

  const handleEditTask = (task: Task) => {
    setSelectedTask(task);
    setSelectedDate(task.date);
    setIsModalOpen(true);
  };

  const handleSaveTask = async (taskToSave: Task) => {
    setTasks(prev => {
      const exists = prev.find(t => t.id === taskToSave.id);
      if (exists) return prev.map(t => t.id === taskToSave.id ? taskToSave : t);
      return [...prev, taskToSave];
    });

    if (getApiUrl()) {
      await api.saveTask(taskToSave);
      fetchData();
    }
  };

  const handleDeleteTask = async (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
    if (getApiUrl()) {
      await api.deleteTask(taskId);
      fetchData();
    }
  };

  const handleAddUser = async (newUser: User) => {
    setTeamUsers(prev => [...prev, newUser]);
    if (getApiUrl()) {
      await api.saveUser(newUser);
      fetchData();
    }
  };

  const handleEditUser = async (updatedUser: User) => {
    setTeamUsers(prev => prev.map(u => {
        if (u.id === updatedUser.id) {
            if (!updatedUser.password && u.password) {
                return { ...updatedUser, password: u.password };
            }
            return updatedUser;
        }
        return u;
    }));

    if (currentUser.id === updatedUser.id) {
       setCurrentUser(prev => {
         if (!updatedUser.password && prev.password) {
           return { ...updatedUser, password: prev.password };
         }
         return updatedUser;
       });
    }

    if (getApiUrl()) {
      const userToSend = { ...updatedUser };
      const localUser = teamUsers.find(u => u.id === updatedUser.id);
      if (localUser?.password && !userToSend.password) {
          userToSend.password = localUser.password;
      }
      await api.saveUser(userToSend);
      fetchData();
    }
  };

  const handleRemoveUser = async (userId: string) => {
    setTeamUsers(prev => prev.filter(u => u.id !== userId));
    if (getApiUrl()) {
      await api.deleteUser(userId);
      fetchData();
    }
  };

  const handleAddTeam = async (newTeam: Team) => {
    setTeams(prev => [...prev, newTeam]);
    if (getApiUrl()) {
      await api.saveTeam(newTeam);
      fetchData();
    }
  };

  const handleRemoveTeam = async (teamId: string) => {
    setTeams(prev => prev.filter(t => t.id !== teamId));
    if (getApiUrl()) {
      await api.deleteTeam(teamId);
      fetchData();
    }
  };

  const handleSaveAlert = async (newAlert: AlertPeriod) => {
    setAlertPeriods(prev => {
       const exists = prev.find(a => a.id === newAlert.id);
       if (exists) return prev.map(a => a.id === newAlert.id ? newAlert : a);
       return [...prev, newAlert];
    });

    if (getApiUrl()) {
      await api.saveAlert(newAlert);
      fetchData();
    }
  };

  const handleDeleteAlert = async (alertId: string) => {
     setAlertPeriods(prev => prev.filter(a => a.id !== alertId));
     // Backend endpoint for deleteAlert isn't defined in types but we assume user adds it
     // await api.deleteAlert(alertId); 
  };

  const handleBatchUpdatePresence = async (updatedUsers: User[]) => {
     setTeamUsers(prev => prev.map(u => {
        const match = updatedUsers.find(upd => upd.id === u.id);
        return match ? match : u;
     }));

     if (getApiUrl()) {
        await api.saveUsersBatch(updatedUsers);
        fetchData(); 
     }
  };

  const isLeader = currentUser.role === 'LEADER' || currentUser.role === 'COORDINATOR';
  const isCoordinator = currentUser.role === 'COORDINATOR';

  // MAIN FILTER LOGIC
  const displayedTasks = tasks.filter(task => {
    const assignee = teamUsers.find(u => u.id === task.assigneeId);
    if (!assignee) return false;

    let passesScope = false;
    if (filterScope === 'ME') {
      passesScope = assignee.id === currentUser.id;
    } else if (filterScope === 'MY_TEAM') {
      passesScope = assignee.teamId === currentUser.teamId;
    } else if (filterScope === 'ALL_TEAMS') {
      passesScope = true;
    } else {
      passesScope = assignee.teamId === filterScope;
    }

    if (!passesScope) return false;

    if (viewMode === 'LIST' && filterStatus !== 'ALL') {
       if (task.status !== filterStatus) return false;
    }

    return true;
  });

  const displayedAlerts = alertPeriods.filter(alert => {
     if (!alert.targetTeamId || alert.targetTeamId === 'ALL') return true;
     return alert.targetTeamId === currentUser.teamId || isCoordinator;
  });

  // Filter notifications for current user
  const myNotifications = notifications.filter(n => n.targetUserId === currentUser.id);

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">

      {/* Sidebar - Adjusted Layout */}
      <aside className="w-16 lg:w-72 bg-slate-900 text-slate-300 flex flex-col flex-shrink-0 shadow-xl z-20 transition-all">
        {/* Updated Title and Slogan - Stacked but minimal */}
        <div className="p-4 lg:p-6 border-b border-slate-800 flex items-center justify-center lg:justify-start gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg text-white shrink-0">
             <Layout size={24} />
          </div>
          <div className="hidden lg:flex flex-col">
             <h1 className="text-xl font-bold tracking-tight text-white leading-none mb-1">GestãoPRO</h1>
             <span className="text-[10px] text-slate-400 font-medium whitespace-nowrap">Organizador de Demandas</span>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          <button onClick={() => setViewMode('CALENDAR')} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'CALENDAR' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <CheckSquare size={20} />
            <span className="hidden lg:inline">Minhas Demandas</span>
          </button>

          <button onClick={() => { setViewMode('DASHBOARD'); setFilterStatus('ALL'); }} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'DASHBOARD' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <PieChart size={20} />
            <span className="hidden lg:inline">Indicadores</span>
          </button>

          <button onClick={() => setViewMode('REPORTS')} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'REPORTS' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <FileBarChart size={20} />
            <span className="hidden lg:inline">Relatórios</span>
          </button>

          <button onClick={() => setIsPresencialModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
            <MapPin size={20} />
            <span className="hidden lg:inline">Escala Presencial</span>
          </button>

          {isLeader && (
            <>
              <div className="my-2 border-t border-slate-800"></div>
              <button onClick={() => setIsTeamModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
                <Settings size={20} />
                <span className="hidden lg:inline">Gerenciar Equipe</span>
              </button>
              <button onClick={() => setIsAlertModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-orange-400">
                <AlertTriangle size={20} />
                <span className="hidden lg:inline">Criar Alerta</span>
              </button>
            </>
          )}
        </nav>

        {/* Database Config */}
        <div className="p-2 bg-slate-950">
           <button 
             onClick={() => { setIsConfigOpen(true); setConfigError(null); }}
             className="w-full flex items-center justify-center lg:justify-start gap-3 p-3 rounded-lg hover:bg-slate-800 transition-colors group"
             title={connectionStatus === 'CONNECTED' ? 'Conexão Ativa' : 'Sem Conexão'}
           >
              <div className="relative">
                 <Database size={20} className="text-slate-400 group-hover:text-white transition-colors" />
                 <div className={`absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full border-2 border-slate-900 ${
                    connectionStatus === 'CONNECTED' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.6)]' : 
                    connectionStatus === 'ERROR' ? 'bg-red-500' : 
                    'bg-slate-600'
                 }`}></div>
              </div>
              <span className="hidden lg:inline text-sm font-medium text-slate-300 group-hover:text-white">
                Banco de Dados
              </span>
              {isSyncing && <Loader2 size={14} className="animate-spin ml-auto text-slate-500" />}
           </button>
        </div>

        {/* User Switcher with Password Protection */}
        <div className="relative border-t border-slate-800 bg-slate-950 p-2" ref={userSwitcherRef}>
           <button 
             onClick={() => setIsUserSwitcherOpen(!isUserSwitcherOpen)}
             className="w-full flex items-center justify-center lg:justify-start gap-3 p-2 rounded hover:bg-slate-800 transition-colors"
           >
              <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center overflow-hidden">
                 <Users size={16} className="text-slate-300" />
              </div>
              <div className="hidden lg:block text-left">
                 <div className="text-xs font-bold text-slate-400">Alternar Usuário</div>
              </div>
           </button>

           {isUserSwitcherOpen && (
              <div className="absolute bottom-full left-2 w-56 bg-slate-800 border border-slate-700 rounded-lg shadow-xl mb-2 p-1 z-50 max-h-60 overflow-y-auto">
                 {teamUsers.map(u => (
                   <button
                     key={u.id}
                     onClick={() => handleUserSwitchClick(u)}
                     className={`w-full flex items-center gap-2 p-2 rounded text-sm ${currentUser.id === u.id ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-700'}`}
                   >
                     <img src={u.avatar} className="w-6 h-6 rounded-full" alt=""/>
                     <span className="truncate">{u.name}</span>
                     {!u.password && <span className="ml-auto w-2 h-2 rounded-full bg-red-500" title="Sem senha"></span>}
                   </button>
                 ))}
              </div>
           )}
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shadow-sm z-10 gap-4">

          <div className="flex items-center gap-4">
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button
                onClick={() => setViewMode('CALENDAR')}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${
                  viewMode === 'CALENDAR' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                <CalendarIcon size={16} />
                <span className="hidden sm:inline">Calendário</span>
              </button>
              <button
                onClick={() => { setViewMode('LIST'); setFilterStatus('ALL'); }}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${
                  viewMode === 'LIST' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                <List size={16} />
                <span className="hidden sm:inline">Lista</span>
              </button>
            </div>

            <div className="h-6 w-px bg-slate-200 mx-2 hidden sm:block"></div>

            {(viewMode === 'CALENDAR' || viewMode === 'LIST' || viewMode === 'DASHBOARD' || viewMode === 'REPORTS') && (
               <div className="flex items-center gap-2">
                 <Filter size={16} className="text-slate-400" />
                 <select 
                   value={filterScope}
                   onChange={(e) => setFilterScope(e.target.value)}
                   className="bg-slate-50 border-none text-sm font-medium text-slate-700 rounded-md focus:ring-0 cursor-pointer hover:bg-slate-100 py-1.5 pl-2 pr-8"
                 >
                    <option value="ME">Apenas Minhas</option>
                    <option value="MY_TEAM">Minha Equipe</option>
                    {isCoordinator && (
                      <>
                        <option disabled>──────────</option>
                        <option value="ALL_TEAMS">Todas as Equipes</option>
                        {teams.map(team => (
                          <option key={team.id} value={team.id}>Equipe: {team.name}</option>
                        ))}
                      </>
                    )}
                 </select>
               </div>
            )}
          </div>

          <div className="flex items-center gap-6">
            {/* Notifications */}
            <div className="relative" ref={notificationRef}>
              <button 
                onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
                className="text-slate-400 hover:text-indigo-600 transition-colors relative"
              >
                 <Bell size={20} />
                 {myNotifications.filter(n => !n.read).length > 0 && (
                   <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-bounce"></span>
                 )}
              </button>

              {isNotificationsOpen && (
                 <div className="absolute right-0 top-full mt-2 w-72 bg-white border border-slate-200 rounded-xl shadow-xl z-50 overflow-hidden">
                    <div className="bg-slate-50 px-4 py-2 border-b border-slate-100 text-xs font-bold text-slate-500">
                        Notificações ({myNotifications.filter(n => !n.read).length})
                    </div>
                    <div className="max-h-64 overflow-y-auto custom-scrollbar">
                       {myNotifications.length === 0 ? (
                         <div className="p-4 text-center text-xs text-slate-400">Nenhuma notificação nova.</div>
                       ) : (
                        myNotifications.map(n => (
                           <div key={n.id} className="p-3 border-b border-slate-50 hover:bg-slate-50 transition-colors">
                              <p className={`text-sm ${n.type === 'NUDGE' ? 'text-amber-700 font-bold' : 'text-slate-700'}`}>{n.message}</p>
                              <span className="text-[10px] text-slate-400">{format(n.date, 'dd/MM HH:mm')}</span>
                           </div>
                         ))
                       )}
                    </div>
                    {myNotifications.length > 0 && (
                        <div className="bg-slate-50 p-2 text-center border-t border-slate-100">
                            <button 
                                onClick={() => setNotifications(prev => prev.filter(n => n.targetUserId !== currentUser.id))} 
                                className="text-xs text-indigo-600 font-medium hover:underline"
                            >
                                Limpar Minhas Notificações
                            </button>
                        </div>
                    )}
                 </div>
              )}
            </div>

            {/* Change Password Button */}
            <button 
               onClick={handleChangePasswordClick}
               className="text-slate-400 hover:text-indigo-600 transition-colors"
               title="Alterar Senha"
            >
               <KeyRound size={18} />
            </button>

            <div className="flex items-center gap-3 pl-6 border-l border-slate-200">
              <div className="text-right hidden sm:block">
                <div className="text-sm font-bold text-slate-800">{currentUser.name}</div>
                <div className="text-xs text-slate-500">
                   {currentUser.role === 'COORDINATOR' ? 'Coordenador' : currentUser.role === 'LEADER' ? 'Líder' : 'Membro'}
                </div>
              </div>
              <img src={currentUser.avatar} alt="User" className="w-9 h-9 rounded-full border border-slate-200 shadow-sm" />
            </div>
          </div>
        </header>

        {/* Content */}
        <div className="flex-1 p-4 lg:p-6 overflow-hidden flex flex-col bg-slate-50">
          <div className="flex-1 h-full min-h-0">
            {viewMode === 'CALENDAR' ? (
              <Calendar 
                tasks={displayedTasks} 
                users={teamUsers}
                alertPeriods={displayedAlerts}
                currentUser={currentUser}
                onAddTask={handleAddTask}
                onEditTask={handleEditTask}
              />
            ) : viewMode === 'LIST' ? (
              <TaskListView 
                tasks={displayedTasks}
                currentUser={currentUser}
                onEditTask={handleEditTask}
              />
            ) : viewMode === 'DASHBOARD' ? (
              <DashboardView 
                tasks={displayedTasks} 
                users={teamUsers}
                onFilterRequest={(status) => {
                   setFilterStatus(status);
                   setViewMode('LIST');
                }}
              />
            ) : (
              <ReportsView 
                 tasks={displayedTasks}
                 users={teamUsers}
              />
            )}
          </div>
        </div>
      </main>

      {/* Config Modal */}
      {isConfigOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
           <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden p-6 text-center animate-in fade-in zoom-in duration-200 relative">
              <button 
                onClick={() => setIsConfigOpen(false)}
                className="absolute top-4 right-4 text-slate-400 hover:text-slate-600 transition-colors"
              >
                 <X size={24} />
              </button>

              <div className="w-16 h-16 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center mx-auto mb-4">
                 <Database size={32} />
              </div>
              <h2 className="text-xl font-bold text-slate-900 mb-2">Conectar Google Sheets</h2>
              <p className="text-slate-500 text-sm mb-6">
                 Para sincronizar dados entre a equipe, insira a URL do Web App do Google Apps Script abaixo.
              </p>

              {configError && (
                 <div className="mb-4 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-700 flex items-start gap-2 text-left">
                    <XCircle size={16} className="mt-0.5 flex-shrink-0" />
                    <div>{configError}</div>
                 </div>
              )}

              <div className="text-left mb-4">
                 <label className="block text-xs font-bold text-slate-700 uppercase mb-1">URL da API (Script Google)</label>
                 <div className="flex gap-2">
                   <div className="relative flex-1">
                      <LinkIcon className="absolute left-3 top-2.5 text-slate-400" size={16} />
                      <input 
                        type="text" 
                        value={apiUrlInput}
                        onChange={(e) => setApiUrlInput(e.target.value)}
                        placeholder="https://script.google.com/macros/s/..."
                        className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500"
                      />
                   </div>
                 </div>
              </div>

              <div className="flex gap-3">
                 <button 
                   onClick={() => setIsConfigOpen(false)}
                   className="flex-1 py-2 text-sm font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
                 >
                   Usar Offline (Demo)
                 </button>
                 <button 
                   onClick={handleConnect}
                   disabled={!apiUrlInput || isSyncing}
                   className="flex-1 py-2 text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-lg shadow-indigo-200 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                 >
                   {isSyncing ? <Loader2 size={16} className="animate-spin" /> : 'Conectar e Sincronizar'}
                 </button>
              </div>

              <div className="mt-6 pt-6 border-t border-slate-100 text-xs text-slate-400 text-left">
                 <p className="mb-2 font-bold">Instruções:</p>
                 <ol className="list-decimal pl-4 space-y-1">
                    <li>Copie o novo código do Apps Script (versão com senha).</li>
                    <li>Vá em <strong>Implantar</strong> {'>'} <strong>Nova implantação</strong>.</li>
                    <li>Cole a URL gerada acima.</li>
                 </ol>
              </div>
           </div>
        </div>
      )}

      {/* Auth Modal (Password) */}
      <UserAuthModal 
        isOpen={isAuthModalOpen}
        onClose={() => setIsAuthModalOpen(false)}
        targetUser={authTargetUser}
        mode={authMode}
        onSuccess={handleAuthSuccess}
      />

      {/* Other Modals */}
      <TaskModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        onRequestTransfer={() => {}} 
        initialTask={selectedTask}
        selectedDate={selectedDate}
        currentUser={currentUser}
        users={teamUsers}
        teams={teams}
      />

      <TeamModal 
        isOpen={isTeamModalOpen}
        onClose={() => setIsTeamModalOpen(false)}
        users={teamUsers}
        teams={teams}
        onAddUser={handleAddUser}
        onEditUser={handleEditUser}
        onRemoveUser={handleRemoveUser}
        onAddTeam={handleAddTeam}
        onRemoveTeam={handleRemoveTeam}
      />

      <AlertModal 
        isOpen={isAlertModalOpen}
        onClose={() => setIsAlertModalOpen(false)}
        onSave={handleSaveAlert}
        onDelete={handleDeleteAlert}
        alertPeriods={alertPeriods}
        teams={teams}
      />

      <PresencialModal 
        isOpen={isPresencialModalOpen}
        onClose={() => setIsPresencialModalOpen(false)}
        users={teamUsers}
        teams={teams}
        currentUser={currentUser}
        onSavePresence={handleBatchUpdatePresence}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import TaskListView from './components/TaskListView';
import TeamModal from './components/TeamModal';
import AlertModal from './components/AlertModal';
import DashboardView from './components/DashboardView';
import PresencialModal from './components/PresencialModal';
import UserAuthModal from './components/UserAuthModal'; 

import { User, Task, AlertPeriod, normalizeDate, Team, Notification, TaskStatus } from './types';
import { USERS, INITIAL_TASKS, INITIAL_TEAMS } from './constants';
import { api, setApiUrl, getApiUrl } from './services/api';
import { Layout, CheckSquare, List, Calendar as CalendarIcon, Settings, PieChart, MapPin, AlertTriangle, Users, User as UserIcon, Database, Link as LinkIcon, RefreshCw, Loader2, XCircle, X, Filter, KeyRound, Bell } from 'lucide-react';
import { format, isValid } from 'date-fns';

const App: React.FC = () => {
  // Config State
  const [isConfigOpen, setIsConfigOpen] = useState(!getApiUrl());
  const [apiUrlInput, setApiUrlInput] = useState(getApiUrl());
  const [isSyncing, setIsSyncing] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'DISCONNECTED' | 'CONNECTED' | 'ERROR'>('DISCONNECTED');
  const [configError, setConfigError] = useState<string | null>(null);

  const [currentUser, setCurrentUser] = useState<User>(USERS[0]); 

  // Data State
  const [tasks, setTasks] = useState<Task[]>([]);
  const [teamUsers, setTeamUsers] = useState<User[]>([]);
  const [teams, setTeams] = useState<Team[]>([]);
  const [alertPeriods, setAlertPeriods] = useState<AlertPeriod[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const [viewMode, setViewMode] = useState<'CALENDAR' | 'LIST' | 'DASHBOARD'>('CALENDAR');
  const [filterScope, setFilterScope] = useState<string>('MY_TEAM'); 
  const [filterStatus, setFilterStatus] = useState<TaskStatus | 'ALL'>('ALL'); // For Dashboard filtering

  // Modals State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [isAlertModalOpen, setIsAlertModalOpen] = useState(false);
  const [isPresencialModalOpen, setIsPresencialModalOpen] = useState(false);
  const [isUserSwitcherOpen, setIsUserSwitcherOpen] = useState(false);
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);

  // Auth Modal State
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authTargetUser, setAuthTargetUser] = useState<User | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'CHANGE_PASSWORD'>('LOGIN');

  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  // Refs for click outside
  const userSwitcherRef = useRef<HTMLDivElement>(null);
  const notificationRef = useRef<HTMLDivElement>(null);

  // Ref for notifications comparison (to avoid stale state in interval)
  const tasksRef = useRef<Task[]>([]);
  const isFirstLoadRef = useRef(true);

  // Keep refs synced
  useEffect(() => {
    tasksRef.current = tasks;
  }, [tasks]);

  // --- CLICK OUTSIDE HANDLER ---
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (userSwitcherRef.current && !userSwitcherRef.current.contains(event.target as Node)) {
        setIsUserSwitcherOpen(false);
      }
      if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // --- API & SYNC LOGIC ---

  const fetchData = async (): Promise<boolean> => {
    if (!getApiUrl()) return false;

    try {
      setIsSyncing(true);
      const data = await api.sync();

      // PARSE TASKS
      const parsedTasks: Task[] = data.tasks.map((t: any) => {
        let dateObj;
        if (typeof t.date === 'string' && t.date.includes('-') && !t.date.includes('T')) {
           const [y, m, d] = t.date.split('-').map(Number);
           dateObj = new Date(y, m - 1, d);
        } else if (typeof t.date === 'string') {
           const datePart = t.date.substring(0, 10);
           if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
             const [y, m, d] = datePart.split('-').map(Number);
             dateObj = new Date(y, m - 1, d);
           } else {
             dateObj = new Date(t.date);
           }
        } else {
           dateObj = new Date(t.date);
        }

        const cleanTime = (val: any) => {
          if (!val) return '';
          const strVal = String(val);
          if (strVal.match(/^\d{1,2}:\d{2}$/)) return strVal;
          const d = new Date(strVal);
          if (isValid(d)) return format(d, 'HH:mm');
          return strVal;
        };

        return { 
          ...t, 
          date: dateObj,
          startTime: cleanTime(t.startTime),
          endTime: cleanTime(t.endTime)
        };
      });

      const parsedAlerts: AlertPeriod[] = data.alerts.map((a: any) => {
         let start, end;
         if (typeof a.startDate === 'string') {
            const datePart = a.startDate.substring(0, 10);
            if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
               const [y, m, d] = datePart.split('-').map(Number);
               start = new Date(y, m - 1, d);
            } else start = new Date(a.startDate);
         } else start = new Date(a.startDate);

         if (typeof a.endDate === 'string') {
             const datePart = a.endDate.substring(0, 10);
             if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
                const [y, m, d] = datePart.split('-').map(Number);
                end = new Date(y, m - 1, d);
             } else end = new Date(a.endDate);
         } else end = new Date(a.endDate);

         return { ...a, startDate: start, endDate: end };
      });

      const parsedUsers: User[] = data.users.map((u: any) => ({
        ...u,
        presencialDates: Array.isArray(u.presencialDates) ? u.presencialDates : [],
        password: (u.password !== undefined && u.password !== null && u.password !== '') ? String(u.password) : undefined
      }));

      const parsedTeams: Team[] = data.teams || [];

      // CHECK NOTIFICATIONS (Improved Logic)
      if (!isFirstLoadRef.current && tasksRef.current.length > 0) {
         parsedTasks.forEach(newTask => {
             const oldTask = tasksRef.current.find(t => t.id === newTask.id);

             // 1. New Assignment
             if ((!oldTask || oldTask.assigneeId !== newTask.assigneeId) && newTask.assigneeId) {
                // Avoid duplicates
                setNotifications(prev => {
                    const exists = prev.some(n => n.type === 'TASK_ASSIGNED' && n.message.includes(newTask.title) && n.targetUserId === newTask.assigneeId);
                    if (exists) return prev;
                    return [
                        { 
                          id: crypto.randomUUID(), 
                          targetUserId: newTask.assigneeId,
                          message: `Nova demanda atribuída: ${newTask.title}`, 
                          date: new Date(), 
                          read: false, 
                          type: 'TASK_ASSIGNED' 
                        },
                        ...prev
                    ];
                });
             }

             // 2. Nudge (Cobrança) - If isNudged changed to true
             if (newTask.isNudged && (!oldTask || !oldTask.isNudged)) {
                 setNotifications(prev => {
                     const exists = prev.some(n => n.type === 'NUDGE' && n.message.includes(newTask.title) && n.targetUserId === newTask.assigneeId);
                     if (exists) return prev;
                     return [
                         {
                           id: crypto.randomUUID(),
                           targetUserId: newTask.assigneeId,
                           message: `⚠️ URGENTE / COBRANÇA: A demanda "${newTask.title}" foi sinalizada.`,
                           date: new Date(),
                           read: false,
                           type: 'NUDGE'
                         },
                         ...prev
                     ]
                 });
             }
         });
      }
      isFirstLoadRef.current = false;

      setTasks(parsedTasks);

      if (parsedUsers.length > 0) {
        setTeamUsers(prevUsers => {
            return parsedUsers.map(serverUser => {
                const localUser = prevUsers.find(u => u.id === serverUser.id);
                if (localUser?.password && !serverUser.password) {
                    return { ...serverUser, password: localUser.password };
                }
                return serverUser;
            });
        });
      } else {
        setTeamUsers(USERS);
      }

      if (parsedTeams.length > 0) setTeams(parsedTeams);
      else setTeams(INITIAL_TEAMS);

      setAlertPeriods(parsedAlerts);

      setTeamUsers(currentList => {
         const foundCurrent = currentList.find(u => u.id === currentUser.id);
         if (foundCurrent) {
            if (foundCurrent.name !== currentUser.name || foundCurrent.role !== currentUser.role || foundCurrent.teamId !== currentUser.teamId) {
               setCurrentUser(prev => ({ ...prev, ...foundCurrent }));
            }
         } else if (currentList.length > 0 && !currentList.find(u => u.id === currentUser.id)) {
            setCurrentUser(currentList[0]);
         }
         return currentList; 
      });

      setConnectionStatus('CONNECTED');
      return true;
    } catch (error) {
      console.error("Sync Error", error);
      setConnectionStatus('ERROR');
      return false;
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (getApiUrl()) {
      fetchData();
      const intervalId = setInterval(fetchData, 5000);
      return () => clearInterval(intervalId);
    } else {
      setTasks(INITIAL_TASKS);
      setTeamUsers(USERS);
      setTeams(INITIAL_TEAMS);
      isFirstLoadRef.current = false; // For demo mode, enable notifications immediately
    }
  }, []); 

  useEffect(() => {
    setFilterScope('MY_TEAM');
  }, [currentUser.id]);

  const handleConnect = async () => {
    setConfigError(null);
    setIsSyncing(true);
    setApiUrl(apiUrlInput);
    isFirstLoadRef.current = true; // Reset first load on new connection

    const success = await fetchData();

    if (success) {
      setIsConfigOpen(false);
    } else {
      setConfigError("Não foi possível conectar. Verifique se autorizou o script e se a permissão de acesso está definida como 'Qualquer pessoa'.");
      setConnectionStatus('ERROR');
    }
    setIsSyncing(false);
  };

  // --- AUTH HANDLERS ---

  const handleUserSwitchClick = (user: User) => {
    setAuthTargetUser(user);
    setAuthMode('LOGIN');
    setIsAuthModalOpen(true);
    setIsUserSwitcherOpen(false); 
  };

  const handleChangePasswordClick = () => {
    setAuthTargetUser(currentUser);
    setAuthMode('CHANGE_PASSWORD');
    setIsAuthModalOpen(true);
  };

  const handleAuthSuccess = async (updatedUser?: User) => {
    if (updatedUser) {
        setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
        setCurrentUser(updatedUser);
        if (getApiUrl()) await api.saveUser(updatedUser);
    } else if (authTargetUser) {
        setCurrentUser(authTargetUser);
    }
    if (authMode === 'CHANGE_PASSWORD') alert("Senha alterada com sucesso!");
  };

  // --- DATA HANDLERS ---

  const handleAddTask = (date: Date) => {
    setSelectedDate(date);
    setSelectedTask(null);
    setIsModalOpen(true);
  };

  const handleEditTask = (task: Task) => {
    setSelectedTask(task);
    setSelectedDate(task.date);
    setIsModalOpen(true);
  };

  const handleSaveTask = async (taskToSave: Task) => {
    setTasks(prev => {
      const exists = prev.find(t => t.id === taskToSave.id);
      if (exists) return prev.map(t => t.id === taskToSave.id ? taskToSave : t);
      return [...prev, taskToSave];
    });

    if (getApiUrl()) {
      await api.saveTask(taskToSave);
      fetchData();
    }
  };

  const handleDeleteTask = async (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
    if (getApiUrl()) {
      await api.deleteTask(taskId);
      fetchData();
    }
  };

  const handleAddUser = async (newUser: User) => {
    setTeamUsers(prev => [...prev, newUser]);
    if (getApiUrl()) {
      await api.saveUser(newUser);
      fetchData();
    }
  };

  const handleEditUser = async (updatedUser: User) => {
    setTeamUsers(prev => prev.map(u => {
        if (u.id === updatedUser.id) {
            if (!updatedUser.password && u.password) {
                return { ...updatedUser, password: u.password };
            }
            return updatedUser;
        }
        return u;
    }));

    if (currentUser.id === updatedUser.id) {
       setCurrentUser(prev => {
         if (!updatedUser.password && prev.password) {
           return { ...updatedUser, password: prev.password };
         }
         return updatedUser;
       });
    }

    if (getApiUrl()) {
      const userToSend = { ...updatedUser };
      const localUser = teamUsers.find(u => u.id === updatedUser.id);
      if (localUser?.password && !userToSend.password) {
          userToSend.password = localUser.password;
      }
      await api.saveUser(userToSend);
      fetchData();
    }
  };

  const handleRemoveUser = async (userId: string) => {
    setTeamUsers(prev => prev.filter(u => u.id !== userId));
    if (getApiUrl()) {
      await api.deleteUser(userId);
      fetchData();
    }
  };

  const handleAddTeam = async (newTeam: Team) => {
    setTeams(prev => [...prev, newTeam]);
    if (getApiUrl()) {
      await api.saveTeam(newTeam);
      fetchData();
    }
  };

  const handleRemoveTeam = async (teamId: string) => {
    setTeams(prev => prev.filter(t => t.id !== teamId));
    if (getApiUrl()) {
      await api.deleteTeam(teamId);
      fetchData();
    }
  };

  const handleSaveAlert = async (newAlert: AlertPeriod) => {
    setAlertPeriods(prev => {
       const exists = prev.find(a => a.id === newAlert.id);
       if (exists) return prev.map(a => a.id === newAlert.id ? newAlert : a);
       return [...prev, newAlert];
    });

    if (getApiUrl()) {
      await api.saveAlert(newAlert);
      fetchData();
    }
  };

  const handleDeleteAlert = async (alertId: string) => {
     setAlertPeriods(prev => prev.filter(a => a.id !== alertId));
     // Backend endpoint for deleteAlert isn't defined in types but we assume user adds it
     // await api.deleteAlert(alertId); 
  };

  const handleBatchUpdatePresence = async (updatedUsers: User[]) => {
     setTeamUsers(prev => prev.map(u => {
        const match = updatedUsers.find(upd => upd.id === u.id);
        return match ? match : u;
     }));

     if (getApiUrl()) {
        await api.saveUsersBatch(updatedUsers);
        fetchData(); 
     }
  };

  const isLeader = currentUser.role === 'LEADER' || currentUser.role === 'COORDINATOR';
  const isCoordinator = currentUser.role === 'COORDINATOR';

  // MAIN FILTER LOGIC
  const displayedTasks = tasks.filter(task => {
    const assignee = teamUsers.find(u => u.id === task.assigneeId);
    if (!assignee) return false;

    let passesScope = false;
    if (filterScope === 'ME') {
      passesScope = assignee.id === currentUser.id;
    } else if (filterScope === 'MY_TEAM') {
      passesScope = assignee.teamId === currentUser.teamId;
    } else if (filterScope === 'ALL_TEAMS') {
      passesScope = true;
    } else {
      passesScope = assignee.teamId === filterScope;
    }

    if (!passesScope) return false;

    if (viewMode === 'LIST' && filterStatus !== 'ALL') {
       if (task.status !== filterStatus) return false;
    }

    return true;
  });

  const displayedAlerts = alertPeriods.filter(alert => {
     if (!alert.targetTeamId || alert.targetTeamId === 'ALL') return true;
     return alert.targetTeamId === currentUser.teamId || isCoordinator;
  });

  // Filter notifications for current user
  const myNotifications = notifications.filter(n => n.targetUserId === currentUser.id);

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">

      {/* Sidebar - Adjusted Layout */}
      <aside className="w-16 lg:w-72 bg-slate-900 text-slate-300 flex flex-col flex-shrink-0 shadow-xl z-20 transition-all">
        {/* Updated Title and Slogan - Stacked but minimal */}
        <div className="p-4 lg:p-6 border-b border-slate-800 flex items-center justify-center lg:justify-start gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg text-white shrink-0">
             <Layout size={24} />
          </div>
          <div className="hidden lg:flex flex-col">
             <h1 className="text-xl font-bold tracking-tight text-white leading-none mb-1">GestãoPRO</h1>
             <span className="text-[10px] text-slate-400 font-medium whitespace-nowrap">Organizador de Demandas</span>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          <button onClick={() => setViewMode('CALENDAR')} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'CALENDAR' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <CheckSquare size={20} />
            <span className="hidden lg:inline">Minhas Demandas</span>
          </button>

          <button onClick={() => { setViewMode('DASHBOARD'); setFilterStatus('ALL'); }} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'DASHBOARD' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <PieChart size={20} />
            <span className="hidden lg:inline">Indicadores</span>
          </button>

          <button onClick={() => setIsPresencialModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
            <MapPin size={20} />
            <span className="hidden lg:inline">Escala Presencial</span>
          </button>

          {isLeader && (
            <>
              <div className="my-2 border-t border-slate-800"></div>
              <button onClick={() => setIsTeamModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
                <Settings size={20} />
                <span className="hidden lg:inline">Gerenciar Equipe</span>
              </button>
              <button onClick={() => setIsAlertModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-orange-400">
                <AlertTriangle size={20} />
                <span className="hidden lg:inline">Criar Alerta</span>
              </button>
            </>
          )}
        </nav>

        {/* Database Config */}
        <div className="p-2 bg-slate-950">
           <button 
             onClick={() => { setIsConfigOpen(true); setConfigError(null); }}
             className="w-full flex items-center justify-center lg:justify-start gap-3 p-3 rounded-lg hover:bg-slate-800 transition-colors group"
             title={connectionStatus === 'CONNECTED' ? 'Conexão Ativa' : 'Sem Conexão'}
           >
              <div className="relative">
                 <Database size={20} className="text-slate-400 group-hover:text-white transition-colors" />
                 <div className={`absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full border-2 border-slate-900 ${
                    connectionStatus === 'CONNECTED' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.6)]' : 
                    connectionStatus === 'ERROR' ? 'bg-red-500' : 
                    'bg-slate-600'
                 }`}></div>
              </div>
              <span className="hidden lg:inline text-sm font-medium text-slate-300 group-hover:text-white">
                Banco de Dados
              </span>
              {isSyncing && <Loader2 size={14} className="animate-spin ml-auto text-slate-500" />}
           </button>
        </div>

        {/* User Switcher with Password Protection */}
        <div className="relative border-t border-slate-800 bg-slate-950 p-2" ref={userSwitcherRef}>
           <button 
             onClick={() => setIsUserSwitcherOpen(!isUserSwitcherOpen)}
             className="w-full flex items-center justify-center lg:justify-start gap-3 p-2 rounded hover:bg-slate-800 transition-colors"
           >
              <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center overflow-hidden">
                 <Users size={16} className="text-slate-300" />
              </div>
              <div className="hidden lg:block text-left">
                 <div className="text-xs font-bold text-slate-400">Alternar Usuário</div>
              </div>
           </button>

           {isUserSwitcherOpen && (
              <div className="absolute bottom-full left-2 w-56 bg-slate-800 border border-slate-700 rounded-lg shadow-xl mb-2 p-1 z-50 max-h-60 overflow-y-auto">
                 {teamUsers.map(u => (
                   <button
                     key={u.id}
                     onClick={() => handleUserSwitchClick(u)}
                     className={`w-full flex items-center gap-2 p-2 rounded text-sm ${currentUser.id === u.id ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-700'}`}
                   >
                     <img src={u.avatar} className="w-6 h-6 rounded-full" alt=""/>
                     <span className="truncate">{u.name}</span>
                     {!u.password && <span className="ml-auto w-2 h-2 rounded-full bg-red-500" title="Sem senha"></span>}
                   </button>
                 ))}
              </div>
           )}
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shadow-sm z-10 gap-4">

          <div className="flex items-center gap-4">
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button
                onClick={() => setViewMode('CALENDAR')}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${
                  viewMode === 'CALENDAR' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                <CalendarIcon size={16} />
                <span className="hidden sm:inline">Calendário</span>
              </button>
              <button
                onClick={() => { setViewMode('LIST'); setFilterStatus('ALL'); }}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${
                  viewMode === 'LIST' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                <List size={16} />
                <span className="hidden sm:inline">Lista</span>
              </button>
            </div>

            <div className="h-6 w-px bg-slate-200 mx-2 hidden sm:block"></div>

            {(viewMode === 'CALENDAR' || viewMode === 'LIST' || viewMode === 'DASHBOARD') && (
               <div className="flex items-center gap-2">
                 <Filter size={16} className="text-slate-400" />
                 <select 
                   value={filterScope}
                   onChange={(e) => setFilterScope(e.target.value)}
                   className="bg-slate-50 border-none text-sm font-medium text-slate-700 rounded-md focus:ring-0 cursor-pointer hover:bg-slate-100 py-1.5 pl-2 pr-8"
                 >
                    <option value="ME">Apenas Minhas</option>
                    <option value="MY_TEAM">Minha Equipe</option>
                    {isCoordinator && (
                      <>
                        <option disabled>──────────</option>
                        <option value="ALL_TEAMS">Todas as Equipes</option>
                        {teams.map(team => (
                          <option key={team.id} value={team.id}>Equipe: {team.name}</option>
                        ))}
                      </>
                    )}
                 </select>
               </div>
            )}
          </div>

          <div className="flex items-center gap-6">
            {/* Notifications */}
            <div className="relative" ref={notificationRef}>
              <button 
                onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
                className="text-slate-400 hover:text-indigo-600 transition-colors relative"
              >
                 <Bell size={20} />
                 {myNotifications.filter(n => !n.read).length > 0 && (
                   <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-bounce"></span>
                 )}
              </button>

              {isNotificationsOpen && (
                 <div className="absolute right-0 top-full mt-2 w-72 bg-white border border-slate-200 rounded-xl shadow-xl z-50 overflow-hidden">
                    <div className="bg-slate-50 px-4 py-2 border-b border-slate-100 text-xs font-bold text-slate-500">
                        Notificações ({myNotifications.filter(n => !n.read).length})
                    </div>
                    <div className="max-h-64 overflow-y-auto custom-scrollbar">
                       {myNotifications.length === 0 ? (
                         <div className="p-4 text-center text-xs text-slate-400">Nenhuma notificação nova.</div>
                       ) : (
                        myNotifications.map(n => (
                           <div key={n.id} className="p-3 border-b border-slate-50 hover:bg-slate-50 transition-colors">
                              <p className={`text-sm ${n.type === 'NUDGE' ? 'text-amber-700 font-bold' : 'text-slate-700'}`}>{n.message}</p>
                              <span className="text-[10px] text-slate-400">{format(n.date, 'dd/MM HH:mm')}</span>
                           </div>
                         ))
                       )}
                    </div>
                    {myNotifications.length > 0 && (
                        <div className="bg-slate-50 p-2 text-center border-t border-slate-100">
                            <button 
                                onClick={() => setNotifications(prev => prev.filter(n => n.targetUserId !== currentUser.id))} 
                                className="text-xs text-indigo-600 font-medium hover:underline"
                            >
                                Limpar Minhas Notificações
                            </button>
                        </div>
                    )}
                 </div>
              )}
            </div>

            {/* Change Password Button */}
            <button 
               onClick={handleChangePasswordClick}
               className="text-slate-400 hover:text-indigo-600 transition-colors"
               title="Alterar Senha"
            >
               <KeyRound size={18} />
            </button>

            <div className="flex items-center gap-3 pl-6 border-l border-slate-200">
              <div className="text-right hidden sm:block">
                <div className="text-sm font-bold text-slate-800">{currentUser.name}</div>
                <div className="text-xs text-slate-500">
                   {currentUser.role === 'COORDINATOR' ? 'Coordenador' : currentUser.role === 'LEADER' ? 'Líder' : 'Membro'}
                </div>
              </div>
              <img src={currentUser.avatar} alt="User" className="w-9 h-9 rounded-full border border-slate-200 shadow-sm" />
            </div>
          </div>
        </header>

        {/* Content */}
        <div className="flex-1 p-4 lg:p-6 overflow-hidden flex flex-col bg-slate-50">
          <div className="flex-1 h-full min-h-0">
            {viewMode === 'CALENDAR' ? (
              <Calendar 
                tasks={displayedTasks} 
                users={teamUsers}
                alertPeriods={displayedAlerts}
                currentUser={currentUser}
                onAddTask={handleAddTask}
                onEditTask={handleEditTask}
              />
            ) : viewMode === 'LIST' ? (
              <TaskListView 
                tasks={displayedTasks}
                currentUser={currentUser}
                onEditTask={handleEditTask}
              />
            ) : (
              <DashboardView 
                tasks={displayedTasks} 
                users={teamUsers}
                onFilterRequest={(status) => {
                   setFilterStatus(status);
                   setViewMode('LIST');
                }}
              />
            )}
          </div>
        </div>
      </main>

      {/* Config Modal */}
      {isConfigOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
           <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden p-6 text-center animate-in fade-in zoom-in duration-200 relative">
              <button 
                onClick={() => setIsConfigOpen(false)}
                className="absolute top-4 right-4 text-slate-400 hover:text-slate-600 transition-colors"
              >
                 <X size={24} />
              </button>

              <div className="w-16 h-16 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center mx-auto mb-4">
                 <Database size={32} />
              </div>
              <h2 className="text-xl font-bold text-slate-900 mb-2">Conectar Google Sheets</h2>
              <p className="text-slate-500 text-sm mb-6">
                 Para sincronizar dados entre a equipe, insira a URL do Web App do Google Apps Script abaixo.
              </p>

              {configError && (
                 <div className="mb-4 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-700 flex items-start gap-2 text-left">
                    <XCircle size={16} className="mt-0.5 flex-shrink-0" />
                    <div>{configError}</div>
                 </div>
              )}

              <div className="text-left mb-4">
                 <label className="block text-xs font-bold text-slate-700 uppercase mb-1">URL da API (Script Google)</label>
                 <div className="flex gap-2">
                   <div className="relative flex-1">
                      <LinkIcon className="absolute left-3 top-2.5 text-slate-400" size={16} />
                      <input 
                        type="text" 
                        value={apiUrlInput}
                        onChange={(e) => setApiUrlInput(e.target.value)}
                        placeholder="https://script.google.com/macros/s/..."
                        className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500"
                      />
                   </div>
                 </div>
              </div>

              <div className="flex gap-3">
                 <button 
                   onClick={() => setIsConfigOpen(false)}
                   className="flex-1 py-2 text-sm font-medium text-slate-600 hover:bg-slate-100 rounded-lg"
                 >
                   Usar Offline (Demo)
                 </button>
                 <button 
                   onClick={handleConnect}
                   disabled={!apiUrlInput || isSyncing}
                   className="flex-1 py-2 text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-lg shadow-indigo-200 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                 >
                   {isSyncing ? <Loader2 size={16} className="animate-spin" /> : 'Conectar e Sincronizar'}
                 </button>
              </div>

              <div className="mt-6 pt-6 border-t border-slate-100 text-xs text-slate-400 text-left">
                 <p className="mb-2 font-bold">Instruções:</p>
                 <ol className="list-decimal pl-4 space-y-1">
                    <li>Copie o novo código do Apps Script (versão com senha).</li>
                    <li>Vá em <strong>Implantar</strong> {'>'} <strong>Nova implantação</strong>.</li>
                    <li>Cole a URL gerada acima.</li>
                 </ol>
              </div>
           </div>
        </div>
      )}

      {/* Auth Modal (Password) */}
      <UserAuthModal 
        isOpen={isAuthModalOpen}
        onClose={() => setIsAuthModalOpen(false)}
        targetUser={authTargetUser}
        mode={authMode}
        onSuccess={handleAuthSuccess}
      />

      {/* Other Modals */}
      <TaskModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        onRequestTransfer={() => {}} 
        initialTask={selectedTask}
        selectedDate={selectedDate}
        currentUser={currentUser}
        users={teamUsers}
        teams={teams}
      />

      <TeamModal 
        isOpen={isTeamModalOpen}
        onClose={() => setIsTeamModalOpen(false)}
        users={teamUsers}
        teams={teams}
        onAddUser={handleAddUser}
        onEditUser={handleEditUser}
        onRemoveUser={handleRemoveUser}
        onAddTeam={handleAddTeam}
        onRemoveTeam={handleRemoveTeam}
      />

      <AlertModal 
        isOpen={isAlertModalOpen}
        onClose={() => setIsAlertModalOpen(false)}
        onSave={handleSaveAlert}
        onDelete={handleDeleteAlert}
        alertPeriods={alertPeriods}
        teams={teams}
      />

      <PresencialModal 
        isOpen={isPresencialModalOpen}
        onClose={() => setIsPresencialModalOpen(false)}
        users={teamUsers}
        teams={teams}
        currentUser={currentUser}
        onSavePresence={handleBatchUpdatePresence}
      />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Task, User, TaskStatus } from '../types';
import { STATUS_LABELS } from '../constants';
import { isSameDay, format, startOfMonth, endOfMonth, eachDayOfInterval, isSameMonth, subMonths, addMonths } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { PieChart, UserCheck, Home, ArrowRight, CalendarDays, FileDown, Activity, ChevronLeft, ChevronRight, CheckCircle2 } from 'lucide-react';

interface DashboardViewProps {
  tasks: Task[];
  users: User[];
  currentDate?: Date; // Default to today
  onFilterRequest?: (status: TaskStatus | 'ALL') => void;
}

const DashboardView: React.FC<DashboardViewProps> = ({ tasks, users, currentDate = new Date(), onFilterRequest }) => {
  const [activeTab, setActiveTab] = useState<'DAILY' | 'MONTHLY'>('DAILY');
  const [reportMonth, setReportMonth] = useState(new Date());

  // --- DAILY VIEW LOGIC ---
  const todayTasks = tasks.filter(t => isSameDay(new Date(t.date), currentDate));

  const dailyStats = {
    TODO: todayTasks.filter(t => t.status === 'TODO'),
    IN_PROGRESS: todayTasks.filter(t => t.status === 'IN_PROGRESS'),
    DONE: todayTasks.filter(t => t.status === 'DONE'),
  };

  const totalToday = todayTasks.length;
  const currentDateStr = format(currentDate, 'yyyy-MM-dd');
  const presencialUsers = users.filter(u => u.presencialDates.includes(currentDateStr));
  const homeOfficeUsers = users.filter(u => !u.presencialDates.includes(currentDateStr));

  // --- MONTHLY REPORT LOGIC ---
  const handlePrevMonth = () => setReportMonth(subMonths(reportMonth, 1));
  const handleNextMonth = () => setReportMonth(addMonths(reportMonth, 1));

  const monthlyTasks = tasks.filter(t => isSameMonth(t.date, reportMonth));
  const totalMonth = monthlyTasks.length;
  const doneMonth = monthlyTasks.filter(t => t.status === 'DONE').length;
  const inProgressMonth = monthlyTasks.filter(t => t.status === 'IN_PROGRESS').length;
  const todoMonth = monthlyTasks.filter(t => t.status === 'TODO').length;
  const completionRate = totalMonth > 0 ? Math.round((doneMonth / totalMonth) * 100) : 0;

  const userStats = users.map(user => {
    const userTasks = monthlyTasks.filter(t => t.assigneeId === user.id);
    const uDone = userTasks.filter(t => t.status === 'DONE').length;
    const uPending = userTasks.filter(t => t.status !== 'DONE').length;
    return {
       user,
       total: userTasks.length,
       done: uDone,
       pending: uPending,
       rate: userTasks.length > 0 ? Math.round((uDone / userTasks.length) * 100) : 0
    };
  }).filter(stat => stat.total > 0).sort((a, b) => b.total - a.total);

  const handleCardClick = (status: TaskStatus | 'ALL') => {
    if (onFilterRequest) {
      onFilterRequest(status);
    }
  };

  const downloadCSV = () => {
    const headers = ['Titulo', 'Descricao', 'Responsavel', 'Data', 'Inicio', 'Fim', 'Status', 'Prioridade'];
    const rows = monthlyTasks.map(t => {
       const user = users.find(u => u.id === t.assigneeId);
       return [
          `"${t.title.replace(/"/g, '""')}"`,
          `"${t.description.replace(/"/g, '""')}"`,
          `"${user ? user.name : 'N/A'}"`,
          format(t.date, 'dd/MM/yyyy'),
          t.startTime,
          t.endTime,
          STATUS_LABELS[t.status],
          t.priority
       ].join(',');
    });

    const csvContent = "data:text/csv;charset=utf-8," 
        + headers.join(',') + "\n" 
        + rows.join('\n');

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Relatorio_Atividades_${format(reportMonth, 'MMM_yyyy')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="bg-slate-50 h-full overflow-hidden flex flex-col">
      {/* Tabs Header */}
      <div className="bg-white border-b border-slate-200 px-6 pt-4 flex items-center justify-between shrink-0">
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2 mb-4">
            <PieChart className="text-indigo-600" /> Painel de Indicadores
          </h2>
          <div className="flex gap-4 mb-4">
             <button 
               onClick={() => setActiveTab('DAILY')}
               className={`pb-2 px-1 text-sm font-medium border-b-2 transition-colors ${activeTab === 'DAILY' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
             >
                Visão do Dia
             </button>
             <button 
               onClick={() => setActiveTab('MONTHLY')}
               className={`pb-2 px-1 text-sm font-medium border-b-2 transition-colors ${activeTab === 'MONTHLY' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
             >
                Relatório Mensal
             </button>
          </div>
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-6">

        {activeTab === 'DAILY' ? (
          <>
            {/* Summary Cards */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <button onClick={() => handleCardClick('ALL')} className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 text-left hover:shadow-md transition-all hover:scale-[1.02] group">
                <div className="text-sm text-slate-500 mb-1 flex justify-between">
                    Total Hoje <ArrowRight size={14} className="opacity-0 group-hover:opacity-100 transition-opacity" />
                </div>
                <div className="text-3xl font-bold text-slate-800">{totalToday}</div>
                </button>
                <button onClick={() => handleCardClick('TODO')} className="bg-white p-4 rounded-xl shadow-sm border border-l-4 border-l-slate-400 border-slate-200 text-left hover:shadow-md transition-all hover:scale-[1.02] group">
                <div className="text-sm text-slate-500 mb-1 flex justify-between">
                    Não Iniciado <ArrowRight size={14} className="opacity-0 group-hover:opacity-100 transition-opacity" />
                </div>
                <div className="text-3xl font-bold text-slate-600">{dailyStats.TODO.length}</div>
                </button>
                <button onClick={() => handleCardClick('IN_PROGRESS')} className="bg-white p-4 rounded-xl shadow-sm border border-l-4 border-l-amber-400 border-slate-200 text-left hover:shadow-md transition-all hover:scale-[1.02] group">
                <div className="text-sm text-slate-500 mb-1 flex justify-between">
                    Em Andamento <ArrowRight size={14} className="opacity-0 group-hover:opacity-100 transition-opacity" />
                </div>
                <div className="text-3xl font-bold text-amber-600">{dailyStats.IN_PROGRESS.length}</div>
                </button>
                <button onClick={() => handleCardClick('DONE')} className="bg-white p-4 rounded-xl shadow-sm border border-l-4 border-l-emerald-400 border-slate-200 text-left hover:shadow-md transition-all hover:scale-[1.02] group">
                <div className="text-sm text-slate-500 mb-1 flex justify-between">
                    Concluídas <ArrowRight size={14} className="opacity-0 group-hover:opacity-100 transition-opacity" />
                </div>
                <div className="text-3xl font-bold text-emerald-600">{dailyStats.DONE.length}</div>
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Activity List */}
                <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col">
                <div className="p-4 border-b border-slate-100 font-bold text-slate-700 flex items-center gap-2">
                    <CalendarDays size={18} /> Cronograma do Dia
                </div>
                <div className="p-4 overflow-y-auto max-h-96 custom-scrollbar">
                    {todayTasks.length === 0 ? (
                    <div className="text-center text-slate-400 py-8">Nenhuma atividade agendada para hoje.</div>
                    ) : (
                    <div className="space-y-4">
                        {(['TODO', 'IN_PROGRESS', 'DONE'] as TaskStatus[]).map(status => {
                            const statusTasks = todayTasks.filter(t => t.status === status);
                            if (statusTasks.length === 0) return null;
                            return (
                            <div key={status} className="space-y-2">
                                <h4 className="text-xs font-bold uppercase tracking-wider text-slate-500">{STATUS_LABELS[status]}</h4>
                                {statusTasks.map(task => {
                                    const assignee = users.find(u => u.id === task.assigneeId);
                                    return (
                                    <div key={task.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border border-slate-100">
                                        <div>
                                            <div className="font-semibold text-sm text-slate-800 flex items-center gap-2">
                                            {task.title}
                                            {task.isNudged && <span className="bg-red-100 text-red-600 text-[10px] px-1.5 py-0.5 rounded font-bold">COBRADO</span>}
                                            </div>
                                            <div className="text-xs text-slate-500">
                                            {task.startTime} - {task.endTime}
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <img src={assignee?.avatar} className="w-6 h-6 rounded-full" alt=""/>
                                            <span className="text-xs font-medium text-slate-700">{assignee?.name}</span>
                                        </div>
                                    </div>
                                    )
                                })}
                            </div>
                            )
                        })}
                    </div>
                    )}
                </div>
                </div>

                {/* Presence List */}
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-fit">
                <div className="p-4 border-b border-slate-100 font-bold text-slate-700 flex items-center gap-2">
                    <UserCheck size={18} /> Local de Trabalho (Hoje)
                </div>
                <div className="p-4 space-y-4 max-h-[500px] overflow-y-auto custom-scrollbar">
                    <div>
                        <h4 className="text-xs font-bold text-slate-400 uppercase mb-2">Presencial</h4>
                        <div className="space-y-2">
                        {presencialUsers.length === 0 && <span className="text-xs text-slate-400 italic">Ninguém no escritório hoje.</span>}
                        {presencialUsers.map(user => (
                            <div key={user.id} className="flex items-center gap-3 p-2 bg-green-50 rounded-lg border border-green-100">
                                <div className="relative">
                                <img src={user.avatar} className="w-8 h-8 rounded-full" alt="" />
                                <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 border-2 border-white rounded-full"></div>
                                </div>
                                <div>
                                <div className="text-sm font-medium text-slate-800">{user.name}</div>
                                <div className="text-[10px] text-slate-500 truncate max-w-[120px]">
                                    {users.find(u => u.id === user.id)?.role === 'COORDINATOR' ? 'Coordenador' : 'Membro'}
                                </div>
                                </div>
                            </div>
                        ))}
                        </div>
                    </div>
                    <div>
                        <h4 className="text-xs font-bold text-slate-400 uppercase mb-2">Home Office</h4>
                        <div className="space-y-2">
                        {homeOfficeUsers.length === 0 && <span className="text-xs text-slate-400 italic">Ninguém em home office.</span>}
                        {homeOfficeUsers.map(user => (
                            <div key={user.id} className="flex items-center gap-3 p-2 bg-slate-50 rounded-lg border border-slate-100 opacity-80">
                                <div className="relative">
                                <img src={user.avatar} className="w-8 h-8 rounded-full grayscale" alt="" />
                                <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-slate-400 border-2 border-white rounded-full"></div>
                                </div>
                                <div>
                                <div className="text-sm font-medium text-slate-600">{user.name}</div>
                                </div>
                                <Home size={14} className="ml-auto text-slate-400" />
                            </div>
                        ))}
                        </div>
                    </div>
                </div>
                </div>
            </div>
          </>
        ) : (
           /* MONTHLY REPORT VIEW */
           <div className="space-y-6">

              <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                 <div className="flex items-center bg-white border border-slate-200 rounded-lg p-1 shadow-sm">
                    <button onClick={handlePrevMonth} className="p-1 hover:bg-slate-100 rounded text-slate-600">
                    <ChevronLeft size={20} />
                    </button>
                    <span className="px-4 text-sm font-bold text-slate-700 min-w-[140px] text-center capitalize">
                    {format(reportMonth, 'MMMM yyyy', { locale: ptBR })}
                    </span>
                    <button onClick={handleNextMonth} className="p-1 hover:bg-slate-100 rounded text-slate-600">
                    <ChevronRight size={20} />
                    </button>
                 </div>

                 <button 
                   onClick={downloadCSV}
                   className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg shadow-sm text-sm font-medium transition-colors"
                 >
                    <FileDown size={18} />
                    Exportar Excel (.csv)
                 </button>
              </div>

              {/* Stats Cards */}
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="bg-indigo-50 rounded-xl p-4 border border-indigo-100">
                    <div className="text-xs font-bold text-indigo-500 uppercase mb-1">Total de Atividades</div>
                    <div className="text-3xl font-bold text-indigo-700">{totalMonth}</div>
                    <div className="text-xs text-indigo-400 mt-1">Neste mês</div>
                </div>

                <div className="bg-emerald-50 rounded-xl p-4 border border-emerald-100">
                    <div className="text-xs font-bold text-emerald-500 uppercase mb-1">Taxa de Conclusão</div>
                    <div className="text-3xl font-bold text-emerald-700">{completionRate}%</div>
                    <div className="w-full bg-emerald-200 h-1.5 rounded-full mt-2 overflow-hidden">
                    <div className="bg-emerald-500 h-full" style={{ width: `${completionRate}%` }}></div>
                    </div>
                </div>

                <div className="bg-amber-50 rounded-xl p-4 border border-amber-100">
                    <div className="text-xs font-bold text-amber-500 uppercase mb-1">Em Andamento</div>
                    <div className="text-3xl font-bold text-amber-700">{inProgressMonth}</div>
                </div>

                <div className="bg-slate-50 rounded-xl p-4 border border-slate-200">
                    <div className="text-xs font-bold text-slate-500 uppercase mb-1">Pendentes</div>
                    <div className="text-3xl font-bold text-slate-700">{todoMonth}</div>
                </div>
              </div>

              {/* Performance List */}
                <div className="bg-white rounded-xl border border-slate-200 overflow-hidden shadow-sm">
                   <div className="p-4 border-b border-slate-100 font-bold text-slate-700 flex items-center gap-2">
                      <CheckCircle2 size={18} /> Desempenho da Equipe ({format(reportMonth, 'MMM/yyyy', { locale: ptBR })})
                   </div>
                   {userStats.length === 0 ? (
                      <div className="p-4 text-center text-sm text-slate-400">Nenhum dado para este mês.</div>
                   ) : (
                      <div className="divide-y divide-slate-100">
                         {userStats.map((stat, idx) => (
                            <div key={stat.user.id} className="p-3 flex items-center justify-between hover:bg-slate-50 transition-colors">
                               <div className="flex items-center gap-3">
                                  <div className="text-xs font-bold text-slate-400 w-4">{idx + 1}</div>
                                  <img src={stat.user.avatar} className="w-8 h-8 rounded-full" alt=""/>
                                  <div>
                                     <div className="text-sm font-semibold text-slate-800">{stat.user.name}</div>
                                     <div className="text-xs text-slate-500">{stat.total} demandas</div>
                                  </div>
                               </div>
                               <div className="flex items-center gap-4 text-right">
                                  <div className="hidden sm:block">
                                     <div className="text-xs font-bold text-emerald-600">{stat.done} ok</div>
                                     <div className="text-[10px] text-slate-400">Concluídas</div>
                                  </div>
                                  <div className="hidden sm:block">
                                     <div className="text-xs font-bold text-slate-600">{stat.pending} pend</div>
                                     <div className="text-[10px] text-slate-400">Restantes</div>
                                  </div>
                                  <div className="w-12 text-center">
                                      <div className={`text-sm font-bold ${stat.rate >= 80 ? 'text-emerald-600' : stat.rate >= 50 ? 'text-amber-600' : 'text-red-600'}`}>
                                         {stat.rate}%
                                      </div>
                                  </div>
                               </div>
                            </div>
                         ))}
                      </div>
                   )}
                </div>
           </div>
        )}

      </div>
    </div>
  );
};

