### Código Atualizado do Google Apps Script (Backend)

Copie o código abaixo e substitua **todo** o conteúdo do seu arquivo `.gs` no Google Apps Script. Em seguida, clique em **Implantar > Nova Implantação > (Acesso: Qualquer pessoa) > Implantar**.

```javascript
/* 
  GestorPro - Backend v3.0 (Full Sync Support)

  Features:
  - Users with Passwords & Presence Dates
  - Tasks with Nudge (Cobrança) & Priority
  - Team Management
  - Alert Management
  - Batch Updates
*/

function doGet(e) {
  return handleRequest('read', null);
}

function doPost(e) {
  var action = e.parameter.action;
  var data = e.postData ? JSON.parse(e.postData.contents) : null;
  return handleRequest(action, data);
}

function handleRequest(action, data) {
  var lock = LockService.getScriptLock();
  lock.waitLock(30000); // Prevents concurrency issues

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var result = {};

    // Ensure sheets exist
    var sheets = ['Tasks', 'Users', 'Teams', 'Alerts'];
    sheets.forEach(function(name) {
      if (!ss.getSheetByName(name)) ss.insertSheet(name);
    });

    if (action === 'read') {
      result = readAllData(ss);
    } 
    else if (action === 'saveTask') {
      saveTask(ss, data);
      result = { success: true };
    }
    else if (action === 'deleteTask') {
      deleteRowById(ss, 'Tasks', data.id);
      result = { success: true };
    }
    else if (action === 'saveUser') {
      saveUser(ss, data);
      result = { success: true };
    }
    else if (action === 'saveUsersBatch') {
      // Expects data to be an array of Users
      if (Array.isArray(data)) {
        data.forEach(function(u) { saveUser(ss, u); });
      }
      result = { success: true };
    }
    else if (action === 'deleteUser') {
      deleteRowById(ss, 'Users', data.id);
      result = { success: true };
    }
    else if (action === 'saveTeam') {
      saveTeam(ss, data);
      result = { success: true };
    }
    else if (action === 'deleteTeam') {
      deleteRowById(ss, 'Teams', data.id);
      result = { success: true };
    }
    else if (action === 'saveAlert') {
      saveAlert(ss, data);
      result = { success: true };
    }

    return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ error: e.toString() })).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

// --- READ OPERATIONS ---

function readAllData(ss) {
  return {
    tasks: getSheetData(ss, 'Tasks'),
    users: getSheetData(ss, 'Users'),
    teams: getSheetData(ss, 'Teams'),
    alerts: getSheetData(ss, 'Alerts')
  };
}

function getSheetData(ss, sheetName) {
  var sheet = ss.getSheetByName(sheetName);
  var data = sheet.getDataRange().getValues();
  if (data.length < 2) return []; // Empty sheet

  var headers = data[0];
  var rows = data.slice(1);

  return rows.map(function(row) {
    var obj = {};
    headers.forEach(function(header, index) {
      var val = row[index];
      // Parse special fields
      if (header === 'presencialDates' && typeof val === 'string') {
        obj[header] = val ? val.split(',') : [];
      } else if (header === 'isNudged') {
        obj[header] = val === true || val === 'true';
      } else {
        obj[header] = val;
      }
    });
    return obj;
  });
}

// --- WRITE OPERATIONS ---

function saveTask(ss, task) {
  var sheet = ss.getSheetByName('Tasks');
  // Columns: id, title, description, assigneeId, date, startTime, endTime, status, priority, targetTeamId, isNudged
  var headers = ['id', 'title', 'description', 'assigneeId', 'date', 'startTime', 'endTime', 'status', 'priority', 'targetTeamId', 'isNudged'];
  ensureHeaders(sheet, headers);

  var rowData = [
    task.id,
    task.title,
    task.description,
    task.assigneeId,
    task.date, // Expecting yyyy-MM-dd string from client
    task.startTime,
    task.endTime,
    task.status,
    task.priority,
    task.targetTeamId || '',
    task.isNudged ? 'true' : 'false'
  ];

  upsertRow(sheet, task.id, rowData);
}

function saveUser(ss, user) {
  var sheet = ss.getSheetByName('Users');
  // Columns: id, name, email, role, teamId, avatar, presencialDates, password
  var headers = ['id', 'name', 'email', 'role', 'teamId', 'avatar', 'presencialDates', 'password'];
  ensureHeaders(sheet, headers);

  var pDates = Array.isArray(user.presencialDates) ? user.presencialDates.join(',') : '';

  var rowData = [
    user.id,
    user.name,
    user.email,
    user.role,
    user.teamId,
    user.avatar,
    pDates,
    user.password || ''
  ];

  upsertRow(sheet, user.id, rowData);
}

function saveTeam(ss, team) {
  var sheet = ss.getSheetByName('Teams');
  var headers = ['id', 'name', 'color'];
  ensureHeaders(sheet, headers);
  upsertRow(sheet, team.id, [team.id, team.name, team.color]);
}

function saveAlert(ss, alert) {
  var sheet = ss.getSheetByName('Alerts');
  var headers = ['id', 'startDate', 'endDate', 'label', 'color', 'targetTeamId'];
  ensureHeaders(sheet, headers);
  upsertRow(sheet, alert.id, [alert.id, alert.startDate, alert.endDate, alert.label, alert.color, alert.targetTeamId]);
}

// --- HELPER FUNCTIONS ---

function ensureHeaders(sheet, headers) {
  if (sheet.getLastRow() === 0) {
    sheet.appendRow(headers);
  }
}

function upsertRow(sheet, id, rowData) {
  var data = sheet.getDataRange().getValues();
  // Find index by ID (Assumes ID is always in first column index 0)
  var rowIndex = -1;

  // Skip header (i=1)
  for (var i = 1; i < data.length; i++) {
    if (data[i][0] == id) {
      rowIndex = i + 1; // 1-based index
      break;
    }
  }

  if (rowIndex > 0) {
    // Update existing
    sheet.getRange(rowIndex, 1, 1, rowData.length).setValues([rowData]);
  } else {
    // Append new
    sheet.appendRow(rowData);
  }
}

function deleteRowById(ss, sheetName, id) {
  var sheet = ss.getSheetByName(sheetName);
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) {
    if (data[i][0] == id) {
      sheet.deleteRow(i + 1);
      return;
    }
  }
}

