import React, { useState, useEffect, useRef } from 'react';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import TaskListView from './components/TaskListView';
import TeamModal from './components/TeamModal';
import AlertModal from './components/AlertModal';
import DashboardView from './components/DashboardView';
import PresencialModal from './components/PresencialModal';
import UserAuthModal from './components/UserAuthModal'; 
import LoginScreen from './components/LoginScreen';

import { User, Task, AlertPeriod, Team, Notification, TaskStatus } from './types';
import { USERS, INITIAL_TASKS, INITIAL_TEAMS } from './constants';
import { api, getApiUrl } from './services/api';
import { Layout, CheckSquare, List, Calendar as CalendarIcon, Settings, PieChart, MapPin, AlertTriangle, Users, Database, Loader2, Filter, KeyRound, Bell, LogOut } from 'lucide-react';
import { format, isValid } from 'date-fns';

const App: React.FC = () => {
  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<User>(USERS[0]); 

  // Data State
  const [isSyncing, setIsSyncing] = useState(false);
  const [isLoadingInitial, setIsLoadingInitial] = useState(true);
  const [connectionStatus, setConnectionStatus] = useState<'DISCONNECTED' | 'CONNECTED' | 'ERROR'>('DISCONNECTED');

  const [tasks, setTasks] = useState<Task[]>([]);
  const [teamUsers, setTeamUsers] = useState<User[]>([]);
  const [teams, setTeams] = useState<Team[]>([]);
  const [alertPeriods, setAlertPeriods] = useState<AlertPeriod[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const [viewMode, setViewMode] = useState<'CALENDAR' | 'LIST' | 'DASHBOARD'>('CALENDAR');
  const [filterScope, setFilterScope] = useState<string>('MY_TEAM'); 
  const [filterStatus, setFilterStatus] = useState<TaskStatus | 'ALL'>('ALL'); 

  // Modals State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [isAlertModalOpen, setIsAlertModalOpen] = useState(false);
  const [isPresencialModalOpen, setIsPresencialModalOpen] = useState(false);
  const [isUserSwitcherOpen, setIsUserSwitcherOpen] = useState(false);
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);

  // Auth Modal State
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authTargetUser, setAuthTargetUser] = useState<User | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'CHANGE_PASSWORD'>('LOGIN');

  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  // Refs
  const userSwitcherRef = useRef<HTMLDivElement>(null);
  const notificationRef = useRef<HTMLDivElement>(null);
  const tasksRef = useRef<Task[]>([]);
  const currentUserRef = useRef<User>(currentUser);
  const isFirstLoadRef = useRef(true);

  // Keep refs synced
  useEffect(() => { tasksRef.current = tasks; }, [tasks]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);

  // --- CLICK OUTSIDE HANDLER ---
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (userSwitcherRef.current && !userSwitcherRef.current.contains(event.target as Node)) {
        setIsUserSwitcherOpen(false);
      }
      if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // --- API & SYNC LOGIC ---
  const fetchData = async (): Promise<boolean> => {
    if (!getApiUrl()) {
        // Fallback demo mode if no URL is hardcoded
        setTasks(INITIAL_TASKS);
        setTeamUsers(USERS);
        setTeams(INITIAL_TEAMS);
        setIsLoadingInitial(false);
        return false;
    }

    try {
      setIsSyncing(true);
      const data = await api.sync();

      // PARSE TASKS
      const parsedTasks: Task[] = data.tasks.map((t: any) => {
        let dateObj;
        if (typeof t.date === 'string' && t.date.includes('-') && !t.date.includes('T')) {
           const [y, m, d] = t.date.split('-').map(Number);
           dateObj = new Date(y, m - 1, d);
        } else if (typeof t.date === 'string') {
           const datePart = t.date.substring(0, 10);
           if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
             const [y, m, d] = datePart.split('-').map(Number);
             dateObj = new Date(y, m - 1, d);
           } else {
             dateObj = new Date(t.date);
           }
        } else {
           dateObj = new Date(t.date);
        }

        const cleanTime = (val: any) => {
          if (!val) return '';
          const strVal = String(val);
          if (strVal.match(/^\d{1,2}:\d{2}$/)) return strVal;
          const d = new Date(strVal);
          if (isValid(d)) return format(d, 'HH:mm');
          return strVal;
        };

        return { 
          ...t, 
          title: t.title || 'Sem título', 
          date: dateObj,
          startTime: cleanTime(t.startTime),
          endTime: cleanTime(t.endTime)
        };
      });

      const parsedAlerts: AlertPeriod[] = data.alerts.map((a: any) => {
         let start, end;
         if (typeof a.startDate === 'string') {
            const datePart = a.startDate.substring(0, 10);
            if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
               const [y, m, d] = datePart.split('-').map(Number);
               start = new Date(y, m - 1, d);
            } else start = new Date(a.startDate);
         } else start = new Date(a.startDate);

         if (typeof a.endDate === 'string') {
             const datePart = a.endDate.substring(0, 10);
             if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
                const [y, m, d] = datePart.split('-').map(Number);
                end = new Date(y, m - 1, d);
             } else end = new Date(a.endDate);
         } else end = new Date(a.endDate);

         return { ...a, startDate: start, endDate: end };
      });

      const parsedUsers: User[] = data.users.map((u: any) => ({
        ...u,
        presencialDates: Array.isArray(u.presencialDates) ? u.presencialDates : [],
        password: (u.password !== undefined && u.password !== null && u.password !== '') ? String(u.password) : undefined
      }));

      const parsedTeams: Team[] = data.teams || [];

      updateNotifications(parsedTasks);
      isFirstLoadRef.current = false;
      setTasks(parsedTasks);

      // Update Users List (merging passwords if needed locally, but usually fresh from API)
      if (parsedUsers.length > 0) {
        setTeamUsers(parsedUsers);
      } else {
        setTeamUsers(USERS); // Fallback
      }

      if (parsedTeams.length > 0) setTeams(parsedTeams);
      else setTeams(INITIAL_TEAMS);

      setAlertPeriods(parsedAlerts);
      setConnectionStatus('CONNECTED');
      setIsLoadingInitial(false);
      return true;
    } catch (error) {
      console.error("Sync Error", error);
      setConnectionStatus('ERROR');
      setIsLoadingInitial(false);
      return false;
    } finally {
      setIsSyncing(false);
    }
  };

  // Initial Fetch on Mount
  useEffect(() => {
    fetchData();
    const intervalId = setInterval(fetchData, 5000);
    return () => clearInterval(intervalId);
  }, []); 

  // --- NOTIFICATION LOGIC ---
  const updateNotifications = (currentTasks: Task[]) => {
      setNotifications(prev => {
         const readIds = JSON.parse(localStorage.getItem('GEST_PRO_READ_NOTIFS') || '[]');
         const currentIds = new Set(prev.map(n => n.id));
         const incomingNotifications: Notification[] = [];
         const myId = currentUserRef.current.id;

         currentTasks.forEach(task => {
             if (task.isNudged) {
                 const notifId = `${task.id}_nudge`;
                 if (task.assigneeId === myId && !readIds.includes(notifId) && !currentIds.has(notifId)) {
                     const title = task.title && task.title.trim() !== '' ? task.title : 'Tarefa sem título';
                     incomingNotifications.push({
                        id: notifId,
                        targetUserId: task.assigneeId,
                        message: `⚠️ URGENTE: A demanda "${title}" foi cobrada!`,
                        date: new Date(),
                        read: false,
                        type: 'NUDGE'
                     });
                     currentIds.add(notifId);
                 }
             }
         });

         if (!isFirstLoadRef.current && tasksRef.current.length > 0) {
            currentTasks.forEach(newTask => {
                const oldTask = tasksRef.current.find(t => t.id === newTask.id);
                if ((!oldTask || oldTask.assigneeId !== newTask.assigneeId) && newTask.assigneeId === myId) {
                    const notifId = `assign_${newTask.id}_${newTask.assigneeId}`;
                     if (!currentIds.has(notifId) && !readIds.includes(notifId)) {
                        const title = newTask.title && newTask.title.trim() !== '' ? newTask.title : 'Tarefa sem título';
                        incomingNotifications.push({ 
                            id: notifId, 
                            targetUserId: newTask.assigneeId,
                            message: `Nova demanda atribuída: ${title}`, 
                            date: new Date(), 
                            read: false, 
                            type: 'TASK_ASSIGNED' 
                        });
                        currentIds.add(notifId);
                     }
                }
            });
         }
         if (incomingNotifications.length === 0) return prev;
         return [...incomingNotifications, ...prev];
      });
  };

  useEffect(() => {
    if (isAuthenticated) setFilterScope('MY_TEAM');
  }, [currentUser.id, isAuthenticated]);

  const handleMarkAsRead = () => {
     const currentRead = JSON.parse(localStorage.getItem('GEST_PRO_READ_NOTIFS') || '[]');
     const newIds = notifications.filter(n => n.targetUserId === currentUser.id).map(n => n.id);
     localStorage.setItem('GEST_PRO_READ_NOTIFS', JSON.stringify([...new Set([...currentRead, ...newIds])]));
     setNotifications(prev => prev.filter(n => n.targetUserId !== currentUser.id));
  };

  // --- LOGIN FLOW HANDLERS ---
  const handleLoginClick = (user: User) => {
    setAuthTargetUser(user);
    setAuthMode('LOGIN');
    setIsAuthModalOpen(true);
  };

  const handleLoginSuccess = async (updatedUser?: User) => {
     if (updatedUser) {
        // First access or password change (user has new password)
        setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
        setCurrentUser(updatedUser);
        if (getApiUrl()) await api.saveUser(updatedUser);
     } else if (authTargetUser) {
        // Standard login (no user change)
        setCurrentUser(authTargetUser);
     }
     setIsAuthenticated(true);
     setAuthTargetUser(null);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setViewMode('CALENDAR');
    setIsUserSwitcherOpen(false);
  };

  // --- AUTH HANDLERS (Inside App) ---
  const handleUserSwitchClick = (user: User) => {
    setAuthTargetUser(user);
    setAuthMode('LOGIN');
    setIsAuthModalOpen(true);
    setIsUserSwitcherOpen(false); 
  };

  const handleChangePasswordClick = () => {
    setAuthTargetUser(currentUser);
    setAuthMode('CHANGE_PASSWORD');
    setIsAuthModalOpen(true);
  };

  const handleAuthModalSuccess = async (updatedUser?: User) => {
    if (updatedUser) {
        setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
        setCurrentUser(updatedUser);
        if (getApiUrl()) await api.saveUser(updatedUser);
        if (authMode === 'CHANGE_PASSWORD') alert("Senha alterada com sucesso!");
    } else if (authTargetUser) {
       // Switching user inside app
       setCurrentUser(authTargetUser);
       setIsAuthenticated(true); // Ensure stays true
    }
  };


  // --- DATA HANDLERS ---
  const handleAddTask = (date: Date) => { setSelectedDate(date); setSelectedTask(null); setIsModalOpen(true); };
  const handleEditTask = (task: Task) => { setSelectedTask(task); setSelectedDate(task.date); setIsModalOpen(true); };

  const handleSaveTask = async (taskToSave: Task) => {
    const safeTask = { ...taskToSave, title: taskToSave.title || 'Sem título' };
    setTasks(prev => {
      const exists = prev.find(t => t.id === safeTask.id);
      return exists ? prev.map(t => t.id === safeTask.id ? safeTask : t) : [...prev, safeTask];
    });
    if (getApiUrl()) { await api.saveTask(safeTask); fetchData(); }
  };

  const handleDeleteTask = async (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
    if (getApiUrl()) { await api.deleteTask(taskId); fetchData(); }
  };

  const handleAddUser = async (newUser: User) => {
    setTeamUsers(prev => [...prev, newUser]);
    if (getApiUrl()) { await api.saveUser(newUser); fetchData(); }
  };

  const handleEditUser = async (updatedUser: User) => {
    setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser.id === updatedUser.id) setCurrentUser(prev => ({...prev, ...updatedUser}));
    if (getApiUrl()) {
      const localUser = teamUsers.find(u => u.id === updatedUser.id);
      const userToSend = { ...updatedUser };
      if (localUser?.password && !userToSend.password) userToSend.password = localUser.password;
      await api.saveUser(userToSend);
      fetchData();
    }
  };

  const handleRemoveUser = async (userId: string) => {
    setTeamUsers(prev => prev.filter(u => u.id !== userId));
    if (getApiUrl()) { await api.deleteUser(userId); fetchData(); }
  };

  const handleAddTeam = async (newTeam: Team) => {
    setTeams(prev => [...prev, newTeam]);
    if (getApiUrl()) { await api.saveTeam(newTeam); fetchData(); }
  };

  const handleRemoveTeam = async (teamId: string) => {
    setTeams(prev => prev.filter(t => t.id !== teamId));
    if (getApiUrl()) { await api.deleteTeam(teamId); fetchData(); }
  };

  const handleSaveAlert = async (newAlert: AlertPeriod) => {
    setAlertPeriods(prev => {
       const exists = prev.find(a => a.id === newAlert.id);
       return exists ? prev.map(a => a.id === newAlert.id ? newAlert : a) : [...prev, newAlert];
    });
    if (getApiUrl()) { await api.saveAlert(newAlert); fetchData(); }
  };

  const handleDeleteAlert = async (alertId: string) => {
     setAlertPeriods(prev => prev.filter(a => a.id !== alertId));
     if (getApiUrl()) { await api.deleteAlert(alertId); fetchData(); }
  };

  const handleBatchUpdatePresence = async (updatedUsers: User[]) => {
     setTeamUsers(prev => prev.map(u => updatedUsers.find(upd => upd.id === u.id) || u));
     if (getApiUrl()) { await api.saveUsersBatch(updatedUsers); fetchData(); }
  };

  const isLeader = currentUser.role === 'LEADER' || currentUser.role === 'COORDINATOR';
  const isCoordinator = currentUser.role === 'COORDINATOR';

  const displayedTasks = tasks.filter(task => {
    const assignee = teamUsers.find(u => u.id === task.assigneeId);
    if (!assignee) return false;
    let passesScope = false;
    if (filterScope === 'ME') passesScope = assignee.id === currentUser.id;
    else if (filterScope === 'MY_TEAM') passesScope = assignee.teamId === currentUser.teamId;
    else if (filterScope === 'ALL_TEAMS') passesScope = true;
    else passesScope = assignee.teamId === filterScope;

    if (!passesScope) return false;
    if (viewMode === 'LIST' && filterStatus !== 'ALL') if (task.status !== filterStatus) return false;
    return true;
  });

  const displayedAlerts = alertPeriods.filter(alert => {
     if (!alert.targetTeamId || alert.targetTeamId === 'ALL') return true;
     return alert.targetTeamId === currentUser.teamId || isCoordinator;
  });

  const myNotifications = notifications.filter(n => n.targetUserId === currentUser.id);
  const safeDate = (d: any) => (d instanceof Date && !isNaN(d.getTime())) ? d : (typeof d === 'string' ? new Date(d) : new Date());

  // --- RENDER ---

  // 1. If not authenticated, show Login Screen (after initial data load)
  if (!isAuthenticated) {
     return (
       <>
         <LoginScreen 
            users={teamUsers} 
            teams={teams}
            onLogin={handleLoginClick} 
            isLoading={isLoadingInitial}
         />
         <UserAuthModal 
            isOpen={isAuthModalOpen}
            onClose={() => setIsAuthModalOpen(false)}
            targetUser={authTargetUser}
            mode={authMode}
            onSuccess={handleLoginSuccess}
         />
       </>
     );
  }

  // 2. Main App
  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">

      {/* Sidebar */}
      <aside className="w-16 lg:w-72 bg-slate-900 text-slate-300 flex flex-col flex-shrink-0 shadow-xl z-20 transition-all">
        <div className="p-4 lg:p-6 border-b border-slate-800 flex items-center justify-center lg:justify-start gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg text-white shrink-0">
             <Layout size={24} />
          </div>
          <div className="hidden lg:flex flex-col">
             <h1 className="text-xl font-bold tracking-tight text-white leading-none mb-1">GestãoPRO</h1>
             <span className="text-[10px] text-slate-400 font-medium whitespace-nowrap">Organizador de Demandas</span>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          <button onClick={() => setViewMode('CALENDAR')} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'CALENDAR' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <CheckSquare size={20} />
            <span className="hidden lg:inline">Minhas Demandas</span>
          </button>

          <button onClick={() => { setViewMode('DASHBOARD'); setFilterStatus('ALL'); }} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'DASHBOARD' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <PieChart size={20} />
            <span className="hidden lg:inline">Indicadores</span>
          </button>

          <button onClick={() => setIsPresencialModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
            <MapPin size={20} />
            <span className="hidden lg:inline">Escala Presencial</span>
          </button>

          {isLeader && (
            <>
              <div className="my-2 border-t border-slate-800"></div>
              <button onClick={() => setIsTeamModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
                <Settings size={20} />
                <span className="hidden lg:inline">Gerenciar Equipe</span>
              </button>
              <button onClick={() => setIsAlertModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-orange-400">
                <AlertTriangle size={20} />
                <span className="hidden lg:inline">Criar Alerta</span>
              </button>
            </>
          )}
        </nav>

        <div className="p-2 bg-slate-950">
           <div className="w-full flex items-center justify-center lg:justify-start gap-3 p-3 rounded-lg hover:bg-slate-800 transition-colors group cursor-default">
              <div className="relative">
                 <Database size={20} className="text-slate-400 group-hover:text-white transition-colors" />
                 <div className={`absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full border-2 border-slate-900 ${
                    connectionStatus === 'CONNECTED' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.6)]' : 
                    connectionStatus === 'ERROR' ? 'bg-red-500' : 'bg-slate-600'
                 }`}></div>
              </div>
              <span className="hidden lg:inline text-sm font-medium text-slate-300 group-hover:text-white">
                {connectionStatus === 'CONNECTED' ? 'Conectado' : 'Desconectado'}
              </span>
              {isSyncing && <Loader2 size={14} className="animate-spin ml-auto text-slate-500" />}
           </div>
        </div>

        <div className="relative border-t border-slate-800 bg-slate-950 p-2" ref={userSwitcherRef}>
           <button 
             onClick={() => setIsUserSwitcherOpen(!isUserSwitcherOpen)}
             className="w-full flex items-center justify-center lg:justify-start gap-3 p-2 rounded hover:bg-slate-800 transition-colors"
           >
              <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center overflow-hidden">
                 <Users size={16} className="text-slate-300" />
              </div>
              <div className="hidden lg:block text-left">
                 <div className="text-xs font-bold text-slate-400">Alternar Usuário</div>
              </div>
           </button>

           {isUserSwitcherOpen && (
              <div className="absolute bottom-full left-2 w-56 bg-slate-800 border border-slate-700 rounded-lg shadow-xl mb-2 p-1 z-50 max-h-60 overflow-y-auto">
                 {teamUsers.map(u => (
                   <button
                     key={u.id}
                     onClick={() => handleUserSwitchClick(u)}
                     className={`w-full flex items-center gap-2 p-2 rounded text-sm ${currentUser.id === u.id ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-700'}`}
                   >
                     <img src={u.avatar} className="w-6 h-6 rounded-full" alt=""/>
                     <span className="truncate">{u.name}</span>
                     {!u.password && <span className="ml-auto w-2 h-2 rounded-full bg-red-500" title="Sem senha"></span>}
                   </button>
                 ))}
                 <div className="border-t border-slate-700 mt-1 pt-1">
                    <button onClick={handleLogout} className="w-full flex items-center gap-2 p-2 text-red-400 hover:bg-slate-700 rounded text-sm">
                        <LogOut size={14} /> Sair do Sistema
                    </button>
                 </div>
              </div>
           )}
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shadow-sm z-10 gap-4">

          <div className="flex items-center gap-4">
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button
                onClick={() => setViewMode('CALENDAR')}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${
                  viewMode === 'CALENDAR' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                <CalendarIcon size={16} />
                <span className="hidden sm:inline">Calendário</span>
              </button>
              <button
                onClick={() => { setViewMode('LIST'); setFilterStatus('ALL'); }}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${
                  viewMode === 'LIST' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                <List size={16} />
                <span className="hidden sm:inline">Lista</span>
              </button>
            </div>

            <div className="h-6 w-px bg-slate-200 mx-2 hidden sm:block"></div>

            {(viewMode === 'CALENDAR' || viewMode === 'LIST' || viewMode === 'DASHBOARD') && (
               <div className="flex items-center gap-2">
                 <Filter size={16} className="text-slate-400" />
                 <select 
                   value={filterScope}
                   onChange={(e) => setFilterScope(e.target.value)}
                   className="bg-slate-50 border-none text-sm font-medium text-slate-700 rounded-md focus:ring-0 cursor-pointer hover:bg-slate-100 py-1.5 pl-2 pr-8"
                 >
                    <option value="ME">Apenas Minhas</option>
                    <option value="MY_TEAM">Minha Equipe</option>
                    {isCoordinator && (
                      <>
                        <option disabled>──────────</option>
                        <option value="ALL_TEAMS">Todas as Equipes</option>
                        {teams.map(team => (
                          <option key={team.id} value={team.id}>Equipe: {team.name}</option>
                        ))}
                      </>
                    )}
                 </select>
               </div>
            )}
          </div>

          <div className="flex items-center gap-6">
            <div className="relative" ref={notificationRef}>
              <button 
                onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
                className="text-slate-400 hover:text-indigo-600 transition-colors relative"
              >
                 <Bell size={20} />
                 {myNotifications.length > 0 && (
                   <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-bounce"></span>
                 )}
              </button>

              {isNotificationsOpen && (
                 <div className="absolute right-0 top-full mt-2 w-72 bg-white border border-slate-200 rounded-xl shadow-xl z-50 overflow-hidden">
                    <div className="bg-slate-50 px-4 py-2 border-b border-slate-100 text-xs font-bold text-slate-500">
                        Notificações ({myNotifications.length})
                    </div>
                    <div className="max-h-64 overflow-y-auto custom-scrollbar">
                       {myNotifications.length === 0 ? (
                         <div className="p-4 text-center text-xs text-slate-400">Nenhuma notificação nova.</div>
                       ) : (
                        myNotifications.map(n => (
                           <div key={n.id} className="p-3 border-b border-slate-50 hover:bg-slate-50 transition-colors">
                              <p className={`text-sm mb-1 ${n.type === 'NUDGE' ? 'text-amber-700 font-bold' : 'text-slate-800'}`}>
                                 {n.message || 'Nova Notificação'}
                              </p>
                              <span className="text-[10px] text-slate-400 font-medium">
                                 {format(safeDate(n.date), 'dd/MM HH:mm')}
                              </span>
                           </div>
                         ))
                       )}
                    </div>
                    {myNotifications.length > 0 && (
                        <div className="bg-slate-50 p-2 text-center border-t border-slate-100">
                            <button onClick={handleMarkAsRead} className="text-xs text-indigo-600 font-medium hover:underline">
                                Marcar como lidas
                            </button>
                        </div>
                    )}
                 </div>
              )}
            </div>

            <button onClick={handleChangePasswordClick} className="text-slate-400 hover:text-indigo-600 transition-colors" title="Alterar Senha">
               <KeyRound size={18} />
            </button>

            <div className="flex items-center gap-3 pl-6 border-l border-slate-200">
              <div className="text-right hidden sm:block">
                <div className="text-sm font-bold text-slate-800">{currentUser.name}</div>
                <div className="text-xs text-slate-500">
                   {currentUser.role === 'COORDINATOR' ? 'Coordenador' : currentUser.role === 'LEADER' ? 'Líder' : 'Membro'}
                </div>
              </div>
              <img src={currentUser.avatar} alt="User" className="w-9 h-9 rounded-full border border-slate-200 shadow-sm" />
            </div>
          </div>
        </header>

        <div className="flex-1 p-4 lg:p-6 overflow-hidden flex flex-col bg-slate-50">
          <div className="flex-1 h-full min-h-0">
            {viewMode === 'CALENDAR' ? (
              <Calendar 
                tasks={displayedTasks} 
                users={teamUsers}
                alertPeriods={displayedAlerts}
                currentUser={currentUser}
                onAddTask={handleAddTask}
                onEditTask={handleEditTask}
              />
            ) : viewMode === 'LIST' ? (
              <TaskListView 
                tasks={displayedTasks}
                currentUser={currentUser}
                onEditTask={handleEditTask}
              />
            ) : (
              <DashboardView 
                tasks={displayedTasks} 
                users={teamUsers}
                onFilterRequest={(status) => {
                   setFilterStatus(status);
                   setViewMode('LIST');
                }}
              />
            )}
          </div>
        </div>
      </main>

      {/* Auth Modal (Password Change / Login inside app) */}
      <UserAuthModal 
        isOpen={isAuthModalOpen}
        onClose={() => setIsAuthModalOpen(false)}
        targetUser={authTargetUser}
        mode={authMode}
        onSuccess={handleAuthModalSuccess}
      />

      {/* Other Modals */}
      <TaskModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        onRequestTransfer={() => {}} 
        initialTask={selectedTask}
        selectedDate={selectedDate}
        currentUser={currentUser}
        users={teamUsers}
        teams={teams}
      />

      <TeamModal 
        isOpen={isTeamModalOpen}
        onClose={() => setIsTeamModalOpen(false)}
        users={teamUsers}
        teams={teams}
        onAddUser={handleAddUser}
        onEditUser={handleEditUser}
        onRemoveUser={handleRemoveUser}
        onAddTeam={handleAddTeam}
        onRemoveTeam={handleRemoveTeam}
      />

      <AlertModal 
        isOpen={isAlertModalOpen}
        onClose={() => setIsAlertModalOpen(false)}
        onSave={handleSaveAlert}
        onDelete={handleDeleteAlert}
        alertPeriods={alertPeriods}
        teams={teams}
      />

      <PresencialModal 
        isOpen={isPresencialModalOpen}
        onClose={() => setIsPresencialModalOpen(false)}
        users={teamUsers}
        teams={teams}
        currentUser={currentUser}
        onSavePresence={handleBatchUpdatePresence}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import TaskListView from './components/TaskListView';
import TeamModal from './components/TeamModal';
import AlertModal from './components/AlertModal';
import DashboardView from './components/DashboardView';
import PresencialModal from './components/PresencialModal';
import UserAuthModal from './components/UserAuthModal'; 
import LoginScreen from './components/LoginScreen';

import { User, Task, AlertPeriod, Team, Notification, TaskStatus } from './types';
import { USERS, INITIAL_TASKS, INITIAL_TEAMS } from './constants';
import { api, getApiUrl } from './services/api';
import { Layout, CheckSquare, List, Calendar as CalendarIcon, Settings, PieChart, MapPin, AlertTriangle, Users, Database, Loader2, Filter, KeyRound, Bell, LogOut } from 'lucide-react';
import { format, isValid } from 'date-fns';

const App: React.FC = () => {
  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<User>(USERS[0]); 

  // Data State
  const [isSyncing, setIsSyncing] = useState(false);
  const [isLoadingInitial, setIsLoadingInitial] = useState(true);
  const [connectionStatus, setConnectionStatus] = useState<'DISCONNECTED' | 'CONNECTED' | 'ERROR'>('DISCONNECTED');

  const [tasks, setTasks] = useState<Task[]>([]);
  const [teamUsers, setTeamUsers] = useState<User[]>([]);
  const [teams, setTeams] = useState<Team[]>([]);
  const [alertPeriods, setAlertPeriods] = useState<AlertPeriod[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const [viewMode, setViewMode] = useState<'CALENDAR' | 'LIST' | 'DASHBOARD'>('CALENDAR');
  const [filterScope, setFilterScope] = useState<string>('MY_TEAM'); 
  const [filterStatus, setFilterStatus] = useState<TaskStatus | 'ALL'>('ALL'); 

  // Modals State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [isAlertModalOpen, setIsAlertModalOpen] = useState(false);
  const [isPresencialModalOpen, setIsPresencialModalOpen] = useState(false);
  const [isUserSwitcherOpen, setIsUserSwitcherOpen] = useState(false);
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);

  // Auth Modal State
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authTargetUser, setAuthTargetUser] = useState<User | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'CHANGE_PASSWORD'>('LOGIN');

  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  // Refs
  const userSwitcherRef = useRef<HTMLDivElement>(null);
  const notificationRef = useRef<HTMLDivElement>(null);
  const tasksRef = useRef<Task[]>([]);
  const currentUserRef = useRef<User>(currentUser);
  const isFirstLoadRef = useRef(true);

  // Keep refs synced
  useEffect(() => { tasksRef.current = tasks; }, [tasks]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);

  // --- CLICK OUTSIDE HANDLER ---
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (userSwitcherRef.current && !userSwitcherRef.current.contains(event.target as Node)) {
        setIsUserSwitcherOpen(false);
      }
      if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // --- API & SYNC LOGIC ---
  const fetchData = async (): Promise<boolean> => {
    if (!getApiUrl()) {
        // Fallback demo mode if no URL is hardcoded
        setTasks(INITIAL_TASKS);
        setTeamUsers(USERS);
        setTeams(INITIAL_TEAMS);
        setIsLoadingInitial(false);
        return false;
    }

    try {
      setIsSyncing(true);
      const data = await api.sync();

      // PARSE TASKS
      const parsedTasks: Task[] = data.tasks.map((t: any) => {
        let dateObj;
        if (typeof t.date === 'string' && t.date.includes('-') && !t.date.includes('T')) {
           const [y, m, d] = t.date.split('-').map(Number);
           dateObj = new Date(y, m - 1, d);
        } else if (typeof t.date === 'string') {
           const datePart = t.date.substring(0, 10);
           if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
             const [y, m, d] = datePart.split('-').map(Number);
             dateObj = new Date(y, m - 1, d);
           } else {
             dateObj = new Date(t.date);
           }
        } else {
           dateObj = new Date(t.date);
        }

        const cleanTime = (val: any) => {
          if (!val) return '';
          const strVal = String(val);
          if (strVal.match(/^\d{1,2}:\d{2}$/)) return strVal;
          const d = new Date(strVal);
          if (isValid(d)) return format(d, 'HH:mm');
          return strVal;
        };

        return { 
          ...t, 
          title: t.title || 'Sem título', 
          date: dateObj,
          startTime: cleanTime(t.startTime),
          endTime: cleanTime(t.endTime)
        };
      });

      const parsedAlerts: AlertPeriod[] = data.alerts.map((a: any) => {
         let start, end;
         if (typeof a.startDate === 'string') {
            const datePart = a.startDate.substring(0, 10);
            if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
               const [y, m, d] = datePart.split('-').map(Number);
               start = new Date(y, m - 1, d);
            } else start = new Date(a.startDate);
         } else start = new Date(a.startDate);

         if (typeof a.endDate === 'string') {
             const datePart = a.endDate.substring(0, 10);
             if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
                const [y, m, d] = datePart.split('-').map(Number);
                end = new Date(y, m - 1, d);
             } else end = new Date(a.endDate);
         } else end = new Date(a.endDate);

         return { ...a, startDate: start, endDate: end };
      });

      const parsedUsers: User[] = data.users.map((u: any) => ({
        ...u,
        presencialDates: Array.isArray(u.presencialDates) ? u.presencialDates : [],
        password: (u.password !== undefined && u.password !== null && u.password !== '') ? String(u.password) : undefined
      }));

      const parsedTeams: Team[] = data.teams || [];

      updateNotifications(parsedTasks);
      isFirstLoadRef.current = false;
      setTasks(parsedTasks);

      // Update Users List (merging passwords if needed locally, but usually fresh from API)
      if (parsedUsers.length > 0) {
        setTeamUsers(parsedUsers);
      } else {
        setTeamUsers(USERS); // Fallback
      }

      if (parsedTeams.length > 0) setTeams(parsedTeams);
      else setTeams(INITIAL_TEAMS);

      setAlertPeriods(parsedAlerts);
      setConnectionStatus('CONNECTED');
      setIsLoadingInitial(false);
      return true;
    } catch (error) {
      console.error("Sync Error", error);
      setConnectionStatus('ERROR');
      setIsLoadingInitial(false);
      return false;
    } finally {
      setIsSyncing(false);
    }
  };

  // Initial Fetch on Mount
  useEffect(() => {
    fetchData();
    // AUMENTADO PARA 30 SEGUNDOS CONFORME SOLICITADO
    const intervalId = setInterval(fetchData, 30000); 
    return () => clearInterval(intervalId);
  }, []); 

  // --- NOTIFICATION LOGIC ---
  const updateNotifications = (currentTasks: Task[]) => {
      setNotifications(prev => {
         const readIds = JSON.parse(localStorage.getItem('GEST_PRO_READ_NOTIFS') || '[]');
         const currentIds = new Set(prev.map(n => n.id));
         const incomingNotifications: Notification[] = [];
         const myId = currentUserRef.current.id;

         currentTasks.forEach(task => {
             if (task.isNudged) {
                 const notifId = `${task.id}_nudge`;
                 if (task.assigneeId === myId && !readIds.includes(notifId) && !currentIds.has(notifId)) {
                     const title = task.title && task.title.trim() !== '' ? task.title : 'Tarefa sem título';
                     incomingNotifications.push({
                        id: notifId,
                        targetUserId: task.assigneeId,
                        message: `⚠️ URGENTE: A demanda "${title}" foi cobrada!`,
                        date: new Date(),
                        read: false,
                        type: 'NUDGE'
                     });
                     currentIds.add(notifId);
                 }
             }
         });

         if (!isFirstLoadRef.current && tasksRef.current.length > 0) {
            currentTasks.forEach(newTask => {
                const oldTask = tasksRef.current.find(t => t.id === newTask.id);
                if ((!oldTask || oldTask.assigneeId !== newTask.assigneeId) && newTask.assigneeId === myId) {
                    const notifId = `assign_${newTask.id}_${newTask.assigneeId}`;
                     if (!currentIds.has(notifId) && !readIds.includes(notifId)) {
                        const title = newTask.title && newTask.title.trim() !== '' ? newTask.title : 'Tarefa sem título';
                        incomingNotifications.push({ 
                            id: notifId, 
                            targetUserId: newTask.assigneeId,
                            message: `Nova demanda atribuída: ${title}`, 
                            date: new Date(), 
                            read: false, 
                            type: 'TASK_ASSIGNED' 
                        });
                        currentIds.add(notifId);
                     }
                }
            });
         }
         if (incomingNotifications.length === 0) return prev;
         return [...incomingNotifications, ...prev];
      });
  };

  useEffect(() => {
    if (isAuthenticated) setFilterScope('MY_TEAM');
  }, [currentUser.id, isAuthenticated]);

  const handleMarkAsRead = () => {
     const currentRead = JSON.parse(localStorage.getItem('GEST_PRO_READ_NOTIFS') || '[]');
     const newIds = notifications.filter(n => n.targetUserId === currentUser.id).map(n => n.id);
     localStorage.setItem('GEST_PRO_READ_NOTIFS', JSON.stringify([...new Set([...currentRead, ...newIds])]));
     setNotifications(prev => prev.filter(n => n.targetUserId !== currentUser.id));
  };

  // --- LOGIN FLOW HANDLERS ---
  const handleLoginClick = (user: User) => {
    setAuthTargetUser(user);
    setAuthMode('LOGIN');
    setIsAuthModalOpen(true);
  };

  const handleLoginSuccess = async (updatedUser?: User) => {
     if (updatedUser) {
        setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
        setCurrentUser(updatedUser);
        if (getApiUrl()) await api.saveUser(updatedUser);
     } else if (authTargetUser) {
        setCurrentUser(authTargetUser);
     }
     setIsAuthenticated(true);
     setAuthTargetUser(null);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setViewMode('CALENDAR');
    setIsUserSwitcherOpen(false);
  };

  // --- AUTH HANDLERS (Inside App) ---
  const handleUserSwitchClick = (user: User) => {
    setAuthTargetUser(user);
    setAuthMode('LOGIN');
    setIsAuthModalOpen(true);
    setIsUserSwitcherOpen(false); 
  };

  const handleChangePasswordClick = () => {
    setAuthTargetUser(currentUser);
    setAuthMode('CHANGE_PASSWORD');
    setIsAuthModalOpen(true);
  };

  const handleAuthModalSuccess = async (updatedUser?: User) => {
    if (updatedUser) {
        setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
        setCurrentUser(updatedUser);
        if (getApiUrl()) await api.saveUser(updatedUser);
        if (authMode === 'CHANGE_PASSWORD') alert("Senha alterada com sucesso!");
    } else if (authTargetUser) {
       setCurrentUser(authTargetUser);
       setIsAuthenticated(true); 
    }
  };


  // --- DATA HANDLERS ---
  const handleAddTask = (date: Date) => { setSelectedDate(date); setSelectedTask(null); setIsModalOpen(true); };
  const handleEditTask = (task: Task) => { setSelectedTask(task); setSelectedDate(task.date); setIsModalOpen(true); };

  const handleSaveTask = async (taskToSave: Task) => {
    const safeTask = { ...taskToSave, title: taskToSave.title || 'Sem título' };
    setTasks(prev => {
      const exists = prev.find(t => t.id === safeTask.id);
      return exists ? prev.map(t => t.id === safeTask.id ? safeTask : t) : [...prev, safeTask];
    });
    if (getApiUrl()) { await api.saveTask(safeTask); fetchData(); }
  };

  const handleDeleteTask = async (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
    if (getApiUrl()) { await api.deleteTask(taskId); fetchData(); }
  };

  const handleAddUser = async (newUser: User) => {
    setTeamUsers(prev => [...prev, newUser]);
    if (getApiUrl()) { await api.saveUser(newUser); fetchData(); }
  };

  const handleEditUser = async (updatedUser: User) => {
    setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser.id === updatedUser.id) setCurrentUser(prev => ({...prev, ...updatedUser}));
    if (getApiUrl()) {
      const localUser = teamUsers.find(u => u.id === updatedUser.id);
      const userToSend = { ...updatedUser };
      if (localUser?.password && !userToSend.password) userToSend.password = localUser.password;
      await api.saveUser(userToSend);
      fetchData();
    }
  };

  const handleRemoveUser = async (userId: string) => {
    setTeamUsers(prev => prev.filter(u => u.id !== userId));
    if (getApiUrl()) { await api.deleteUser(userId); fetchData(); }
  };

  const handleAddTeam = async (newTeam: Team) => {
    setTeams(prev => [...prev, newTeam]);
    if (getApiUrl()) { await api.saveTeam(newTeam); fetchData(); }
  };

  const handleRemoveTeam = async (teamId: string) => {
    setTeams(prev => prev.filter(t => t.id !== teamId));
    if (getApiUrl()) { await api.deleteTeam(teamId); fetchData(); }
  };

  const handleSaveAlert = async (newAlert: AlertPeriod) => {
    setAlertPeriods(prev => {
       const exists = prev.find(a => a.id === newAlert.id);
       return exists ? prev.map(a => a.id === newAlert.id ? newAlert : a) : [...prev, newAlert];
    });
    if (getApiUrl()) { await api.saveAlert(newAlert); fetchData(); }
  };

  const handleDeleteAlert = async (alertId: string) => {
     setAlertPeriods(prev => prev.filter(a => a.id !== alertId));
     if (getApiUrl()) { await api.deleteAlert(alertId); fetchData(); }
  };

  const handleBatchUpdatePresence = async (updatedUsers: User[]) => {
     setTeamUsers(prev => prev.map(u => updatedUsers.find(upd => upd.id === u.id) || u));
     if (getApiUrl()) { await api.saveUsersBatch(updatedUsers); fetchData(); }
  };

  const isLeader = currentUser.role === 'LEADER' || currentUser.role === 'COORDINATOR';
  const isCoordinator = currentUser.role === 'COORDINATOR';

  const displayedTasks = tasks.filter(task => {
    // Check if task is assigned to a User OR a Team
    const assigneeUser = teamUsers.find(u => u.id === task.assigneeId);
    const assigneeTeam = teams.find(t => t.id === task.assigneeId);

    // If assignee doesn't exist (deleted user/team), maybe hide? or show as orphan. 
    // For now we act robustly.

    let passesScope = false;

    // Scope Logic
    if (filterScope === 'ME') {
        // Show if assigned to ME directly OR assigned to MY TEAM (Group Task)
        passesScope = task.assigneeId === currentUser.id || task.assigneeId === currentUser.teamId;
    }
    else if (filterScope === 'MY_TEAM') {
        // Show if assigned user belongs to my team OR assigned directly to my team
        if (assigneeUser) passesScope = assigneeUser.teamId === currentUser.teamId;
        else if (assigneeTeam) passesScope = assigneeTeam.id === currentUser.teamId;
        else passesScope = false; // Orphaned task
    }
    else if (filterScope === 'ALL_TEAMS') {
        passesScope = true;
    }
    else {
        // Specific Team ID selected
        if (assigneeUser) passesScope = assigneeUser.teamId === filterScope;
        else if (assigneeTeam) passesScope = assigneeTeam.id === filterScope;
    }

    if (!passesScope) return false;
    if (viewMode === 'LIST' && filterStatus !== 'ALL') if (task.status !== filterStatus) return false;
    return true;
  });

  const displayedAlerts = alertPeriods.filter(alert => {
     if (!alert.targetTeamId || alert.targetTeamId === 'ALL') return true;
     return alert.targetTeamId === currentUser.teamId || isCoordinator;
  });

  const myNotifications = notifications.filter(n => n.targetUserId === currentUser.id);
  const safeDate = (d: any) => (d instanceof Date && !isNaN(d.getTime())) ? d : (typeof d === 'string' ? new Date(d) : new Date());

  // --- RENDER ---

  if (!isAuthenticated) {
     return (
       <>
         <LoginScreen 
            users={teamUsers} 
            teams={teams}
            onLogin={handleLoginClick} 
            isLoading={isLoadingInitial}
         />
         <UserAuthModal 
            isOpen={isAuthModalOpen}
            onClose={() => setIsAuthModalOpen(false)}
            targetUser={authTargetUser}
            mode={authMode}
            onSuccess={handleLoginSuccess}
         />
       </>
     );
  }

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">

      {/* Sidebar */}
      <aside className="w-16 lg:w-72 bg-slate-900 text-slate-300 flex flex-col flex-shrink-0 shadow-xl z-20 transition-all">
        <div className="p-4 lg:p-6 border-b border-slate-800 flex items-center justify-center lg:justify-start gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg text-white shrink-0">
             <Layout size={24} />
          </div>
          <div className="hidden lg:flex flex-col">
             <h1 className="text-xl font-bold tracking-tight text-white leading-none mb-1">GestãoPRO</h1>
             <span className="text-[10px] text-slate-400 font-medium whitespace-nowrap">Organizador de Demandas</span>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          <button onClick={() => setViewMode('CALENDAR')} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'CALENDAR' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <CheckSquare size={20} />
            <span className="hidden lg:inline">Minhas Demandas</span>
          </button>

          <button onClick={() => { setViewMode('DASHBOARD'); setFilterStatus('ALL'); }} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'DASHBOARD' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <PieChart size={20} />
            <span className="hidden lg:inline">Indicadores</span>
          </button>

          <button onClick={() => setIsPresencialModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
            <MapPin size={20} />
            <span className="hidden lg:inline">Escala Presencial</span>
          </button>

          {isLeader && (
            <>
              <div className="my-2 border-t border-slate-800"></div>
              <button onClick={() => setIsTeamModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
                <Settings size={20} />
                <span className="hidden lg:inline">Gerenciar Equipe</span>
              </button>
              <button onClick={() => setIsAlertModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-orange-400">
                <AlertTriangle size={20} />
                <span className="hidden lg:inline">Criar Alerta</span>
              </button>
            </>
          )}
        </nav>

        <div className="p-2 bg-slate-950">
           <div className="w-full flex items-center justify-center lg:justify-start gap-3 p-3 rounded-lg hover:bg-slate-800 transition-colors group cursor-default">
              <div className="relative">
                 <Database size={20} className="text-slate-400 group-hover:text-white transition-colors" />
                 <div className={`absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full border-2 border-slate-900 ${
                    connectionStatus === 'CONNECTED' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.6)]' : 
                    connectionStatus === 'ERROR' ? 'bg-red-500' : 'bg-slate-600'
                 }`}></div>
              </div>
              <span className="hidden lg:inline text-sm font-medium text-slate-300 group-hover:text-white">
                {connectionStatus === 'CONNECTED' ? 'Conectado' : 'Desconectado'}
              </span>
              {isSyncing && <Loader2 size={14} className="animate-spin ml-auto text-slate-500" />}
           </div>
        </div>

        <div className="relative border-t border-slate-800 bg-slate-950 p-2" ref={userSwitcherRef}>
           <button 
             onClick={() => setIsUserSwitcherOpen(!isUserSwitcherOpen)}
             className="w-full flex items-center justify-center lg:justify-start gap-3 p-2 rounded hover:bg-slate-800 transition-colors"
           >
              <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center overflow-hidden">
                 <Users size={16} className="text-slate-300" />
              </div>
              <div className="hidden lg:block text-left">
                 <div className="text-xs font-bold text-slate-400">Alternar Usuário</div>
              </div>
           </button>

           {isUserSwitcherOpen && (
              <div className="absolute bottom-full left-2 w-56 bg-slate-800 border border-slate-700 rounded-lg shadow-xl mb-2 p-1 z-50 max-h-60 overflow-y-auto">
                 {teamUsers.map(u => (
                   <button
                     key={u.id}
                     onClick={() => handleUserSwitchClick(u)}
                     className={`w-full flex items-center gap-2 p-2 rounded text-sm ${currentUser.id === u.id ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-700'}`}
                   >
                     <img src={u.avatar} className="w-6 h-6 rounded-full" alt=""/>
                     <span className="truncate">{u.name}</span>
                     {!u.password && <span className="ml-auto w-2 h-2 rounded-full bg-red-500" title="Sem senha"></span>}
                   </button>
                 ))}
                 <div className="border-t border-slate-700 mt-1 pt-1">
                    <button onClick={handleLogout} className="w-full flex items-center gap-2 p-2 text-red-400 hover:bg-slate-700 rounded text-sm">
                        <LogOut size={14} /> Sair do Sistema
                    </button>
                 </div>
              </div>
           )}
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shadow-sm z-10 gap-4">

          <div className="flex items-center gap-4">
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button
                onClick={() => setViewMode('CALENDAR')}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${
                  viewMode === 'CALENDAR' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                <CalendarIcon size={16} />
                <span className="hidden sm:inline">Calendário</span>
              </button>
              <button
                onClick={() => { setViewMode('LIST'); setFilterStatus('ALL'); }}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${
                  viewMode === 'LIST' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                <List size={16} />
                <span className="hidden sm:inline">Lista</span>
              </button>
            </div>

            <div className="h-6 w-px bg-slate-200 mx-2 hidden sm:block"></div>

            {(viewMode === 'CALENDAR' || viewMode === 'LIST' || viewMode === 'DASHBOARD') && (
               <div className="flex items-center gap-2">
                 <Filter size={16} className="text-slate-400" />
                 <select 
                   value={filterScope}
                   onChange={(e) => setFilterScope(e.target.value)}
                   className="bg-slate-50 border-none text-sm font-medium text-slate-700 rounded-md focus:ring-0 cursor-pointer hover:bg-slate-100 py-1.5 pl-2 pr-8"
                 >
                    <option value="ME">Apenas Minhas</option>
                    <option value="MY_TEAM">Minha Equipe</option>
                    {isCoordinator && (
                      <>
                        <option disabled>──────────</option>
                        <option value="ALL_TEAMS">Todas as Equipes</option>
                        {teams.map(team => (
                          <option key={team.id} value={team.id}>Equipe: {team.name}</option>
                        ))}
                      </>
                    )}
                 </select>
               </div>
            )}
          </div>

          <div className="flex items-center gap-6">
            <div className="relative" ref={notificationRef}>
              <button 
                onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
                className="text-slate-400 hover:text-indigo-600 transition-colors relative"
              >
                 <Bell size={20} />
                 {myNotifications.length > 0 && (
                   <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-bounce"></span>
                 )}
              </button>

              {isNotificationsOpen && (
                 <div className="absolute right-0 top-full mt-2 w-72 bg-white border border-slate-200 rounded-xl shadow-xl z-50 overflow-hidden">
                    <div className="bg-slate-50 px-4 py-2 border-b border-slate-100 text-xs font-bold text-slate-500">
                        Notificações ({myNotifications.length})
                    </div>
                    <div className="max-h-64 overflow-y-auto custom-scrollbar">
                       {myNotifications.length === 0 ? (
                         <div className="p-4 text-center text-xs text-slate-400">Nenhuma notificação nova.</div>
                       ) : (
                        myNotifications.map(n => (
                           <div key={n.id} className="p-3 border-b border-slate-50 hover:bg-slate-50 transition-colors">
                              <p className={`text-sm mb-1 ${n.type === 'NUDGE' ? 'text-amber-700 font-bold' : 'text-slate-800'}`}>
                                 {n.message || 'Nova Notificação'}
                              </p>
                              <span className="text-[10px] text-slate-400 font-medium">
                                 {format(safeDate(n.date), 'dd/MM HH:mm')}
                              </span>
                           </div>
                         ))
                       )}
                    </div>
                    {myNotifications.length > 0 && (
                        <div className="bg-slate-50 p-2 text-center border-t border-slate-100">
                            <button onClick={handleMarkAsRead} className="text-xs text-indigo-600 font-medium hover:underline">
                                Marcar como lidas
                            </button>
                        </div>
                    )}
                 </div>
              )}
            </div>

            <button onClick={handleChangePasswordClick} className="text-slate-400 hover:text-indigo-600 transition-colors" title="Alterar Senha">
               <KeyRound size={18} />
            </button>

            <div className="flex items-center gap-3 pl-6 border-l border-slate-200">
              <div className="text-right hidden sm:block">
                <div className="text-sm font-bold text-slate-800">{currentUser.name}</div>
                <div className="text-xs text-slate-500">
                   {currentUser.role === 'COORDINATOR' ? 'Coordenador' : currentUser.role === 'LEADER' ? 'Líder' : 'Membro'}
                </div>
              </div>
              <img src={currentUser.avatar} alt="User" className="w-9 h-9 rounded-full border border-slate-200 shadow-sm" />
            </div>
          </div>
        </header>

        <div className="flex-1 p-4 lg:p-6 overflow-hidden flex flex-col bg-slate-50">
          <div className="flex-1 h-full min-h-0">
            {viewMode === 'CALENDAR' ? (
              <Calendar 
                tasks={displayedTasks} 
                users={teamUsers}
                teams={teams}
                alertPeriods={displayedAlerts}
                currentUser={currentUser}
                onAddTask={handleAddTask}
                onEditTask={handleEditTask}
              />
            ) : viewMode === 'LIST' ? (
              <TaskListView 
                tasks={displayedTasks}
                currentUser={currentUser}
                users={teamUsers}
                teams={teams}
                onEditTask={handleEditTask}
              />
            ) : (
              <DashboardView 
                tasks={displayedTasks} 
                users={teamUsers}
                onFilterRequest={(status) => {
                   setFilterStatus(status);
                   setViewMode('LIST');
                }}
              />
            )}
          </div>
        </div>
      </main>

      {/* Auth Modal (Password Change / Login inside app) */}
      <UserAuthModal 
        isOpen={isAuthModalOpen}
        onClose={() => setIsAuthModalOpen(false)}
        targetUser={authTargetUser}
        mode={authMode}
        onSuccess={handleAuthModalSuccess}
      />

      {/* Other Modals */}
      <TaskModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        onRequestTransfer={() => {}} 
        initialTask={selectedTask}
        selectedDate={selectedDate}
        currentUser={currentUser}
        users={teamUsers}
        teams={teams}
      />

      <TeamModal 
        isOpen={isTeamModalOpen}
        onClose={() => setIsTeamModalOpen(false)}
        users={teamUsers}
        teams={teams}
        onAddUser={handleAddUser}
        onEditUser={handleEditUser}
        onRemoveUser={handleRemoveUser}
        onAddTeam={handleAddTeam}
        onRemoveTeam={handleRemoveTeam}
      />

      <AlertModal 
        isOpen={isAlertModalOpen}
        onClose={() => setIsAlertModalOpen(false)}
        onSave={handleSaveAlert}
        onDelete={handleDeleteAlert}
        alertPeriods={alertPeriods}
        teams={teams}
      />

      <PresencialModal 
        isOpen={isPresencialModalOpen}
        onClose={() => setIsPresencialModalOpen(false)}
        users={teamUsers}
        teams={teams}
        currentUser={currentUser}
        onSavePresence={handleBatchUpdatePresence}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { X, Calendar as CalendarIcon, User as UserIcon, Flag, CheckCircle2, Clock, AlertCircle, Megaphone, Users } from 'lucide-react';
import { Task, User, Team, TaskStatus, Priority, normalizeDate } from '../types';
import { STATUS_LABELS } from '../constants';
import { format } from 'date-fns';

interface TaskModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Task) => void;
  onDelete?: (taskId: string) => void;
  onRequestTransfer?: (taskId: string, newAssigneeId: string) => void; // Kept for interface compatibility but unused
  initialTask?: Task | null;
  selectedDate?: Date;
  currentUser: User;
  users: User[]; // Dynamic users list
  teams: Team[]; // Dynamic teams list
}

const TaskModal: React.FC<TaskModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  onDelete, 
  initialTask, 
  selectedDate, 
  currentUser,
  users,
  teams
}) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [assigneeId, setAssigneeId] = useState(currentUser.id);
  const [targetTeamId, setTargetTeamId] = useState<string>(''); // For filtering task per team
  const [priority, setPriority] = useState<Priority>('MEDIUM');
  const [status, setStatus] = useState<TaskStatus>('TODO');
  const [dateStr, setDateStr] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [isNudged, setIsNudged] = useState(false);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [pendingNudge, setPendingNudge] = useState(false);

  // Reset or populate form when modal opens
  useEffect(() => {
    if (isOpen) {
      setHasUnsavedChanges(false);
      setPendingNudge(false);
      if (initialTask) {
        setTitle(initialTask.title);
        setDescription(initialTask.description);
        setAssigneeId(initialTask.assigneeId);
        setPriority(initialTask.priority);
        setStatus(initialTask.status);
        setDateStr(format(initialTask.date, 'yyyy-MM-dd'));
        setStartTime(initialTask.startTime || '');
        setEndTime(initialTask.endTime || '');
        setTargetTeamId(initialTask.targetTeamId || '');
        setIsNudged(initialTask.isNudged || false);

        // Auto-set team based on assignee if missing
        if (!initialTask.targetTeamId) {
            const assignee = users.find(u => u.id === initialTask.assigneeId);
            if (assignee) setTargetTeamId(assignee.teamId);
            // If assigned to a team directly, check if ID matches a team
            const assignedTeam = teams.find(t => t.id === initialTask.assigneeId);
            if (assignedTeam) setTargetTeamId(assignedTeam.id);
        }

      } else {
        // New Task
        setTitle('');
        setDescription('');
        setAssigneeId(currentUser.id); // Default to current user
        setTargetTeamId(currentUser.teamId || teams[0]?.id || '');
        setPriority('MEDIUM');
        setStatus('TODO');
        setDateStr(selectedDate ? format(selectedDate, 'yyyy-MM-dd') : format(new Date(), 'yyyy-MM-dd'));
        setStartTime('08:00');
        setEndTime('09:00');
        setIsNudged(false);
      }
    }
  }, [isOpen, initialTask, selectedDate, currentUser, users, teams]);

  // Track changes to show save button prompt
  useEffect(() => {
     if(isOpen) setHasUnsavedChanges(true);
  }, [title, description, assigneeId, targetTeamId, priority, status, dateStr, startTime, endTime, isNudged]);


  if (!isOpen) return null;

  const buildTaskObject = (overrides: Partial<Task> = {}): Task | null => {
    if (!title.trim() || !dateStr) return null;

    const [year, month, day] = dateStr.split('-').map(Number);
    const localDate = new Date(year, month - 1, day);

    return {
      id: initialTask?.id || crypto.randomUUID(),
      title,
      description,
      assigneeId,
      targetTeamId,
      priority,
      status,
      date: normalizeDate(localDate),
      startTime,
      endTime,
      isNudged,
      ...overrides
    };
  };

  const handleSave = () => {
    const task = buildTaskObject();
    if (task) {
      onSave(task);
      onClose();
    }
  };

  const handleNudge = () => {
       // Just update local state immediately to show visual feedback
       if (!description.includes('[COBRANÇA]')) {
         setDescription(`[COBRANÇA]: Solicitada prioridade em ${format(new Date(), 'dd/MM HH:mm')}.\n` + description);
       }
       setPriority('HIGH');
       setIsNudged(true);
       setPendingNudge(true); // Triggers visual warning to save
  };

  const handleClaimTask = () => {
    const confirmed = window.confirm("Você tem certeza que deseja assumir a responsabilidade por esta demanda?\n\nO responsável será alterado para você. Clique em 'Salvar' para confirmar.");
    if (confirmed) {
       // Just update local state
       setAssigneeId(currentUser.id);
       setTargetTeamId(currentUser.teamId); // Update team to my team as well
    }
  };

  const isLeader = currentUser.role === 'LEADER';
  const isCoordinator = currentUser.role === 'COORDINATOR';
  const isOwner = initialTask ? initialTask.assigneeId === currentUser.id : true; // True if creating new
  const isTeamTask = initialTask ? teams.some(t => t.id === initialTask.assigneeId) : false;
  const isCreating = !initialTask;

  // Permissions Logic
  // Team tasks can be edited by anyone in that team (conceptually shared)
  const canEditDetails = isCoordinator || isLeader || isOwner || isCreating || (isTeamTask && currentUser.teamId === initialTask?.targetTeamId);
  const canEditStatus = isCoordinator || isLeader || isOwner || (isTeamTask && currentUser.teamId === initialTask?.targetTeamId);
  const canNudge = (isLeader || isCoordinator) && !isOwner && initialTask;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in duration-200">

        {/* Header */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 flex justify-between items-center">
          <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
            {initialTask ? 'Detalhes da Demanda' : 'Nova Demanda'}
            {isNudged && <span className="bg-red-100 text-red-600 text-[10px] px-2 py-0.5 rounded-full border border-red-200 animate-pulse">URGENTE / COBRADO</span>}
          </h2>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 space-y-5">

          {/* View Only Warning for non-owners */}
          {!canEditDetails && (
             <div className="bg-blue-50 border border-blue-200 text-blue-800 p-3 rounded-lg text-sm flex items-start gap-2">
                <AlertCircle size={16} className="mt-0.5" />
                <div>
                   Visualizando demanda de outro membro.
                </div>
             </div>
          )}

          {/* Nudge Warning */}
          {pendingNudge && (
             <div className="bg-amber-50 border border-amber-200 text-amber-800 p-3 rounded-lg text-sm flex items-start gap-2 animate-in slide-in-from-top-2">
                <Megaphone size={16} className="mt-0.5" />
                <div>
                   <strong>Cobrança registrada!</strong> A prioridade foi alterada para ALTA e uma nota foi adicionada à descrição. <br/>
                   Clique em <strong>Salvar</strong> para confirmar.
                </div>
             </div>
          )}

          {/* Title */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Título</label>
            <input
              type="text"
              disabled={!canEditDetails}
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 disabled:text-slate-500"
              placeholder="Ex: Entregar relatório de vendas"
            />
          </div>

          {/* Date & Time Row */}
          <div className="grid grid-cols-3 gap-3">
            <div className="col-span-1">
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <CalendarIcon size={14} /> Data
              </label>
              <input
                type="date"
                disabled={!canEditDetails}
                value={dateStr}
                onChange={(e) => setDateStr(e.target.value)}
                className="w-full px-2 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 text-sm"
              />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <Clock size={14} /> Início
              </label>
              <input
                type="time"
                disabled={!canEditDetails}
                value={startTime}
                onChange={(e) => setStartTime(e.target.value)}
                className="w-full px-2 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 text-sm"
              />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <Clock size={14} /> Fim
              </label>
              <input
                type="time"
                disabled={!canEditDetails}
                value={endTime}
                onChange={(e) => setEndTime(e.target.value)}
                className="w-full px-2 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 text-sm"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
             {/* Assignee (Grouped by Team) */}
             <div>
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <UserIcon size={14} /> Responsável
              </label>
              <div className="relative">
                <select
                  disabled={!canEditDetails} 
                  value={assigneeId}
                  onChange={(e) => {
                     setAssigneeId(e.target.value);
                     // Auto-update team ID based on user OR team selection
                     const u = users.find(u => u.id === e.target.value);
                     if(u) {
                        setTargetTeamId(u.teamId);
                     } else {
                        // Check if it's a team ID (Group Task)
                        const t = teams.find(team => team.id === e.target.value);
                        if(t) setTargetTeamId(t.id);
                     }
                  }}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 appearance-none disabled:bg-slate-100 disabled:text-slate-500 text-sm"
                >
                  {teams.map(team => {
                    const teamMembers = users.filter(u => u.teamId === team.id);
                    // Show team option even if empty members, to allow assigning to future team
                    return (
                      <optgroup key={team.id} label={team.name}>
                        <option value={team.id} className="font-bold">📣 TODA A EQUIPE</option>
                        {teamMembers.map((user) => (
                          <option key={user.id} value={user.id}>
                            {user.name}
                          </option>
                        ))}
                      </optgroup>
                    );
                  })}
                  <optgroup label="Sem Setor">
                    {users.filter(u => !u.teamId).map(user => (
                       <option key={user.id} value={user.id}>{user.name}</option>
                    ))}
                  </optgroup>
                </select>
                <div className="absolute right-3 top-2.5 pointer-events-none text-slate-400">
                  <UserIcon size={16} />
                </div>
              </div>
            </div>

            {/* Target Team Selection (Explicit) */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <Flag size={14} /> Equipe da Demanda
              </label>
              <select
                disabled={!canEditDetails}
                value={targetTeamId}
                onChange={(e) => setTargetTeamId(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100"
              >
                 <option value="" disabled>Selecione...</option>
                 {teams.map(t => (
                   <option key={t.id} value={t.id}>{t.name}</option>
                 ))}
              </select>
            </div>
          </div>

          {/* Status and Priority */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <Flag size={14} /> Prioridade
              </label>
              <select
                disabled={!canEditDetails}
                value={priority}
                onChange={(e) => setPriority(e.target.value as Priority)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100"
              >
                <option value="LOW">Baixa</option>
                <option value="MEDIUM">Média</option>
                <option value="HIGH">Alta</option>
              </select>
            </div>

            <div>
               <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                 <CheckCircle2 size={14} /> Status
               </label>
               <select
                 disabled={!canEditStatus}
                 value={status}
                 onChange={(e) => setStatus(e.target.value as TaskStatus)}
                 className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100"
               >
                 {Object.keys(STATUS_LABELS).map((s) => (
                    <option key={s} value={s}>{STATUS_LABELS[s as TaskStatus]}</option>
                 ))}
               </select>
            </div>
          </div>

          {/* Description */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Descrição</label>
            <textarea
              disabled={!canEditDetails}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
              className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 resize-none text-sm"
              placeholder="Detalhes adicionais..."
            />
          </div>

        </div>

        {/* Footer */}
        <div className="bg-slate-50 border-t border-slate-100 px-6 py-4 flex justify-between items-center">
           {/* Left Action: Delete or Claim or Nudge */}
           <div className="flex gap-2">
             {initialTask && (isLeader || isCoordinator) && (
                <button
                  onClick={() => {
                    if (onDelete && initialTask) onDelete(initialTask.id);
                    onClose();
                  }}
                  className="px-3 py-2 text-sm font-medium text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                >
                  Excluir
                </button>
             )}

             {canNudge && !isNudged && (
                <button
                  onClick={handleNudge}
                  disabled={pendingNudge}
                  className="px-3 py-2 text-sm font-medium text-amber-700 bg-amber-50 hover:bg-amber-100 border border-amber-200 rounded-lg transition-colors flex items-center gap-1 disabled:opacity-50"
                  title="Atualizará prioridade para Alta e adicionará flag de Cobrança. Requer salvar."
                >
                  <Megaphone size={14} /> {pendingNudge ? 'Cobrança Pendente' : 'Cobrar Entrega'}
                </button>
             )}

             {!isOwner && !isTeamTask && initialTask && (
               <button
                 onClick={handleClaimTask}
                 className="px-3 py-2 text-sm font-medium text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                 title="Tornar-se o responsável. Requer salvar."
               >
                 Assumir
               </button>
             )}
           </div>

           <div className="flex gap-3">
             <button
               onClick={onClose}
               className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-200 rounded-lg transition-colors"
             >
               Cancelar
             </button>
             {canEditDetails && (
               <button
                 onClick={handleSave}
                 className="px-4 py-2 text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-md shadow-indigo-200 transition-all hover:scale-105"
               >
                 Salvar
               </button>
             )}
           </div>
        </div>
      </div>
    </div>
  );
};

export default TaskModal;

import React, { useState } from 'react';
import { 
  startOfMonth, endOfMonth, startOfWeek, endOfWeek, 
  eachDayOfInterval, isSameMonth, isSameDay, addMonths, subMonths, 
  format, isToday, isWithinInterval 
} from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { ChevronLeft, ChevronRight, Plus, AlertTriangle, Users } from 'lucide-react';
import { Task, User, normalizeDate, AlertPeriod, ALERT_COLOR_MAP, Team } from '../types';
import { STATUS_COLORS } from '../constants';

interface CalendarProps {
  tasks: Task[];
  users: User[];
  teams: Team[];
  alertPeriods: AlertPeriod[];
  currentUser: User;
  onAddTask: (date: Date) => void;
  onEditTask: (task: Task) => void;
}

const Calendar: React.FC<CalendarProps> = ({ tasks, users, teams, alertPeriods, currentUser, onAddTask, onEditTask }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const firstDayOfMonth = startOfMonth(currentDate);
  const lastDayOfMonth = endOfMonth(currentDate);
  const startDate = startOfWeek(firstDayOfMonth); 
  const endDate = endOfWeek(lastDayOfMonth);

  const days = eachDayOfInterval({ start: startDate, end: endDate });

  const nextMonth = () => setCurrentDate(addMonths(currentDate, 1));
  const prevMonth = () => setCurrentDate(subMonths(currentDate, 1));
  const goToToday = () => setCurrentDate(new Date());

  const getTasksForDay = (date: Date) => {
    return tasks
      .filter(task => isSameDay(normalizeDate(task.date), normalizeDate(date)))
      .sort((a, b) => (a.startTime || '').localeCompare(b.startTime || ''));
  };

  const getAlertForDay = (date: Date) => {
    return alertPeriods.find(period => 
      isWithinInterval(normalizeDate(date), { 
        start: normalizeDate(period.startDate), 
        end: normalizeDate(period.endDate) 
      })
    );
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">

      {/* Calendar Header */}
      <div className="flex-none flex items-center justify-between px-6 py-4 border-b border-slate-100 bg-white z-10">
        <div className="flex items-center gap-4">
          <h2 className="text-2xl font-bold text-slate-800 capitalize">
            {format(currentDate, 'MMMM yyyy', { locale: ptBR })}
          </h2>
          <div className="flex items-center bg-slate-100 rounded-lg p-1">
            <button onClick={prevMonth} className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-slate-600">
              <ChevronLeft size={20} />
            </button>
            <button onClick={nextMonth} className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-slate-600">
              <ChevronRight size={20} />
            </button>
          </div>
        </div>

        <button 
          onClick={goToToday}
          className="px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-200 hover:bg-slate-50 hover:border-slate-300 rounded-lg transition-colors"
        >
          Hoje
        </button>
      </div>

      {/* Days of Week Header */}
      <div className="flex-none grid grid-cols-7 border-b border-slate-100 bg-slate-50">
        {['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'].map((day) => (
          <div key={day} className="py-3 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">
            {day}
          </div>
        ))}
      </div>

      {/* Calendar Grid - Scrollable Area */}
      <div className="flex-1 overflow-y-auto custom-scrollbar">
        <div className="grid grid-cols-7 min-h-full auto-rows-[minmax(120px,1fr)] bg-slate-100 gap-[1px]">
          {days.map((day) => {
            const dayTasks = getTasksForDay(day);
            const isCurrentMonth = isSameMonth(day, currentDate);
            const isDayToday = isToday(day);
            const alert = getAlertForDay(day);
            const alertStyles = alert ? ALERT_COLOR_MAP[alert.color] : null;

            return (
              <div 
                key={day.toISOString()} 
                className={`
                  relative flex flex-col p-2 group transition-colors min-h-[140px]
                  ${!isCurrentMonth ? 'bg-slate-50/50' : 'bg-white'}
                  ${alertStyles ? alertStyles.bg + ' bg-opacity-30' : ''}
                `}
              >
                {/* Alert Background Label */}
                {alertStyles && (
                   <div className={`absolute top-0 left-0 w-full h-1 ${alertStyles.bg.replace('50', '400')}`}></div>
                )}

                {/* Day Number */}
                <div className="flex justify-between items-start mb-1">
                  <span className={`
                    text-sm font-medium w-7 h-7 flex items-center justify-center rounded-full z-10
                    ${isDayToday 
                      ? 'bg-indigo-600 text-white' 
                      : isCurrentMonth ? 'text-slate-700' : 'text-slate-400'}
                  `}>
                    {format(day, 'd')}
                  </span>

                   {/* Alert Icon */}
                   {alert && alertStyles && (
                     <div className="flex items-center gap-1 overflow-hidden">
                       <span className={`text-[10px] font-bold uppercase tracking-tighter truncate ${alertStyles.text}`}>
                         {alert.label}
                       </span>
                       <AlertTriangle size={12} className={alertStyles.icon} />
                     </div>
                   )}

                  {/* Add Button */}
                  <button 
                    onClick={() => onAddTask(day)}
                    className="opacity-0 group-hover:opacity-100 p-1 text-indigo-600 hover:bg-indigo-50 rounded transition-all"
                    title="Nova Demanda"
                  >
                    <Plus size={16} />
                  </button>
                </div>

                {/* Tasks List */}
                <div className="flex flex-col gap-1 overflow-y-auto max-h-[120px] custom-scrollbar z-0">
                  {dayTasks.map(task => {
                    const assignee = users.find(u => u.id === task.assigneeId);
                    const assignedTeam = !assignee ? teams.find(t => t.id === task.assigneeId) : null;

                    return (
                      <button
                        key={task.id}
                        onClick={(e) => {
                          e.stopPropagation();
                          onEditTask(task);
                        }}
                        className={`
                          text-left text-[10px] p-1.5 rounded-md border shadow-sm transition-transform hover:scale-[1.02]
                          ${STATUS_COLORS[task.status]}
                        `}
                      >
                        <div className="flex justify-between items-center mb-0.5 opacity-75">
                           <span>{task.startTime || '??:??'} - {task.endTime || '??:??'}</span>
                        </div>
                        <div className="font-semibold truncate leading-tight mb-0.5">{task.title}</div>
                        <div className="flex items-center justify-between opacity-80">
                          {assignee && (
                            <div className="flex items-center gap-1">
                               <img src={assignee.avatar} alt="" className="w-3 h-3 rounded-full" />
                               <span className="truncate max-w-[40px]">{assignee.name.split(' ')[0]}</span>
                            </div>
                          )}
                          {assignedTeam && (
                            <div className="flex items-center gap-1 bg-white/50 px-1 rounded">
                               <Users size={10} className="text-current" />
                               <span className="uppercase font-bold tracking-tighter">EQUIPE</span>
                            </div>
                          )}
                        </div>
                      </button>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Calendar;

import React from 'react';
import { Task, User, Team, normalizeDate } from '../types';
import { STATUS_LABELS, STATUS_COLORS } from '../constants';
import { format, isSameDay } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { Clock, CheckCircle2, Users } from 'lucide-react';

interface TaskListViewProps {
  tasks: Task[];
  currentUser: User;
  users: User[];
  teams: Team[];
  onEditTask: (task: Task) => void;
}

const TaskListView: React.FC<TaskListViewProps> = ({ tasks, currentUser, users, teams, onEditTask }) => {
  // Sort tasks by date and then by start time
  const sortedTasks = [...tasks].sort((a, b) => {
    const dateComp = a.date.getTime() - b.date.getTime();
    if (dateComp !== 0) return dateComp;
    return (a.startTime || '').localeCompare(b.startTime || '');
  });

  // Group by Date
  const groupedTasks: Record<string, Task[]> = {};
  sortedTasks.forEach(task => {
    const dateKey = task.date.toISOString();
    if (!groupedTasks[dateKey]) groupedTasks[dateKey] = [];
    groupedTasks[dateKey].push(task);
  });

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 h-full overflow-y-auto custom-scrollbar p-6">
      <h2 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
        <Clock className="text-indigo-600" /> Cronograma de Demandas
      </h2>

      {Object.keys(groupedTasks).length === 0 ? (
        <div className="text-center py-12 text-slate-400">
          Nenhuma demanda encontrada.
        </div>
      ) : (
        <div className="space-y-8">
          {Object.entries(groupedTasks).map(([dateStr, dayTasks]) => {
            const date = new Date(dateStr);
            const isToday = isSameDay(date, new Date());

            return (
              <div key={dateStr} className="relative pl-6 border-l-2 border-indigo-100">
                <div className={`
                  absolute -left-[9px] top-0 w-4 h-4 rounded-full border-2 border-white
                  ${isToday ? 'bg-indigo-600 shadow-md shadow-indigo-200' : 'bg-slate-300'}
                `}></div>

                <h3 className={`text-sm font-bold uppercase tracking-wide mb-4 ${isToday ? 'text-indigo-600' : 'text-slate-500'}`}>
                  {format(date, "dd/MM/yy ' - ' EEEE", { locale: ptBR })} {isToday && '(Hoje)'}
                </h3>

                <div className="space-y-3">
                  {dayTasks.map(task => {
                    const assignee = users.find(u => u.id === task.assigneeId);
                    const assignedTeam = !assignee ? teams.find(t => t.id === task.assigneeId) : null;

                    return (
                      <div 
                        key={task.id}
                        onClick={() => onEditTask(task)}
                        className="group flex items-center justify-between p-4 bg-slate-50 hover:bg-white rounded-xl border border-slate-100 hover:border-indigo-200 hover:shadow-md transition-all cursor-pointer"
                      >
                        <div className="flex items-start gap-4">
                          <div className="flex flex-col items-center min-w-[60px]">
                            <span className="text-sm font-bold text-slate-700">{task.startTime || '--:--'}</span>
                            <span className="text-xs text-slate-400">às {task.endTime || '--:--'}</span>
                          </div>

                          <div>
                            <h4 className="font-semibold text-slate-800 group-hover:text-indigo-700 transition-colors flex items-center gap-2">
                              {task.title}
                              {assignedTeam && (
                                <span className="bg-slate-200 text-slate-700 text-[10px] px-1.5 py-0.5 rounded font-bold uppercase flex items-center gap-1">
                                    <Users size={10} /> TIME
                                </span>
                              )}
                            </h4>
                            <div className="flex items-center gap-2 mt-1">
                              {assignee && (
                                <div className="flex items-center gap-1.5 bg-white px-2 py-0.5 rounded-full border border-slate-200">
                                  <img src={assignee.avatar} className="w-4 h-4 rounded-full" alt="" />
                                  <span className="text-xs text-slate-600">{assignee.name.split(' ')[0]}</span>
                                </div>
                              )}
                              {assignedTeam && (
                                <div className="flex items-center gap-1.5 bg-indigo-50 px-2 py-0.5 rounded-full border border-indigo-100">
                                   <Users size={12} className="text-indigo-600" />
                                   <span className="text-xs font-bold text-indigo-700">Toda a Equipe</span>
                                </div>
                              )}

                              <span className={`text-[10px] px-2 py-0.5 rounded-full border font-medium ${STATUS_COLORS[task.status]}`}>
                                {STATUS_LABELS[task.status]}
                              </span>
                            </div>
                          </div>
                        </div>

                        <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                          <CheckCircle2 className="text-slate-300 hover:text-indigo-600" />
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default TaskListView;

export type Role = 'COORDINATOR' | 'LEADER' | 'MEMBER';

export type TaskStatus = 'TODO' | 'IN_PROGRESS' | 'DONE';

export type Priority = 'LOW' | 'MEDIUM' | 'HIGH';

export type AlertColor = 'RED' | 'ORANGE' | 'BLUE' | 'PURPLE' | 'GREEN';

export interface Team {
  id: string;
  name: string;
  color: string; // Hex or tailwind class reference
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: Role;
  teamId: string;
  avatar: string;
  presencialDates: string[]; // Array of ISO date strings (yyyy-MM-dd)
  password?: string; 
}

export interface Task {
  id: string;
  title: string;
  description: string;
  assigneeId: string;
  targetTeamId?: string; // Optional: If specific to a team context
  date: Date; // Normalized to midnight
  startTime?: string; // Format "HH:mm"
  endTime?: string;   // Format "HH:mm"
  status: TaskStatus;
  priority: Priority;
  isNudged?: boolean; // If true, it was "Cobrada"
  teamProgress?: Record<string, TaskStatus>; // Map userId -> status for team tasks
}

export interface AlertPeriod {
  id: string;
  startDate: Date;
  endDate: Date;
  label: string;
  color: AlertColor;
  targetTeamId?: string | 'ALL'; // Filter alert by team
}

export interface Notification {
  id: string;
  targetUserId: string; // Who should see this
  message: string;
  date: Date;
  read: boolean;
  type: 'TASK_ASSIGNED' | 'NUDGE';
}

// Helper to keep dates consistent
export const normalizeDate = (date: Date): Date => {
  const newDate = new Date(date);
  newDate.setHours(0, 0, 0, 0);
  return newDate;
};

// Helper for colors
export const ALERT_COLOR_MAP: Record<AlertColor, { bg: string, border: string, text: string, icon: string }> = {
  RED: { bg: 'bg-red-50', border: 'border-red-200', text: 'text-red-700', icon: 'text-red-500' },
  ORANGE: { bg: 'bg-orange-50', border: 'border-orange-200', text: 'text-orange-700', icon: 'text-orange-500' },
  BLUE: { bg: 'bg-blue-50', border: 'border-blue-200', text: 'text-blue-700', icon: 'text-blue-500' },
  PURPLE: { bg: 'bg-purple-50', border: 'border-purple-200', text: 'text-purple-700', icon: 'text-purple-500' },
  GREEN: { bg: 'bg-emerald-50', border: 'border-emerald-200', text: 'text-emerald-700', icon: 'text-emerald-500' },
};

import React, { useState, useEffect, useRef } from 'react';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import TaskListView from './components/TaskListView';
import TeamModal from './components/TeamModal';
import AlertModal from './components/AlertModal';
import DashboardView from './components/DashboardView';
import PresencialModal from './components/PresencialModal';
import UserAuthModal from './components/UserAuthModal'; 
import LoginScreen from './components/LoginScreen';

import { User, Task, AlertPeriod, Team, Notification, TaskStatus } from './types';
import { USERS, INITIAL_TASKS, INITIAL_TEAMS } from './constants';
import { api, getApiUrl } from './services/api';
import { Layout, CheckSquare, List, Calendar as CalendarIcon, Settings, PieChart, MapPin, AlertTriangle, Users, Database, Loader2, Filter, KeyRound, Bell, LogOut } from 'lucide-react';
import { format, isValid } from 'date-fns';

const App: React.FC = () => {
  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<User>(USERS[0]); 

  // Data State
  const [isSyncing, setIsSyncing] = useState(false);
  const [isLoadingInitial, setIsLoadingInitial] = useState(true);
  const [connectionStatus, setConnectionStatus] = useState<'DISCONNECTED' | 'CONNECTED' | 'ERROR'>('DISCONNECTED');

  const [tasks, setTasks] = useState<Task[]>([]);
  const [teamUsers, setTeamUsers] = useState<User[]>([]);
  const [teams, setTeams] = useState<Team[]>([]);
  const [alertPeriods, setAlertPeriods] = useState<AlertPeriod[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const [viewMode, setViewMode] = useState<'CALENDAR' | 'LIST' | 'DASHBOARD'>('CALENDAR');
  const [filterScope, setFilterScope] = useState<string>('MY_TEAM'); 
  const [filterStatus, setFilterStatus] = useState<TaskStatus | 'ALL'>('ALL'); 

  // Modals State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [isAlertModalOpen, setIsAlertModalOpen] = useState(false);
  const [isPresencialModalOpen, setIsPresencialModalOpen] = useState(false);
  const [isUserSwitcherOpen, setIsUserSwitcherOpen] = useState(false);
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);

  // Auth Modal State
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authTargetUser, setAuthTargetUser] = useState<User | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'CHANGE_PASSWORD'>('LOGIN');

  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  // Refs
  const userSwitcherRef = useRef<HTMLDivElement>(null);
  const notificationRef = useRef<HTMLDivElement>(null);
  const tasksRef = useRef<Task[]>([]);
  const currentUserRef = useRef<User>(currentUser);
  const isFirstLoadRef = useRef(true);

  // Keep refs synced
  useEffect(() => { tasksRef.current = tasks; }, [tasks]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);

  // --- CLICK OUTSIDE HANDLER ---
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (userSwitcherRef.current && !userSwitcherRef.current.contains(event.target as Node)) {
        setIsUserSwitcherOpen(false);
      }
      if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // --- API & SYNC LOGIC ---
  const fetchData = async (): Promise<boolean> => {
    if (!getApiUrl()) {
        // Fallback demo mode if no URL is hardcoded
        setTasks(INITIAL_TASKS);
        setTeamUsers(USERS);
        setTeams(INITIAL_TEAMS);
        setIsLoadingInitial(false);
        return false;
    }

    try {
      setIsSyncing(true);
      const data = await api.sync();

      // PARSE TASKS
      const parsedTasks: Task[] = data.tasks.map((t: any) => {
        let dateObj;
        if (typeof t.date === 'string' && t.date.includes('-') && !t.date.includes('T')) {
           const [y, m, d] = t.date.split('-').map(Number);
           dateObj = new Date(y, m - 1, d);
        } else if (typeof t.date === 'string') {
           const datePart = t.date.substring(0, 10);
           if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
             const [y, m, d] = datePart.split('-').map(Number);
             dateObj = new Date(y, m - 1, d);
           } else {
             dateObj = new Date(t.date);
           }
        } else {
           dateObj = new Date(t.date);
        }

        const cleanTime = (val: any) => {
          if (!val) return '';
          const strVal = String(val);
          if (strVal.match(/^\d{1,2}:\d{2}$/)) return strVal;
          const d = new Date(strVal);
          if (isValid(d)) return format(d, 'HH:mm');
          return strVal;
        };

        // Handle teamProgress JSON string if it comes from stringified source
        let tp = t.teamProgress;
        if (typeof tp === 'string') {
          try { tp = JSON.parse(tp); } catch(e) { tp = {}; }
        }

        return { 
          ...t, 
          title: t.title || 'Sem título', 
          date: dateObj,
          startTime: cleanTime(t.startTime),
          endTime: cleanTime(t.endTime),
          teamProgress: tp || {}
        };
      });

      const parsedAlerts: AlertPeriod[] = data.alerts.map((a: any) => {
         let start, end;
         if (typeof a.startDate === 'string') {
            const datePart = a.startDate.substring(0, 10);
            if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
               const [y, m, d] = datePart.split('-').map(Number);
               start = new Date(y, m - 1, d);
            } else start = new Date(a.startDate);
         } else start = new Date(a.startDate);

         if (typeof a.endDate === 'string') {
             const datePart = a.endDate.substring(0, 10);
             if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
                const [y, m, d] = datePart.split('-').map(Number);
                end = new Date(y, m - 1, d);
             } else end = new Date(a.endDate);
         } else end = new Date(a.endDate);

         return { ...a, startDate: start, endDate: end };
      });

      const parsedUsers: User[] = data.users.map((u: any) => ({
        ...u,
        presencialDates: Array.isArray(u.presencialDates) ? u.presencialDates : [],
        password: (u.password !== undefined && u.password !== null && u.password !== '') ? String(u.password) : undefined
      }));

      const parsedTeams: Team[] = data.teams || [];

      updateNotifications(parsedTasks);
      isFirstLoadRef.current = false;
      setTasks(parsedTasks);

      // Update Users List (merging passwords if needed locally, but usually fresh from API)
      if (parsedUsers.length > 0) {
        setTeamUsers(parsedUsers);
      } else {
        setTeamUsers(USERS); // Fallback
      }

      if (parsedTeams.length > 0) setTeams(parsedTeams);
      else setTeams(INITIAL_TEAMS);

      setAlertPeriods(parsedAlerts);
      setConnectionStatus('CONNECTED');
      setIsLoadingInitial(false);
      return true;
    } catch (error) {
      console.error("Sync Error", error);
      setConnectionStatus('ERROR');
      setIsLoadingInitial(false);
      return false;
    } finally {
      setIsSyncing(false);
    }
  };

  // Initial Fetch on Mount
  useEffect(() => {
    fetchData();
    // AUMENTADO PARA 60 SEGUNDOS (1 MIN) CONFORME SOLICITADO
    const intervalId = setInterval(fetchData, 60000); 
    return () => clearInterval(intervalId);
  }, []); 

  // --- NOTIFICATION LOGIC ---
  const updateNotifications = (currentTasks: Task[]) => {
      setNotifications(prev => {
         const readIds = JSON.parse(localStorage.getItem('GEST_PRO_READ_NOTIFS') || '[]');
         const currentIds = new Set(prev.map(n => n.id));
         const incomingNotifications: Notification[] = [];
         const myId = currentUserRef.current.id;

         currentTasks.forEach(task => {
             if (task.isNudged) {
                 const notifId = `${task.id}_nudge`;
                 // Logic updated: If it's a team task, verify if *I* am responsible
                 const isMyResponsibility = task.assigneeId === myId || (teams.some(t => t.id === task.assigneeId) && currentUserRef.current.teamId === task.assigneeId);

                 if (isMyResponsibility && !readIds.includes(notifId) && !currentIds.has(notifId)) {
                     const title = task.title && task.title.trim() !== '' ? task.title : 'Tarefa sem título';
                     incomingNotifications.push({
                        id: notifId,
                        targetUserId: myId,
                        message: `⚠️ URGENTE: A demanda "${title}" foi cobrada!`,
                        date: new Date(),
                        read: false,
                        type: 'NUDGE'
                     });
                     currentIds.add(notifId);
                 }
             }
         });

         if (!isFirstLoadRef.current && tasksRef.current.length > 0) {
            currentTasks.forEach(newTask => {
                const oldTask = tasksRef.current.find(t => t.id === newTask.id);
                // Notification for assignments
                // Only notify if assignment CHANGED or it's new
                if ((!oldTask || oldTask.assigneeId !== newTask.assigneeId)) {
                   const isAssignedToMe = newTask.assigneeId === myId;
                   const isAssignedToMyTeam = teams.some(t => t.id === newTask.assigneeId) && currentUserRef.current.teamId === newTask.assigneeId;

                   if (isAssignedToMe || isAssignedToMyTeam) {
                      const notifId = `assign_${newTask.id}_${newTask.assigneeId}`;
                      if (!currentIds.has(notifId) && !readIds.includes(notifId)) {
                          const title = newTask.title && newTask.title.trim() !== '' ? newTask.title : 'Tarefa sem título';
                          incomingNotifications.push({ 
                              id: notifId, 
                              targetUserId: myId,
                              message: isAssignedToMyTeam ? `Nova demanda para equipe: ${title}` : `Nova demanda atribuída: ${title}`, 
                              date: new Date(), 
                              read: false, 
                              type: 'TASK_ASSIGNED' 
                          });
                          currentIds.add(notifId);
                      }
                   }
                }
            });
         }
         if (incomingNotifications.length === 0) return prev;
         return [...incomingNotifications, ...prev];
      });
  };

  useEffect(() => {
    if (isAuthenticated) setFilterScope('MY_TEAM');
  }, [currentUser.id, isAuthenticated]);

  const handleMarkAsRead = () => {
     const currentRead = JSON.parse(localStorage.getItem('GEST_PRO_READ_NOTIFS') || '[]');
     const newIds = notifications.filter(n => n.targetUserId === currentUser.id).map(n => n.id);
     localStorage.setItem('GEST_PRO_READ_NOTIFS', JSON.stringify([...new Set([...currentRead, ...newIds])]));
     setNotifications(prev => prev.filter(n => n.targetUserId !== currentUser.id));
  };

  // --- LOGIN FLOW HANDLERS ---
  const handleLoginClick = (user: User) => {
    setAuthTargetUser(user);
    setAuthMode('LOGIN');
    setIsAuthModalOpen(true);
  };

  const handleLoginSuccess = async (updatedUser?: User) => {
     if (updatedUser) {
        setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
        setCurrentUser(updatedUser);
        if (getApiUrl()) await api.saveUser(updatedUser);
     } else if (authTargetUser) {
        setCurrentUser(authTargetUser);
     }
     setIsAuthenticated(true);
     setAuthTargetUser(null);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setViewMode('CALENDAR');
    setIsUserSwitcherOpen(false);
  };

  // --- AUTH HANDLERS (Inside App) ---
  const handleUserSwitchClick = (user: User) => {
    setAuthTargetUser(user);
    setAuthMode('LOGIN');
    setIsAuthModalOpen(true);
    setIsUserSwitcherOpen(false); 
  };

  const handleChangePasswordClick = () => {
    setAuthTargetUser(currentUser);
    setAuthMode('CHANGE_PASSWORD');
    setIsAuthModalOpen(true);
  };

  const handleAuthModalSuccess = async (updatedUser?: User) => {
    if (updatedUser) {
        setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
        setCurrentUser(updatedUser);
        if (getApiUrl()) await api.saveUser(updatedUser);
        if (authMode === 'CHANGE_PASSWORD') alert("Senha alterada com sucesso!");
    } else if (authTargetUser) {
       setCurrentUser(authTargetUser);
       setIsAuthenticated(true); 
    }
  };


  // --- DATA HANDLERS ---
  const handleAddTask = (date: Date) => { setSelectedDate(date); setSelectedTask(null); setIsModalOpen(true); };
  const handleEditTask = (task: Task) => { setSelectedTask(task); setSelectedDate(task.date); setIsModalOpen(true); };

  const handleSaveTask = async (taskToSave: Task) => {
    const safeTask = { 
       ...taskToSave, 
       title: taskToSave.title || 'Sem título',
       teamProgress: taskToSave.teamProgress || {} // Ensure property exists
    };
    setTasks(prev => {
      const exists = prev.find(t => t.id === safeTask.id);
      return exists ? prev.map(t => t.id === safeTask.id ? safeTask : t) : [...prev, safeTask];
    });
    if (getApiUrl()) { await api.saveTask(safeTask); fetchData(); }
  };

  const handleDeleteTask = async (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
    if (getApiUrl()) { await api.deleteTask(taskId); fetchData(); }
  };

  const handleAddUser = async (newUser: User) => {
    setTeamUsers(prev => [...prev, newUser]);
    if (getApiUrl()) { await api.saveUser(newUser); fetchData(); }
  };

  const handleEditUser = async (updatedUser: User) => {
    setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser.id === updatedUser.id) setCurrentUser(prev => ({...prev, ...updatedUser}));
    if (getApiUrl()) {
      const localUser = teamUsers.find(u => u.id === updatedUser.id);
      const userToSend = { ...updatedUser };
      if (localUser?.password && !userToSend.password) userToSend.password = localUser.password;
      await api.saveUser(userToSend);
      fetchData();
    }
  };

  const handleRemoveUser = async (userId: string) => {
    setTeamUsers(prev => prev.filter(u => u.id !== userId));
    if (getApiUrl()) { await api.deleteUser(userId); fetchData(); }
  };

  const handleAddTeam = async (newTeam: Team) => {
    setTeams(prev => [...prev, newTeam]);
    if (getApiUrl()) { await api.saveTeam(newTeam); fetchData(); }
  };

  const handleRemoveTeam = async (teamId: string) => {
    setTeams(prev => prev.filter(t => t.id !== teamId));
    if (getApiUrl()) { await api.deleteTeam(teamId); fetchData(); }
  };

  const handleSaveAlert = async (newAlert: AlertPeriod) => {
    setAlertPeriods(prev => {
       const exists = prev.find(a => a.id === newAlert.id);
       return exists ? prev.map(a => a.id === newAlert.id ? newAlert : a) : [...prev, newAlert];
    });
    if (getApiUrl()) { await api.saveAlert(newAlert); fetchData(); }
  };

  const handleDeleteAlert = async (alertId: string) => {
     setAlertPeriods(prev => prev.filter(a => a.id !== alertId));
     if (getApiUrl()) { await api.deleteAlert(alertId); fetchData(); }
  };

  const handleBatchUpdatePresence = async (updatedUsers: User[]) => {
     setTeamUsers(prev => prev.map(u => updatedUsers.find(upd => upd.id === u.id) || u));
     if (getApiUrl()) { await api.saveUsersBatch(updatedUsers); fetchData(); }
  };

  const isLeader = currentUser.role === 'LEADER' || currentUser.role === 'COORDINATOR';
  const isCoordinator = currentUser.role === 'COORDINATOR';

  const displayedTasks = tasks.filter(task => {
    // Check if task is assigned to a User OR a Team
    const assigneeUser = teamUsers.find(u => u.id === task.assigneeId);
    const assigneeTeam = teams.find(t => t.id === task.assigneeId);

    let passesScope = false;

    // Scope Logic
    if (filterScope === 'ME') {
        // Show if assigned to ME directly OR assigned to MY TEAM (Group Task)
        passesScope = task.assigneeId === currentUser.id || task.assigneeId === currentUser.teamId;
    }
    else if (filterScope === 'MY_TEAM') {
        // Show if assigned user belongs to my team OR assigned directly to my team
        if (assigneeUser) passesScope = assigneeUser.teamId === currentUser.teamId;
        else if (assigneeTeam) passesScope = assigneeTeam.id === currentUser.teamId;
        else passesScope = false; 
    }
    else if (filterScope === 'ALL_TEAMS') {
        passesScope = true;
    }
    else {
        // Specific Team ID selected
        if (assigneeUser) passesScope = assigneeUser.teamId === filterScope;
        else if (assigneeTeam) passesScope = assigneeTeam.id === filterScope;
    }

    if (!passesScope) return false;
    if (viewMode === 'LIST' && filterStatus !== 'ALL') if (task.status !== filterStatus) return false;
    return true;
  });

  const displayedAlerts = alertPeriods.filter(alert => {
     if (!alert.targetTeamId || alert.targetTeamId === 'ALL') return true;
     return alert.targetTeamId === currentUser.teamId || isCoordinator;
  });

  const myNotifications = notifications.filter(n => n.targetUserId === currentUser.id);
  const safeDate = (d: any) => (d instanceof Date && !isNaN(d.getTime())) ? d : (typeof d === 'string' ? new Date(d) : new Date());

  // --- RENDER ---

  if (!isAuthenticated) {
     return (
       <>
         <LoginScreen 
            users={teamUsers} 
            teams={teams}
            onLogin={handleLoginClick} 
            isLoading={isLoadingInitial}
         />
         <UserAuthModal 
            isOpen={isAuthModalOpen}
            onClose={() => setIsAuthModalOpen(false)}
            targetUser={authTargetUser}
            mode={authMode}
            onSuccess={handleLoginSuccess}
         />
       </>
     );
  }

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">

      {/* Sidebar */}
      <aside className="w-16 lg:w-72 bg-slate-900 text-slate-300 flex flex-col flex-shrink-0 shadow-xl z-20 transition-all">
        <div className="p-4 lg:p-6 border-b border-slate-800 flex items-center justify-center lg:justify-start gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg text-white shrink-0">
             <Layout size={24} />
          </div>
          <div className="hidden lg:flex flex-col">
