  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ error: e.toString() })).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

// --- READ OPERATIONS ---

function readAllData(ss) {
  return {
    tasks: getSheetData(ss, 'Tasks'),
    users: getSheetData(ss, 'Users'),
    teams: getSheetData(ss, 'Teams'),
    alerts: getSheetData(ss, 'Alerts')
  };
}

function getSheetData(ss, sheetName) {
  var sheet = ss.getSheetByName(sheetName);
  var data = sheet.getDataRange().getValues();
  if (data.length < 2) return []; 

  var headers = data[0];
  var rows = data.slice(1);

  return rows.map(function(row) {
    var obj = {};
    headers.forEach(function(header, index) {
      var val = row[index];
      // Tratamento especial para arrays e booleanos
      if (header === 'presencialDates' && typeof val === 'string') {
        obj[header] = val ? val.split(',') : [];
      } else if (header === 'isNudged') {
        obj[header] = (val === true || val === 'true');
      } else {
        obj[header] = val;
      }
    });
    return obj;
  });
}

