      } else {
        obj[header] = val;
      }
    });
    return obj;
  });
}

// --- WRITE OPERATIONS ---

function saveTask(ss, task) {
  var sheet = ss.getSheetByName('Tasks');
  var headers = ['id', 'title', 'description', 'assigneeId', 'date', 'startTime', 'endTime', 'status', 'priority', 'targetTeamId', 'isNudged', 'teamProgress'];
  ensureHeaders(sheet, headers);

  var rowData = [
