**ATENÇÃO: Você PRECISARÁ atualizar o seu código no Google Apps Script (Backend) para suportar as Notas e as Tarefas Recorrentes (Lote).**

### 1. Atualização do Backend (Google Apps Script)

Copie o código abaixo e substitua **tudo** no seu editor do Google Apps Script. Salve e publique uma **Nova Implantação** (New Deployment).

```javascript
/* 
  GestorPro - Backend v6.0 (Com Suporte a Notas e Lote de Tarefas)
*/

function doGet(e) {
  return handleRequest('read', null);
}

function doPost(e) {
  var action = e.parameter.action;
  var data = null;
  try {
    if (e.postData && e.postData.contents) {
      data = JSON.parse(e.postData.contents);
    }
  } catch (err) {
    return createJSONOutput({ error: "Invalid JSON body" });
  }
  return handleRequest(action, data);
}

function createJSONOutput(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

function handleRequest(action, data) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var result = {};

  try {
    // --- LEITURA (SEM LOCK) ---
    if (action === 'read') {
      ensureSheetsExist(ss);
      result = readAllData(ss);
      return createJSONOutput(result);
    }

    // --- ESCRITA (COM LOCK) ---
    var lock = LockService.getScriptLock();
    if (!lock.tryLock(10000)) {
      return createJSONOutput({ error: "Server busy" });
    }

    try {
      ensureSheetsExist(ss);

      if (action === 'saveTask') {
        saveTask(ss, data);
        result = { success: true };
      }
      else if (action === 'saveTasksBatch') {
        // Novo: Salvar várias tarefas de uma vez (recorrência)
        if (Array.isArray(data)) {
          data.forEach(function(t) { saveTask(ss, t); });
        }
        result = { success: true };
      }
      else if (action === 'deleteTask') {
        deleteRowById(ss, 'Tasks', data.id);
        result = { success: true };
      }
      else if (action === 'saveUser') {
        saveUser(ss, data);
        result = { success: true };
      }
      else if (action === 'saveUsersBatch') {
        if (Array.isArray(data)) {
          data.forEach(function(u) { saveUser(ss, u); });
        }
        result = { success: true };
      }
      else if (action === 'deleteUser') {
        deleteRowById(ss, 'Users', data.id);
        result = { success: true };
      }
      else if (action === 'saveTeam') {
        saveTeam(ss, data);
        result = { success: true };
      }
      else if (action === 'deleteTeam') {
        deleteRowById(ss, 'Teams', data.id);
        result = { success: true };
      }
      else if (action === 'saveAlert') {
        saveAlert(ss, data);
        result = { success: true };
      }
      else if (action === 'deleteAlert') {
        deleteRowById(ss, 'Alerts', data.id);
        result = { success: true };
      }
      else if (action === 'saveNote') {
        saveNote(ss, data);
        result = { success: true };
      }
      else if (action === 'deleteNote') {
        deleteRowById(ss, 'Notes', data.id);
        result = { success: true };
      }

    } catch (innerError) {
      return createJSONOutput({ error: innerError.toString() });
    } finally {
      lock.releaseLock();
    }

    return createJSONOutput(result);

  } catch (e) {
    return createJSONOutput({ error: "Critical: " + e.toString() });
  }
}

function ensureSheetsExist(ss) {
  var sheets = ['Tasks', 'Users', 'Teams', 'Alerts', 'Notes'];
  sheets.forEach(function(name) {
    if (!ss.getSheetByName(name)) ss.insertSheet(name);
  });
}

function readAllData(ss) {
  return {
    tasks: getSheetData(ss, 'Tasks'),
    users: getSheetData(ss, 'Users'),
    teams: getSheetData(ss, 'Teams'),
    alerts: getSheetData(ss, 'Alerts'),
    notes: getSheetData(ss, 'Notes')
  };
}

function getSheetData(ss, sheetName) {
  var sheet = ss.getSheetByName(sheetName);
  if (sheet.getLastRow() < 2) return [];
  var data = sheet.getDataRange().getValues();
  var headers = data[0];
  var rows = data.slice(1);
  return rows.map(function(row) {
    var obj = {};
    headers.forEach(function(header, index) {
      var val = row[index];
      if (header === 'presencialDates' && typeof val === 'string') {
        obj[header] = val ? val.split(',') : [];
      } else if (header === 'isNudged') {
        obj[header] = (val === true || val === 'true');
      } else {
        obj[header] = val;
      }
    });
    return obj;
  });
}

// --- SAVERS ---

function saveTask(ss, task) {
  var sheet = ss.getSheetByName('Tasks');
  ensureHeaders(sheet, ['id', 'title', 'description', 'assigneeId', 'date', 'startTime', 'endTime', 'status', 'priority', 'targetTeamId', 'isNudged', 'teamProgress']);
  upsertRow(sheet, task.id, [
    task.id, task.title, task.description, task.assigneeId, task.date, 
    task.startTime, task.endTime, task.status, task.priority, 
    task.targetTeamId || '', task.isNudged ? 'true' : 'false', task.teamProgress || '{}'
  ]);
}

function saveUser(ss, user) {
  var sheet = ss.getSheetByName('Users');
  ensureHeaders(sheet, ['id', 'name', 'email', 'role', 'teamId', 'avatar', 'presencialDates', 'password']);
  var pDates = Array.isArray(user.presencialDates) ? user.presencialDates.join(',') : '';
  upsertRow(sheet, user.id, [
    user.id, user.name, user.email, user.role, user.teamId, user.avatar, pDates, user.password || ''
  ]);
}

function saveTeam(ss, team) {
  var sheet = ss.getSheetByName('Teams');
  ensureHeaders(sheet, ['id', 'name', 'color']);
  upsertRow(sheet, team.id, [team.id, team.name, team.color]);
}

function saveAlert(ss, alert) {
  var sheet = ss.getSheetByName('Alerts');
  ensureHeaders(sheet, ['id', 'startDate', 'endDate', 'label', 'color', 'targetTeamId']);
  upsertRow(sheet, alert.id, [alert.id, alert.startDate, alert.endDate, alert.label, alert.color, alert.targetTeamId]);
}

function saveNote(ss, note) {
  var sheet = ss.getSheetByName('Notes');
  ensureHeaders(sheet, ['id', 'userId', 'content', 'updatedAt']);
  upsertRow(sheet, note.id, [note.id, note.userId, note.content, note.updatedAt]);
}

// --- UTILS ---

function ensureHeaders(sheet, headers) {
  if (sheet.getLastRow() === 0) sheet.appendRow(headers);
}

function upsertRow(sheet, id, rowData) {
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) {
    if (data[i][0] == id) {
      sheet.getRange(i + 1, 1, 1, rowData.length).setValues([rowData]);
      return;
    }
  }
  sheet.appendRow(rowData);
}

function deleteRowById(ss, sheetName, id) {
  var sheet = ss.getSheetByName(sheetName);
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) {
    if (data[i][0] == id) {
      sheet.deleteRow(i + 1);
      return;
    }
  }
}
```

