  const [recurrenceEndDate, setRecurrenceEndDate] = useState('');

  // Reset or populate form when modal opens
  useEffect(() => {
    if (isOpen) {
      setPendingNudge(false);
      setRecurrenceType('NONE');
      setRecurrenceEndDate('');
      if (initialTask) {
        setTitle(initialTask.title);
        setDescription(initialTask.description);
        setAssigneeId(initialTask.assigneeId);
        setPriority(initialTask.priority);
        setStatus(initialTask.status);
        setDateStr(format(initialTask.date, 'yyyy-MM-dd'));
        setStartTime(initialTask.startTime || '');
        setEndTime(initialTask.endTime || '');
        setTargetTeamId(initialTask.targetTeamId || '');
        setIsNudged(initialTask.isNudged || false);
        setTeamProgress(initialTask.teamProgress || {});

        if (!initialTask.targetTeamId) {
            const assignee = users.find(u => u.id === initialTask.assigneeId);
            if (assignee) setTargetTeamId(assignee.teamId);
            const assignedTeam = teams.find(t => t.id === initialTask.assigneeId);
            if (assignedTeam) setTargetTeamId(assignedTeam.id);
        }

      } else {
        setTitle('');
        setDescription('');
        setAssigneeId(currentUser.id); 
        setTargetTeamId(currentUser.teamId || teams[0]?.id || '');
        setPriority('MEDIUM');
        setStatus('TODO');
        setDateStr(selectedDate ? format(selectedDate, 'yyyy-MM-dd') : format(new Date(), 'yyyy-MM-dd'));
        setStartTime('08:00');
        setEndTime('09:00');
        setIsNudged(false);
        setTeamProgress({});
      }
    }
  }, [isOpen, initialTask, selectedDate, currentUser, users, teams]);


  if (!isOpen) return null;

  const buildTaskObject = (id: string, dateObj: Date): Task => {
    return {
      id,
      title,
      description,
      assigneeId,
      targetTeamId,
      priority,
      status,
      date: normalizeDate(dateObj),
      startTime,
      endTime,
      isNudged,
      teamProgress
    };
  };

  const handleSave = () => {
    if (!title.trim() || !dateStr) return;

    const [year, month, day] = dateStr.split('-').map(Number);
    const baseDate = new Date(year, month - 1, day);

    if (recurrenceType === 'NONE' || initialTask) {
       // Single Task Save (Edit or New Single)
       const task = buildTaskObject(initialTask?.id || crypto.randomUUID(), baseDate);
       onSave(task);
    } else {
       // Batch Creation (New Recurring Tasks)
       if (!recurrenceEndDate) {
           alert("Selecione uma data final para a recorrência.");
           return;
       }
       const [ey, em, ed] = recurrenceEndDate.split('-').map(Number);
       const endDateObj = new Date(ey, em - 1, ed);

       const tasksToCreate: Task[] = [];
       let currentDateCursor = baseDate;

       // Prevent infinite loops or massive creation
       let safeguard = 0;

       while (currentDateCursor <= endDateObj && safeguard < 366) {
           tasksToCreate.push(buildTaskObject(crypto.randomUUID(), new Date(currentDateCursor)));

           if (recurrenceType === 'DAILY') {
               currentDateCursor = addDays(currentDateCursor, 1);
           } else if (recurrenceType === 'WEEKLY') {
               currentDateCursor = addWeeks(currentDateCursor, 1);
           } else if (recurrenceType === 'MONTHLY') {
               currentDateCursor = addMonths(currentDateCursor, 1);
           }
           safeguard++;
       }

       if (tasksToCreate.length > 0) {
           onSave(tasksToCreate);
       }
    }
    onClose();
  };

  const handleNudge = () => {
       if (!description.includes('[COBRANÇA]')) {
         setDescription(`[COBRANÇA]: Solicitada prioridade em ${format(new Date(), 'dd/MM HH:mm')}.\n` + description);
       }
       setPriority('HIGH');
       setIsNudged(true);
       setPendingNudge(true); 
  };

  const handleClaimTask = () => {
    const confirmed = window.confirm("Você tem certeza que deseja assumir a responsabilidade por esta demanda?");
    if (confirmed) {
       setAssigneeId(currentUser.id);
       setTargetTeamId(currentUser.teamId); 
    }
  };

  const handleToggleMyTeamStatus = (status: TaskStatus) => {
    setTeamProgress(prev => ({ ...prev, [currentUser.id]: status }));
  };

  const isLeader = currentUser.role === 'LEADER';
  const isCoordinator = currentUser.role === 'COORDINATOR';
  const isOwner = initialTask ? initialTask.assigneeId === currentUser.id : true; 
  const isTeamTask = teams.some(t => t.id === assigneeId); 
  const isCreating = !initialTask;

  const canEditDetails = isCoordinator || isLeader || isOwner || isCreating || (isTeamTask && currentUser.teamId === initialTask?.targetTeamId);
  const canEditStatus = !isTeamTask && (isCoordinator || isLeader || isOwner || (isTeamTask && currentUser.teamId === initialTask?.targetTeamId));
  const canNudge = (isLeader || isCoordinator) && !isOwner && initialTask;

  const teamMembers = users.filter(u => u.teamId === assigneeId);
  const totalTeamMembers = teamMembers.length;
  const doneTeamMembers = teamMembers.filter(u => teamProgress[u.id] === 'DONE').length;
  const progressPercent = totalTeamMembers > 0 ? Math.round((doneTeamMembers / totalTeamMembers) * 100) : 0;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in duration-200 max-h-[95vh] flex flex-col">

        {/* Header */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 flex justify-between items-center shrink-0">
          <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
            {initialTask ? 'Detalhes da Demanda' : 'Nova Demanda'}
            {isNudged && <span className="bg-red-100 text-red-600 text-[10px] px-2 py-0.5 rounded-full border border-red-200 animate-pulse">URGENTE / COBRADO</span>}
          </h2>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 space-y-5 overflow-y-auto custom-scrollbar">

          {!canEditDetails && (
             <div className="bg-blue-50 border border-blue-200 text-blue-800 p-3 rounded-lg text-sm flex items-start gap-2">
                <AlertCircle size={16} className="mt-0.5" />
                <div>Visualizando demanda de outro membro.</div>
             </div>
          )}

          {pendingNudge && (
             <div className="bg-amber-50 border border-amber-200 text-amber-800 p-3 rounded-lg text-sm flex items-start gap-2 animate-in slide-in-from-top-2">
                <Megaphone size={16} className="mt-0.5" />
                <div><strong>Cobrança registrada!</strong> Clique em Salvar para confirmar.</div>
             </div>
          )}

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Título</label>
            <input
              type="text"
              disabled={!canEditDetails}
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 disabled:text-slate-500"
              placeholder="Ex: Entregar relatório de vendas"
            />
          </div>

          {/* Date & Recurrence Row */}
          <div className="grid grid-cols-2 gap-3">
             <div className="col-span-2 md:col-span-1">
                <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                    <CalendarIcon size={14} /> Data Início
                </label>
                <input
                    type="date"
                    disabled={!canEditDetails}
                    value={dateStr}
                    onChange={(e) => setDateStr(e.target.value)}
                    className="w-full px-2 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 text-sm"
                />
             </div>

             {/* Only show recurrence for new tasks */}
             {!initialTask && (
                 <div className="col-span-2 md:col-span-1">
                    <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                        <Repeat size={14} /> Periodicidade
                    </label>
                    <select
                        value={recurrenceType}
                        onChange={e => setRecurrenceType(e.target.value as any)}
                        className="w-full px-2 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 text-sm"
                    >
                        <option value="NONE">Única vez</option>
                        <option value="DAILY">Diária (Todos os dias)</option>
                        <option value="WEEKLY">Semanal (Toda semana)</option>
                        <option value="MONTHLY">Mensal (Todo mês)</option>
                    </select>
                 </div>
             )}
          </div>

          {recurrenceType !== 'NONE' && !initialTask && (
             <div className="bg-indigo-50 p-3 rounded-lg border border-indigo-100">
                <label className="block text-xs font-bold text-indigo-700 mb-1">Repetir até a data:</label>
                <input
                    type="date"
                    value={recurrenceEndDate}
                    onChange={e => setRecurrenceEndDate(e.target.value)}
                    className="w-full px-2 py-2 border border-indigo-200 rounded text-sm focus:ring-2 focus:ring-indigo-500"
                />
                <p className="text-[10px] text-indigo-500 mt-1">
                   Serão criadas múltiplas demandas individuais.
                </p>
             </div>
          )}

          <div className="grid grid-cols-2 gap-3">
             <div>
               <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                 <Clock size={14} /> Início
               </label>
               <input
                 type="time"
                 disabled={!canEditDetails}
                 value={startTime}
                 onChange={(e) => setStartTime(e.target.value)}
                 className="w-full px-2 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 text-sm"
               />
             </div>
             <div>
               <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                 <Clock size={14} /> Fim
               </label>
               <input
                 type="time"
                 disabled={!canEditDetails}
                 value={endTime}
                 onChange={(e) => setEndTime(e.target.value)}
                 className="w-full px-2 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 text-sm"
               />
             </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
             {/* Assignee */}
             <div>
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <UserIcon size={14} /> Responsável
              </label>
              <div className="relative">
                <select
                  disabled={!canEditDetails} 
                  value={assigneeId}
                  onChange={(e) => {
                     setAssigneeId(e.target.value);
                     const u = users.find(u => u.id === e.target.value);
                     if(u) setTargetTeamId(u.teamId);
                     else {
                        const t = teams.find(team => team.id === e.target.value);
                        if(t) setTargetTeamId(t.id);
                     }
                  }}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 appearance-none disabled:bg-slate-100 disabled:text-slate-500 text-sm"
                >
                  {teams.map(team => {
                    const teamMembers = users.filter(u => u.teamId === team.id);
                    return (
                      <optgroup key={team.id} label={team.name}>
                        <option value={team.id} className="font-bold">📣 TODA A EQUIPE</option>
                        {teamMembers.map((user) => (
                          <option key={user.id} value={user.id}>{user.name}</option>
                        ))}
                      </optgroup>
                    );
                  })}
                  <optgroup label="Sem Setor">
                    {users.filter(u => !u.teamId).map(user => (
                       <option key={user.id} value={user.id}>{user.name}</option>
                    ))}
                  </optgroup>
                </select>
                <div className="absolute right-3 top-2.5 pointer-events-none text-slate-400">
                  <UserIcon size={16} />
                </div>
              </div>
            </div>

            {/* Target Team */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <Flag size={14} /> Equipe
              </label>
              <select
                disabled={!canEditDetails}
                value={targetTeamId}
                onChange={(e) => setTargetTeamId(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100"
              >
                 <option value="" disabled>Selecione...</option>
                 {teams.map(t => (
                   <option key={t.id} value={t.id}>{t.name}</option>
                 ))}
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                <Flag size={14} /> Prioridade
              </label>
              <select
                disabled={!canEditDetails}
                value={priority}
                onChange={(e) => setPriority(e.target.value as Priority)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100"
              >
                <option value="LOW">Baixa</option>
                <option value="MEDIUM">Média</option>
                <option value="HIGH">Alta</option>
              </select>
            </div>

            <div>
               <label className="block text-sm font-medium text-slate-700 mb-1 flex items-center gap-1">
                 <CheckCircle2 size={14} /> Status Global
               </label>
               {isTeamTask ? (
                 <div className="w-full px-3 py-2 border border-slate-200 bg-slate-50 rounded-lg flex items-center justify-between">
                    <span className="text-sm font-bold text-indigo-700">{progressPercent}%</span>
                    <div className="w-16 h-2 bg-slate-200 rounded-full overflow-hidden">
                       <div className="bg-indigo-600 h-full" style={{ width: `${progressPercent}%` }}></div>
                    </div>
                 </div>
               ) : (
                 <select
                   disabled={!canEditStatus}
                   value={status}
                   onChange={(e) => setStatus(e.target.value as TaskStatus)}
                   className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100"
                 >
                   {Object.keys(STATUS_LABELS).map((s) => (
                      <option key={s} value={s}>{STATUS_LABELS[s as TaskStatus]}</option>
                   ))}
                 </select>
               )}
            </div>
          </div>

          {/* Team Progress Breakdown */}
          {isTeamTask && (
             <div className="bg-slate-50 p-4 rounded-lg border border-slate-200">
                <h4 className="text-sm font-bold text-slate-700 mb-3 flex items-center gap-2">
                   <ListChecks size={16} /> Progresso Individual
                </h4>
                <div className="space-y-2 max-h-40 overflow-y-auto custom-scrollbar">
                   {teamMembers.map(member => {
                      const memberStatus = teamProgress[member.id] || 'TODO';
                      const isMe = member.id === currentUser.id;
                      return (
                        <div key={member.id} className="flex items-center justify-between p-2 bg-white rounded border border-slate-100">
                           <div className="flex items-center gap-2">
                              <img src={member.avatar} className="w-6 h-6 rounded-full" alt=""/>
                              <span className={`text-sm ${isMe ? 'font-bold text-indigo-700' : 'text-slate-600'}`}>
                                {member.name} {isMe && '(Você)'}
                              </span>
                           </div>
                           {isMe ? (
                              <select 
                                value={memberStatus}
                                onChange={(e) => handleToggleMyTeamStatus(e.target.value as TaskStatus)}
                                className="text-xs border-slate-300 rounded px-2 py-1 bg-indigo-50 border-indigo-200 text-indigo-800 font-bold focus:ring-indigo-500"
                              >
                                 <option value="TODO">Pendente</option>
                                 <option value="IN_PROGRESS">Fazendo</option>
                                 <option value="DONE">Concluído</option>
                              </select>
                           ) : (
                             <span className={`text-xs px-2 py-1 rounded font-medium ${
                                memberStatus === 'DONE' ? 'bg-emerald-100 text-emerald-700' : 
                                memberStatus === 'IN_PROGRESS' ? 'bg-amber-100 text-amber-700' : 
                                'bg-slate-100 text-slate-500'
                             }`}>
                                {STATUS_LABELS[memberStatus]}
                             </span>
                           )}
                        </div>
                      )
                   })}
                </div>
             </div>
          )}

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Descrição</label>
            <textarea
              disabled={!canEditDetails}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
              className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 disabled:bg-slate-100 resize-none text-sm"
              placeholder="Detalhes adicionais..."
            />
          </div>

        </div>

        {/* Footer */}
        <div className="bg-slate-50 border-t border-slate-100 px-6 py-4 flex justify-between items-center shrink-0">
           <div className="flex gap-2">
             {initialTask && (isLeader || isCoordinator) && (
                <button
                  onClick={() => {
                    if (onDelete && initialTask) onDelete(initialTask.id);
                    onClose();
                  }}
                  className="px-3 py-2 text-sm font-medium text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                >
                  Excluir
                </button>
             )}

             {canNudge && !isNudged && (
                <button
                  onClick={handleNudge}
                  disabled={pendingNudge}
                  className="px-3 py-2 text-sm font-medium text-amber-700 bg-amber-50 hover:bg-amber-100 border border-amber-200 rounded-lg transition-colors flex items-center gap-1 disabled:opacity-50"
                  title="Atualizará prioridade para Alta e adicionará flag de Cobrança. Requer salvar."
                >
                  <Megaphone size={14} /> {pendingNudge ? 'Pendente' : 'Cobrar'}
                </button>
             )}

             {!isOwner && !isTeamTask && initialTask && (
               <button
                 onClick={handleClaimTask}
                 className="px-3 py-2 text-sm font-medium text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
               >
                 Assumir
               </button>
             )}
           </div>

           <div className="flex gap-3">
             <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-200 rounded-lg transition-colors">
               Cancelar
             </button>
             <button
               onClick={handleSave}
               className="px-4 py-2 text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-md shadow-indigo-200 transition-all hover:scale-105"
             >
               Salvar
             </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default TaskModal;

import React, { useState } from 'react';
import { X, Plus, Trash2, StickyNote, Save } from 'lucide-react';
import { Note, User } from '../types';
import { format } from 'date-fns';

interface NotesModalProps {
  isOpen: boolean;
  onClose: () => void;
  notes: Note[];
  currentUser: User;
  onSaveNote: (note: Note) => void;
  onDeleteNote: (id: string) => void;
}

const NotesModal: React.FC<NotesModalProps> = ({ isOpen, onClose, notes, currentUser, onSaveNote, onDeleteNote }) => {
  const [currentNoteText, setCurrentNoteText] = useState('');
  const userNotes = notes.filter(n => n.userId === currentUser.id).sort((a,b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());

  if (!isOpen) return null;

  const handleAddNote = () => {
     if (!currentNoteText.trim()) return;
     const newNote: Note = {
        id: crypto.randomUUID(),
        userId: currentUser.id,
        content: currentNoteText,
        updatedAt: new Date()
     };
     onSaveNote(newNote);
     setCurrentNoteText('');
  };

  return (
    <div className="fixed inset-y-0 left-0 z-50 w-80 bg-white shadow-2xl border-r border-slate-200 flex flex-col animate-in slide-in-from-left duration-300">
       <div className="bg-amber-100 border-b border-amber-200 px-4 py-4 flex justify-between items-center shrink-0">
          <h2 className="text-lg font-bold text-amber-900 flex items-center gap-2">
             <StickyNote size={20} className="text-amber-600" /> Minhas Anotações
          </h2>
          <button onClick={onClose} className="text-amber-800 hover:bg-amber-200 p-1 rounded">
             <X size={20} />
          </button>
       </div>

       {/* Add New Note */}
       <div className="p-4 bg-amber-50 border-b border-amber-100">
          <textarea 
             value={currentNoteText}
             onChange={e => setCurrentNoteText(e.target.value)}
             placeholder="Digite um lembrete rápido..."
             className="w-full p-2 text-sm border border-amber-200 rounded-lg bg-white focus:ring-2 focus:ring-amber-400 min-h-[80px] resize-none mb-2"
          />
          <button 
             onClick={handleAddNote}
             disabled={!currentNoteText.trim()}
             className="w-full bg-amber-500 hover:bg-amber-600 text-white text-sm font-medium py-1.5 rounded-lg flex items-center justify-center gap-2 transition-colors disabled:opacity-50"
          >
             <Plus size={16} /> Adicionar Lembrete
          </button>
       </div>

       {/* List */}
       <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50 custom-scrollbar">
           {userNotes.length === 0 && (
              <div className="text-center text-slate-400 text-sm mt-10">
                 Nenhuma anotação.
              </div>
           )}
           {userNotes.map(note => (
              <div key={note.id} className="bg-yellow-50 border border-yellow-200 p-3 rounded-lg shadow-sm relative group hover:shadow-md transition-all">
                 <p className="text-sm text-slate-800 whitespace-pre-wrap">{note.content}</p>
                 <div className="mt-2 flex justify-between items-center border-t border-yellow-100 pt-2">
                    <span className="text-[10px] text-slate-400">
                       {format(new Date(note.updatedAt), 'dd/MM HH:mm')}
                    </span>
                    <button 
                       onClick={() => onDeleteNote(note.id)}
                       className="text-slate-400 hover:text-red-500 p-1 opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                       <Trash2 size={14} />
                    </button>
                 </div>
              </div>
           ))}
       </div>
    </div>
  );
};

export default NotesModal;

import React, { useState } from 'react';
import { 
  startOfMonth, endOfMonth, startOfWeek, endOfWeek, 
  eachDayOfInterval, isSameMonth, isSameDay, addMonths, subMonths, 
  format, isToday, isWithinInterval 
} from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { ChevronLeft, ChevronRight, Plus, AlertTriangle, Users, X, Clock } from 'lucide-react';
import { Task, User, normalizeDate, AlertPeriod, ALERT_COLOR_MAP, Team } from '../types';
import { STATUS_COLORS, STATUS_LABELS } from '../constants';

interface CalendarProps {
  tasks: Task[];
  users: User[];
  teams: Team[];
  alertPeriods: AlertPeriod[];
  currentUser: User;
  onAddTask: (date: Date) => void;
  onEditTask: (task: Task) => void;
}

const Calendar: React.FC<CalendarProps> = ({ tasks, users, teams, alertPeriods, currentUser, onAddTask, onEditTask }) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [expandedDay, setExpandedDay] = useState<Date | null>(null);

  const firstDayOfMonth = startOfMonth(currentDate);
  const lastDayOfMonth = endOfMonth(currentDate);
  const startDate = startOfWeek(firstDayOfMonth); 
  const endDate = endOfWeek(lastDayOfMonth);

  const days = eachDayOfInterval({ start: startDate, end: endDate });

  const nextMonth = () => setCurrentDate(addMonths(currentDate, 1));
  const prevMonth = () => setCurrentDate(subMonths(currentDate, 1));
  const goToToday = () => setCurrentDate(new Date());

  const getTasksForDay = (date: Date) => {
    return tasks
      .filter(task => isSameDay(normalizeDate(task.date), normalizeDate(date)))
      .sort((a, b) => (a.startTime || '').localeCompare(b.startTime || ''));
  };

  // Allow multiple alerts per day
  const getAlertsForDay = (date: Date) => {
    return alertPeriods.filter(period => 
      isWithinInterval(normalizeDate(date), { 
        start: normalizeDate(period.startDate), 
        end: normalizeDate(period.endDate) 
      })
    );
  };

  const DayExpandedModal = () => {
    if (!expandedDay) return null;
    const dayTasks = getTasksForDay(expandedDay);
    const dayAlerts = getAlertsForDay(expandedDay);

    return (
      <div className="absolute inset-0 z-40 bg-white/95 backdrop-blur-sm flex flex-col p-6 animate-in fade-in zoom-in duration-200">
         <div className="flex justify-between items-center mb-6 border-b border-slate-200 pb-4">
             <div>
                <h2 className="text-3xl font-bold text-slate-800 capitalize">
                    {format(expandedDay, "EEEE, d 'de' MMMM", { locale: ptBR })}
                </h2>
                {isToday(expandedDay) && <span className="text-sm font-bold text-indigo-600 uppercase">Hoje</span>}
             </div>
             <div className="flex gap-3">
                 <button 
                   onClick={() => onAddTask(expandedDay)}
                   className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg font-medium transition-colors shadow-lg"
                 >
                    <Plus size={18} /> Nova Demanda
                 </button>
                 <button 
                   onClick={() => setExpandedDay(null)}
                   className="bg-slate-100 hover:bg-slate-200 text-slate-600 p-2 rounded-lg transition-colors"
                 >
                    <X size={24} />
                 </button>
             </div>
         </div>

         <div className="flex-1 overflow-y-auto custom-scrollbar">
             {/* Alerts Section in Expanded View */}
             {dayAlerts.length > 0 && (
                <div className="mb-6 flex flex-wrap gap-2">
                   {dayAlerts.map(alert => (
                      <div key={alert.id} className={`${ALERT_COLOR_MAP[alert.color].bg} ${ALERT_COLOR_MAP[alert.color].text} border ${ALERT_COLOR_MAP[alert.color].border} px-3 py-1.5 rounded-full text-sm font-bold flex items-center gap-2`}>
                         <AlertTriangle size={16} /> {alert.label}
                      </div>
                   ))}
                </div>
             )}

             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                 {dayTasks.length === 0 && (
                    <div className="col-span-full text-center text-slate-400 py-12 text-lg">
                       Nenhuma demanda agendada para este dia.
                    </div>
                 )}
                 {dayTasks.map(task => {
                    const assignee = users.find(u => u.id === task.assigneeId);
                    const assignedTeam = !assignee ? teams.find(t => t.id === task.assigneeId) : null;
                    let progressPercent = 0;
                    if (assignedTeam) {
                        const teamMembers = users.filter(u => u.teamId === assignedTeam.id);
                        const doneCount = teamMembers.filter(u => task.teamProgress?.[u.id] === 'DONE').length;
                        progressPercent = teamMembers.length > 0 ? Math.round((doneCount / teamMembers.length) * 100) : 0;
                    }

                    return (
                       <div 
                         key={task.id}
                         onClick={() => onEditTask(task)}
                         className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm hover:shadow-md hover:border-indigo-300 transition-all cursor-pointer group"
                       >
                           <div className="flex justify-between items-start mb-2">
                               <div className="flex items-center gap-1.5 text-sm font-semibold text-slate-500 bg-slate-50 px-2 py-1 rounded">
                                   <Clock size={14} />
                                   {task.startTime || '--:--'} - {task.endTime || '--:--'}
                               </div>
                               <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold border ${STATUS_COLORS[task.status]}`}>
                                   {STATUS_LABELS[task.status]}
                               </span>
                           </div>

                           <h3 className="text-base font-bold text-slate-800 mb-2 group-hover:text-indigo-700 transition-colors">
                             {task.title}
                           </h3>

                           {assignedTeam ? (
                              <div className="mt-3">
                                 <div className="flex justify-between text-xs text-slate-500 mb-1">
                                    <span>Equipe: {assignedTeam.name}</span>
                                    <span>{progressPercent}%</span>
                                 </div>
                                 <div className="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
                                     <div className="bg-indigo-500 h-full" style={{ width: `${progressPercent}%` }}></div>
                                 </div>
                              </div>
                           ) : assignee && (
                              <div className="flex items-center gap-2 mt-3 pt-3 border-t border-slate-50">
                                 <img src={assignee.avatar} className="w-6 h-6 rounded-full" alt=""/>
                                 <span className="text-sm text-slate-600">{assignee.name}</span>
                              </div>
                           )}
                       </div>
                    )
                 })}
             </div>
         </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden relative">

      {/* Expanded Modal Overlay */}
      <DayExpandedModal />

      {/* Calendar Header */}
      <div className="flex-none flex items-center justify-between px-6 py-4 border-b border-slate-100 bg-white z-10">
        <div className="flex items-center gap-4">
          <h2 className="text-2xl font-bold text-slate-800 capitalize">
            {format(currentDate, 'MMMM yyyy', { locale: ptBR })}
          </h2>
          <div className="flex items-center bg-slate-100 rounded-lg p-1">
            <button onClick={prevMonth} className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-slate-600">
              <ChevronLeft size={20} />
            </button>
            <button onClick={nextMonth} className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-slate-600">
              <ChevronRight size={20} />
            </button>
          </div>
        </div>

        <button 
          onClick={goToToday}
          className="px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-200 hover:bg-slate-50 hover:border-slate-300 rounded-lg transition-colors"
        >
          Hoje
        </button>
      </div>

      {/* Days of Week Header */}
      <div className="flex-none grid grid-cols-7 border-b border-slate-100 bg-slate-50">
        {['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'].map((day) => (
          <div key={day} className="py-3 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">
            {day}
          </div>
        ))}
      </div>

      {/* Calendar Grid - Scrollable Area */}
      <div className="flex-1 overflow-y-auto custom-scrollbar">
        <div className="grid grid-cols-7 min-h-full auto-rows-[minmax(120px,1fr)] bg-slate-100 gap-[1px]">
          {days.map((day) => {
            const dayTasks = getTasksForDay(day);
            const isCurrentMonth = isSameMonth(day, currentDate);
            const isDayToday = isToday(day);
            const dayAlerts = getAlertsForDay(day);

            return (
              <div 
                key={day.toISOString()} 
                onClick={() => setExpandedDay(day)}
                className={`
                  relative flex flex-col p-1 transition-colors min-h-[140px] cursor-pointer hover:bg-slate-50
                  ${!isCurrentMonth ? 'bg-slate-50/50' : 'bg-white'}
                `}
              >
                {/* Multi-Alert Stack Header */}
                <div className="flex flex-col gap-[2px] w-full mb-1">
                    {dayAlerts.map(alert => (
                        <div key={alert.id} className={`h-1.5 w-full rounded-full ${ALERT_COLOR_MAP[alert.color].bar}`} title={alert.label}></div>
                    ))}
                </div>

                {/* Day Number */}
                <div className="flex justify-between items-center px-1">
                  <span className={`
                    text-sm font-medium w-6 h-6 flex items-center justify-center rounded-full
                    ${isDayToday 
                      ? 'bg-indigo-600 text-white' 
                      : isCurrentMonth ? 'text-slate-700' : 'text-slate-400'}
                  `}>
                    {format(day, 'd')}
                  </span>

                  {/* Alert Icons Mini */}
                  {dayAlerts.length > 0 && (
                      <div className="flex gap-0.5">
                         {dayAlerts.slice(0, 3).map(alert => (
                            <AlertTriangle key={alert.id} size={10} className={ALERT_COLOR_MAP[alert.color].icon} />
                         ))}
                      </div>
                  )}
                </div>

                {/* Tasks List */}
                <div className="flex flex-col gap-1 mt-1 overflow-hidden">
                  {dayTasks.slice(0, 4).map(task => {
                    const assignee = users.find(u => u.id === task.assigneeId);
                    const assignedTeam = !assignee ? teams.find(t => t.id === task.assigneeId) : null;

                    return (
                      <div
                        key={task.id}
                        className={`
                          text-left text-[9px] px-1 py-0.5 rounded border truncate relative
                          ${!assignedTeam ? STATUS_COLORS[task.status] : 'bg-white border-slate-200 text-slate-700'}
                        `}
                      >
                         <span className="font-semibold">{task.startTime}</span> {task.title}
                      </div>
                    );
                  })}
                  {dayTasks.length > 4 && (
                      <div className="text-[9px] text-slate-400 text-center font-medium">+ {dayTasks.length - 4} mais</div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Calendar;

import React, { useState, useEffect, useRef } from 'react';
import Calendar from './components/Calendar';
import TaskModal from './components/TaskModal';
import TaskListView from './components/TaskListView';
import TeamModal from './components/TeamModal';
import AlertModal from './components/AlertModal';
import DashboardView from './components/DashboardView';
import PresencialModal from './components/PresencialModal';
import UserAuthModal from './components/UserAuthModal'; 
import LoginScreen from './components/LoginScreen';
import NotesModal from './components/NotesModal';

import { User, Task, AlertPeriod, Team, Notification, TaskStatus, Note } from './types';
import { USERS, INITIAL_TASKS, INITIAL_TEAMS } from './constants';
import { api, getApiUrl } from './services/api';
import { Layout, CheckSquare, List, Calendar as CalendarIcon, Settings, PieChart, MapPin, AlertTriangle, Users, Database, Loader2, Filter, KeyRound, Bell, LogOut, RefreshCw, StickyNote } from 'lucide-react';
import { format, isValid } from 'date-fns';

const App: React.FC = () => {
  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<User>(USERS[0]); 

  // Data State
  const [isSyncing, setIsSyncing] = useState(false);
  const [isLoadingInitial, setIsLoadingInitial] = useState(true);
  const [connectionStatus, setConnectionStatus] = useState<'DISCONNECTED' | 'CONNECTED' | 'ERROR'>('DISCONNECTED');

  const [tasks, setTasks] = useState<Task[]>([]);
  const [teamUsers, setTeamUsers] = useState<User[]>([]);
  const [teams, setTeams] = useState<Team[]>([]);
  const [alertPeriods, setAlertPeriods] = useState<AlertPeriod[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [notes, setNotes] = useState<Note[]>([]); // New State for Notes

  const [viewMode, setViewMode] = useState<'CALENDAR' | 'LIST' | 'DASHBOARD'>('CALENDAR');
  const [filterScope, setFilterScope] = useState<string>('MY_TEAM'); 
  const [filterStatus, setFilterStatus] = useState<TaskStatus | 'ALL'>('ALL'); 

  // Modals State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [isAlertModalOpen, setIsAlertModalOpen] = useState(false);
  const [isPresencialModalOpen, setIsPresencialModalOpen] = useState(false);
  const [isUserSwitcherOpen, setIsUserSwitcherOpen] = useState(false);
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const [isNotesOpen, setIsNotesOpen] = useState(false); // New Notes Modal

  // Auth Modal State
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authTargetUser, setAuthTargetUser] = useState<User | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'CHANGE_PASSWORD'>('LOGIN');

  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  // Refs
  const userSwitcherRef = useRef<HTMLDivElement>(null);
  const notificationRef = useRef<HTMLDivElement>(null);
  const tasksRef = useRef<Task[]>([]);
  const currentUserRef = useRef<User>(currentUser);
  const isFirstLoadRef = useRef(true);

  // Keep refs synced
  useEffect(() => { tasksRef.current = tasks; }, [tasks]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);

  // --- CLICK OUTSIDE HANDLER ---
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (userSwitcherRef.current && !userSwitcherRef.current.contains(event.target as Node)) {
        setIsUserSwitcherOpen(false);
      }
      if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // --- API & SYNC LOGIC ---
  const fetchData = async (): Promise<boolean> => {
    if (!getApiUrl()) {
        setTasks(INITIAL_TASKS);
        setTeamUsers(USERS);
        setTeams(INITIAL_TEAMS);
        setIsLoadingInitial(false);
        return false;
    }

    try {
      setIsSyncing(true);
      const data = await api.sync();

      // Parse Tasks
      const parsedTasks: Task[] = data.tasks.map((t: any) => {
        let dateObj;
        if (typeof t.date === 'string' && t.date.includes('-') && !t.date.includes('T')) {
           const [y, m, d] = t.date.split('-').map(Number);
           dateObj = new Date(y, m - 1, d);
        } else if (typeof t.date === 'string') {
           const datePart = t.date.substring(0, 10);
           if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
             const [y, m, d] = datePart.split('-').map(Number);
             dateObj = new Date(y, m - 1, d);
           } else {
             dateObj = new Date(t.date);
           }
        } else {
           dateObj = new Date(t.date);
        }

        const cleanTime = (val: any) => {
          if (!val) return '';
          const strVal = String(val);
          if (strVal.match(/^\d{1,2}:\d{2}$/)) return strVal;
          const d = new Date(strVal);
          if (isValid(d)) return format(d, 'HH:mm');
          return strVal;
        };

        let tp = t.teamProgress;
        if (typeof tp === 'string') {
          try { tp = JSON.parse(tp); } catch(e) { tp = {}; }
        }

        return { 
          ...t, 
          title: t.title || 'Sem título', 
          date: dateObj,
          startTime: cleanTime(t.startTime),
          endTime: cleanTime(t.endTime),
          teamProgress: tp || {}
        };
      });

      // Parse Alerts
      const parsedAlerts: AlertPeriod[] = data.alerts.map((a: any) => {
         let start, end;
         const parseD = (dStr: any) => {
             if (typeof dStr === 'string') {
                const datePart = dStr.substring(0, 10);
                if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
                   const [y, m, d] = datePart.split('-').map(Number);
                   return new Date(y, m - 1, d);
                } 
                return new Date(dStr);
             } 
             return new Date(dStr);
         };
         return { ...a, startDate: parseD(a.startDate), endDate: parseD(a.endDate) };
      });

      // Parse Users
      const parsedUsers: User[] = data.users.map((u: any) => ({
        ...u,
        presencialDates: Array.isArray(u.presencialDates) ? u.presencialDates : [],
        password: (u.password !== undefined && u.password !== null && u.password !== '') ? String(u.password) : undefined
      }));

      // Parse Notes
      const parsedNotes: Note[] = (data.notes || []).map((n: any) => ({
         ...n,
         updatedAt: new Date(n.updatedAt)
      }));

      const parsedTeams: Team[] = data.teams || [];

      updateNotifications(parsedTasks);
      isFirstLoadRef.current = false;
      setTasks(parsedTasks);
      setNotes(parsedNotes);

      if (parsedUsers.length > 0) setTeamUsers(parsedUsers);
      else setTeamUsers(USERS); 

      if (parsedTeams.length > 0) setTeams(parsedTeams);
      else setTeams(INITIAL_TEAMS);

      setAlertPeriods(parsedAlerts);
      setConnectionStatus('CONNECTED');
      setIsLoadingInitial(false);
      return true;
    } catch (error) {
      console.error("Sync Error", error);
      setConnectionStatus('ERROR');
      setIsLoadingInitial(false);
      return false;
    } finally {
      setIsSyncing(false);
    }
  };

  // Initial Fetch & Interval Update (2 Minutes)
  useEffect(() => {
    fetchData();
    const intervalId = setInterval(fetchData, 120000); // 2 minutes
    return () => clearInterval(intervalId);
  }, []); 

  // --- NOTIFICATION LOGIC ---
  const updateNotifications = (currentTasks: Task[]) => {
      setNotifications(prev => {
         const readIds = JSON.parse(localStorage.getItem('GEST_PRO_READ_NOTIFS') || '[]');
         const currentIds = new Set(prev.map(n => n.id));
         const incomingNotifications: Notification[] = [];
         const myId = currentUserRef.current.id;

         currentTasks.forEach(task => {
             if (task.isNudged) {
                 const notifId = `${task.id}_nudge`;
                 const isMyResponsibility = task.assigneeId === myId || (teams.some(t => t.id === task.assigneeId) && currentUserRef.current.teamId === task.assigneeId);

                 if (isMyResponsibility && !readIds.includes(notifId) && !currentIds.has(notifId)) {
                     const title = task.title && task.title.trim() !== '' ? task.title : 'Tarefa sem título';
                     incomingNotifications.push({
                        id: notifId,
                        targetUserId: myId,
                        message: `⚠️ URGENTE: A demanda "${title}" foi cobrada!`,
                        date: new Date(),
                        read: false,
                        type: 'NUDGE'
                     });
                     currentIds.add(notifId);
                 }
             }
         });

         if (!isFirstLoadRef.current && tasksRef.current.length > 0) {
            currentTasks.forEach(newTask => {
                const oldTask = tasksRef.current.find(t => t.id === newTask.id);
                if ((!oldTask || oldTask.assigneeId !== newTask.assigneeId)) {
                   const isAssignedToMe = newTask.assigneeId === myId;
                   const isAssignedToMyTeam = teams.some(t => t.id === newTask.assigneeId) && currentUserRef.current.teamId === newTask.assigneeId;

                   if (isAssignedToMe || isAssignedToMyTeam) {
                      const notifId = `assign_${newTask.id}_${newTask.assigneeId}`;
                      if (!currentIds.has(notifId) && !readIds.includes(notifId)) {
                          const title = newTask.title && newTask.title.trim() !== '' ? newTask.title : 'Tarefa sem título';
                          incomingNotifications.push({ 
                              id: notifId, 
                              targetUserId: myId,
                              message: isAssignedToMyTeam ? `Nova demanda para equipe: ${title}` : `Nova demanda atribuída: ${title}`, 
                              date: new Date(), 
                              read: false, 
                              type: 'TASK_ASSIGNED' 
                          });
                          currentIds.add(notifId);
                      }
                   }
                }
            });
         }
         if (incomingNotifications.length === 0) return prev;
         return [...incomingNotifications, ...prev];
      });
  };

  useEffect(() => {
    if (isAuthenticated) setFilterScope('MY_TEAM');
  }, [currentUser.id, isAuthenticated]);

  const handleMarkAsRead = () => {
     const currentRead = JSON.parse(localStorage.getItem('GEST_PRO_READ_NOTIFS') || '[]');
     const newIds = notifications.filter(n => n.targetUserId === currentUser.id).map(n => n.id);
     localStorage.setItem('GEST_PRO_READ_NOTIFS', JSON.stringify([...new Set([...currentRead, ...newIds])]));
     setNotifications(prev => prev.filter(n => n.targetUserId !== currentUser.id));
  };

  // --- HANDLERS ---
  const handleLoginClick = (user: User) => {
    setAuthTargetUser(user);
    setAuthMode('LOGIN');
    setIsAuthModalOpen(true);
  };

  const handleLoginSuccess = async (updatedUser?: User) => {
     if (updatedUser) {
        setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
        setCurrentUser(updatedUser);
        if (getApiUrl()) await api.saveUser(updatedUser);
     } else if (authTargetUser) {
        setCurrentUser(authTargetUser);
     }
     setIsAuthenticated(true);
     setAuthTargetUser(null);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setViewMode('CALENDAR');
    setIsUserSwitcherOpen(false);
  };

  const handleUserSwitchClick = (user: User) => {
    setAuthTargetUser(user);
    setAuthMode('LOGIN');
    setIsAuthModalOpen(true);
    setIsUserSwitcherOpen(false); 
  };

  const handleChangePasswordClick = () => {
    setAuthTargetUser(currentUser);
    setAuthMode('CHANGE_PASSWORD');
    setIsAuthModalOpen(true);
  };

  const handleAuthModalSuccess = async (updatedUser?: User) => {
    if (updatedUser) {
        setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
        setCurrentUser(updatedUser);
        if (getApiUrl()) await api.saveUser(updatedUser);
        if (authMode === 'CHANGE_PASSWORD') alert("Senha alterada com sucesso!");
    } else if (authTargetUser) {
       setCurrentUser(authTargetUser);
       setIsAuthenticated(true); 
    }
  };


  // --- DATA HANDLERS ---
  const handleAddTask = (date: Date) => { setSelectedDate(date); setSelectedTask(null); setIsModalOpen(true); };
  const handleEditTask = (task: Task) => { setSelectedTask(task); setSelectedDate(task.date); setIsModalOpen(true); };

  // Updated to support Batch saving (recurrence)
  const handleSaveTask = async (taskOrTasks: Task | Task[]) => {
    if (Array.isArray(taskOrTasks)) {
        // Batch
        const newTasks = taskOrTasks;
        setTasks(prev => [...prev, ...newTasks]);
        if (getApiUrl()) { await api.saveTasksBatch(newTasks); fetchData(); }
    } else {
        // Single
        const safeTask = { 
           ...taskOrTasks, 
           title: taskOrTasks.title || 'Sem título',
           teamProgress: taskOrTasks.teamProgress || {} 
        };
        setTasks(prev => {
          const exists = prev.find(t => t.id === safeTask.id);
          return exists ? prev.map(t => t.id === safeTask.id ? safeTask : t) : [...prev, safeTask];
        });
        if (getApiUrl()) { await api.saveTask(safeTask); fetchData(); }
    }
  };

  const handleDeleteTask = async (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
    if (getApiUrl()) { await api.deleteTask(taskId); fetchData(); }
  };

  const handleAddUser = async (newUser: User) => {
    setTeamUsers(prev => [...prev, newUser]);
    if (getApiUrl()) { await api.saveUser(newUser); fetchData(); }
  };

  const handleEditUser = async (updatedUser: User) => {
    setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser.id === updatedUser.id) setCurrentUser(prev => ({...prev, ...updatedUser}));
    if (getApiUrl()) {
      const localUser = teamUsers.find(u => u.id === updatedUser.id);
      const userToSend = { ...updatedUser };
      if (localUser?.password && !userToSend.password) userToSend.password = localUser.password;
      await api.saveUser(userToSend);
      fetchData();
    }
  };

  const handleRemoveUser = async (userId: string) => {
    setTeamUsers(prev => prev.filter(u => u.id !== userId));
    if (getApiUrl()) { await api.deleteUser(userId); fetchData(); }
  };

  const handleAddTeam = async (newTeam: Team) => {
    setTeams(prev => [...prev, newTeam]);
    if (getApiUrl()) { await api.saveTeam(newTeam); fetchData(); }
  };

  const handleRemoveTeam = async (teamId: string) => {
    setTeams(prev => prev.filter(t => t.id !== teamId));
    if (getApiUrl()) { await api.deleteTeam(teamId); fetchData(); }
  };

  const handleSaveAlert = async (newAlert: AlertPeriod) => {
    setAlertPeriods(prev => {
       const exists = prev.find(a => a.id === newAlert.id);
       return exists ? prev.map(a => a.id === newAlert.id ? newAlert : a) : [...prev, newAlert];
    });
    if (getApiUrl()) { await api.saveAlert(newAlert); fetchData(); }
  };

  const handleDeleteAlert = async (alertId: string) => {
     setAlertPeriods(prev => prev.filter(a => a.id !== alertId));
     if (getApiUrl()) { await api.deleteAlert(alertId); fetchData(); }
