        setSwitcherTeamId(null); // Reset switcher state
      }
      if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // --- API & SYNC LOGIC ---
  const fetchData = async (): Promise<boolean> => {
    if (!getApiUrl()) {
        setTasks(INITIAL_TASKS);
        setTeamUsers(USERS);
        setTeams(INITIAL_TEAMS);
        setIsLoadingInitial(false);
        return false;
    }

    try {
      setIsSyncing(true);
      const data = await api.sync();

      // Parse Tasks
      const parsedTasks: Task[] = data.tasks.map((t: any) => {
        let dateObj;
        if (typeof t.date === 'string' && t.date.includes('-') && !t.date.includes('T')) {
           const [y, m, d] = t.date.split('-').map(Number);
           dateObj = new Date(y, m - 1, d);
        } else if (typeof t.date === 'string') {
           const datePart = t.date.substring(0, 10);
           if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
             const [y, m, d] = datePart.split('-').map(Number);
             dateObj = new Date(y, m - 1, d);
           } else {
             dateObj = new Date(t.date);
           }
        } else {
           dateObj = new Date(t.date);
        }

        const cleanTime = (val: any) => {
          if (!val) return '';
          const strVal = String(val);
          if (strVal.match(/^\d{1,2}:\d{2}$/)) return strVal;
          const d = new Date(strVal);
          if (isValid(d)) return format(d, 'HH:mm');
          return strVal;
        };

        let tp = t.teamProgress;
        if (typeof tp === 'string') {
          try { tp = JSON.parse(tp); } catch(e) { tp = {}; }
        }

        return { 
          ...t, 
          title: t.title || 'Sem título', 
          date: dateObj,
          startTime: cleanTime(t.startTime),
          endTime: cleanTime(t.endTime),
          teamProgress: tp || {}
        };
      });

      // Parse Alerts
      const parsedAlerts: AlertPeriod[] = data.alerts.map((a: any) => {
         let start, end;
         const parseD = (dStr: any) => {
             if (typeof dStr === 'string') {
                const datePart = dStr.substring(0, 10);
                if (datePart.match(/^\d{4}-\d{2}-\d{2}$/)) {
                   const [y, m, d] = datePart.split('-').map(Number);
                   return new Date(y, m - 1, d);
                } 
                return new Date(dStr);
             } 
             return new Date(dStr);
         };
         return { ...a, startDate: parseD(a.startDate), endDate: parseD(a.endDate) };
      });

      // Parse Users
      const parsedUsers: User[] = data.users.map((u: any) => ({
        ...u,
        presencialDates: Array.isArray(u.presencialDates) ? u.presencialDates : [],
        password: (u.password !== undefined && u.password !== null && u.password !== '') ? String(u.password) : undefined
      }));

      // Parse Notes
      const parsedNotes: Note[] = (data.notes || []).map((n: any) => ({
         ...n,
         updatedAt: new Date(n.updatedAt)
      }));

      const parsedTeams: Team[] = data.teams || [];

      updateNotifications(parsedTasks);
      isFirstLoadRef.current = false;
      setTasks(parsedTasks);
      setNotes(parsedNotes);

      if (parsedUsers.length > 0) setTeamUsers(parsedUsers);
      else setTeamUsers(USERS); 

      if (parsedTeams.length > 0) setTeams(parsedTeams);
      else setTeams(INITIAL_TEAMS);

      setAlertPeriods(parsedAlerts);
      setConnectionStatus('CONNECTED');
      setIsLoadingInitial(false);
      return true;
    } catch (error) {
      console.error("Sync Error", error);
      setConnectionStatus('ERROR');
      setIsLoadingInitial(false);
      return false;
    } finally {
      setIsSyncing(false);
    }
  };

  // Initial Fetch & Interval Update (2 Minutes)
  useEffect(() => {
    fetchData();
    const intervalId = setInterval(fetchData, 120000); // 2 minutes
    return () => clearInterval(intervalId);
  }, []); 

  // --- NOTIFICATION LOGIC ---
  const updateNotifications = (currentTasks: Task[]) => {
      setNotifications(prev => {
         const readIds = JSON.parse(localStorage.getItem('GEST_PRO_READ_NOTIFS') || '[]');
         const currentIds = new Set(prev.map(n => n.id));
         const incomingNotifications: Notification[] = [];
         const myId = currentUserRef.current.id;

         currentTasks.forEach(task => {
             if (task.isNudged) {
                 const notifId = `${task.id}_nudge`;
                 const isMyResponsibility = task.assigneeId === myId || (teams.some(t => t.id === task.assigneeId) && currentUserRef.current.teamId === task.assigneeId);

                 if (isMyResponsibility && !readIds.includes(notifId) && !currentIds.has(notifId)) {
                     const title = task.title && task.title.trim() !== '' ? task.title : 'Tarefa sem título';
                     incomingNotifications.push({
                        id: notifId,
                        targetUserId: myId,
                        message: `⚠️ URGENTE: A demanda "${title}" foi cobrada!`,
                        date: new Date(),
                        read: false,
                        type: 'NUDGE'
                     });
                     currentIds.add(notifId);
                 }
             }
         });

         if (!isFirstLoadRef.current && tasksRef.current.length > 0) {
            currentTasks.forEach(newTask => {
                const oldTask = tasksRef.current.find(t => t.id === newTask.id);
                if ((!oldTask || oldTask.assigneeId !== newTask.assigneeId)) {
                   const isAssignedToMe = newTask.assigneeId === myId;
                   const isAssignedToMyTeam = teams.some(t => t.id === newTask.assigneeId) && currentUserRef.current.teamId === newTask.assigneeId;

                   if (isAssignedToMe || isAssignedToMyTeam) {
                      const notifId = `assign_${newTask.id}_${newTask.assigneeId}`;
                      if (!currentIds.has(notifId) && !readIds.includes(notifId)) {
                          const title = newTask.title && newTask.title.trim() !== '' ? newTask.title : 'Tarefa sem título';
                          incomingNotifications.push({ 
                              id: notifId, 
                              targetUserId: myId,
                              message: isAssignedToMyTeam ? `Nova demanda para equipe: ${title}` : `Nova demanda atribuída: ${title}`, 
                              date: new Date(), 
                              read: false, 
                              type: 'TASK_ASSIGNED' 
                          });
                          currentIds.add(notifId);
                      }
                   }
                }
            });
         }
         if (incomingNotifications.length === 0) return prev;
         return [...incomingNotifications, ...prev];
      });
  };

  useEffect(() => {
    if (isAuthenticated) setFilterScope('MY_TEAM');
  }, [currentUser.id, isAuthenticated]);

  const handleMarkAsRead = () => {
     const currentRead = JSON.parse(localStorage.getItem('GEST_PRO_READ_NOTIFS') || '[]');
     const newIds = notifications.filter(n => n.targetUserId === currentUser.id).map(n => n.id);
     localStorage.setItem('GEST_PRO_READ_NOTIFS', JSON.stringify([...new Set([...currentRead, ...newIds])]));
     setNotifications(prev => prev.filter(n => n.targetUserId !== currentUser.id));
  };

  // --- HANDLERS ---
  const handleLoginClick = (user: User) => {
    setAuthTargetUser(user);
    setAuthMode('LOGIN');
    setIsAuthModalOpen(true);
  };

  const handleLoginSuccess = async (updatedUser?: User) => {
     if (updatedUser) {
        setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
        setCurrentUser(updatedUser);
        if (getApiUrl()) await api.saveUser(updatedUser);
     } else if (authTargetUser) {
        setCurrentUser(authTargetUser);
     }
     setIsAuthenticated(true);
     setAuthTargetUser(null);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setViewMode('CALENDAR');
    setIsUserSwitcherOpen(false);
    setSwitcherTeamId(null);
  };

  const handleUserSwitchClick = (user: User) => {
    setAuthTargetUser(user);
    setAuthMode('LOGIN');
    setIsAuthModalOpen(true);
    setIsUserSwitcherOpen(false); 
    setSwitcherTeamId(null);
  };

  const handleChangePasswordClick = () => {
    setAuthTargetUser(currentUser);
    setAuthMode('CHANGE_PASSWORD');
    setIsAuthModalOpen(true);
  };

  const handleAuthModalSuccess = async (updatedUser?: User) => {
    if (updatedUser) {
        setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
        setCurrentUser(updatedUser);
        if (getApiUrl()) await api.saveUser(updatedUser);
        if (authMode === 'CHANGE_PASSWORD') alert("Senha alterada com sucesso!");
    } else if (authTargetUser) {
       setCurrentUser(authTargetUser);
       setIsAuthenticated(true); 
    }
  };


  // --- DATA HANDLERS ---
  const handleAddTask = (date: Date) => { setSelectedDate(date); setSelectedTask(null); setIsModalOpen(true); };
  const handleEditTask = (task: Task) => { setSelectedTask(task); setSelectedDate(task.date); setIsModalOpen(true); };

  // Updated to support Batch saving (recurrence)
  const handleSaveTask = async (taskOrTasks: Task | Task[]) => {
    if (Array.isArray(taskOrTasks)) {
        // Batch
        const newTasks = taskOrTasks;
        setTasks(prev => [...prev, ...newTasks]);
        if (getApiUrl()) { await api.saveTasksBatch(newTasks); fetchData(); }
    } else {
        // Single
        const safeTask = { 
           ...taskOrTasks, 
           title: taskOrTasks.title || 'Sem título',
           teamProgress: taskOrTasks.teamProgress || {} 
        };
        setTasks(prev => {
          const exists = prev.find(t => t.id === safeTask.id);
          return exists ? prev.map(t => t.id === safeTask.id ? safeTask : t) : [...prev, safeTask];
        });
        if (getApiUrl()) { await api.saveTask(safeTask); fetchData(); }
    }
  };

  const handleDeleteTask = async (taskId: string) => {
    setTasks(prev => prev.filter(t => t.id !== taskId));
    if (getApiUrl()) { await api.deleteTask(taskId); fetchData(); }
  };

  const handleAddUser = async (newUser: User) => {
    setTeamUsers(prev => [...prev, newUser]);
    if (getApiUrl()) { await api.saveUser(newUser); fetchData(); }
  };

  const handleEditUser = async (updatedUser: User) => {
    setTeamUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser.id === updatedUser.id) setCurrentUser(prev => ({...prev, ...updatedUser}));
    if (getApiUrl()) {
      const localUser = teamUsers.find(u => u.id === updatedUser.id);
      const userToSend = { ...updatedUser };
      if (localUser?.password && !userToSend.password) userToSend.password = localUser.password;
      await api.saveUser(userToSend);
      fetchData();
    }
  };

  const handleRemoveUser = async (userId: string) => {
    setTeamUsers(prev => prev.filter(u => u.id !== userId));
    if (getApiUrl()) { await api.deleteUser(userId); fetchData(); }
  };

  const handleAddTeam = async (newTeam: Team) => {
    setTeams(prev => [...prev, newTeam]);
    if (getApiUrl()) { await api.saveTeam(newTeam); fetchData(); }
  };

  const handleRemoveTeam = async (teamId: string) => {
    setTeams(prev => prev.filter(t => t.id !== teamId));
    if (getApiUrl()) { await api.deleteTeam(teamId); fetchData(); }
  };

  const handleSaveAlert = async (newAlert: AlertPeriod) => {
    setAlertPeriods(prev => {
       const exists = prev.find(a => a.id === newAlert.id);
       return exists ? prev.map(a => a.id === newAlert.id ? newAlert : a) : [...prev, newAlert];
    });
    if (getApiUrl()) { await api.saveAlert(newAlert); fetchData(); }
  };

  const handleDeleteAlert = async (alertId: string) => {
     setAlertPeriods(prev => prev.filter(a => a.id !== alertId));
     if (getApiUrl()) { await api.deleteAlert(alertId); fetchData(); }
  };

  const handleSaveNote = async (newNote: Note) => {
      setNotes(prev => [newNote, ...prev]);
      if (getApiUrl()) { await api.saveNote(newNote); fetchData(); }
  };

  const handleDeleteNote = async (noteId: string) => {
      setNotes(prev => prev.filter(n => n.id !== noteId));
      if (getApiUrl()) { await api.deleteNote(noteId); fetchData(); }
  };

  const handleBatchUpdatePresence = async (updatedUsers: User[]) => {
     setTeamUsers(prev => prev.map(u => updatedUsers.find(upd => upd.id === u.id) || u));
     if (getApiUrl()) { await api.saveUsersBatch(updatedUsers); fetchData(); }
  };

  const isLeader = currentUser.role === 'LEADER' || currentUser.role === 'COORDINATOR';
  const isCoordinator = currentUser.role === 'COORDINATOR';

  const displayedTasks = tasks.filter(task => {
    const assigneeUser = teamUsers.find(u => u.id === task.assigneeId);
    const assigneeTeam = teams.find(t => t.id === task.assigneeId);

    let passesScope = false;

    if (filterScope === 'ME') {
        passesScope = task.assigneeId === currentUser.id || task.assigneeId === currentUser.teamId;
    }
    else if (filterScope === 'MY_TEAM') {
        if (assigneeUser) passesScope = assigneeUser.teamId === currentUser.teamId;
        else if (assigneeTeam) passesScope = assigneeTeam.id === currentUser.teamId;
        else passesScope = false; 
    }
    else if (filterScope === 'ALL_TEAMS') {
        passesScope = true;
    }
    else {
        if (assigneeUser) passesScope = assigneeUser.teamId === filterScope;
        else if (assigneeTeam) passesScope = assigneeTeam.id === filterScope;
    }

    if (!passesScope) return false;
    if (viewMode === 'LIST' && filterStatus !== 'ALL') if (task.status !== filterStatus) return false;
    return true;
  });

  // 1. Alert Filter Logic Updated
  const displayedAlerts = alertPeriods.filter(alert => {
     // Base check: Is this alert meant for 'ALL' or the user's team, or is user a coordinator?
     const isVisibleToUser = alert.targetTeamId === 'ALL' || alert.targetTeamId === currentUser.teamId || isCoordinator;

     if (!isVisibleToUser) return false;

     // Coordinator Filter Logic: 
     // If coordinator selects a specific team (filterScope is a Team ID), show only alerts for that team (or 'ALL')
     if (isCoordinator) {
        if (filterScope !== 'ALL_TEAMS' && filterScope !== 'MY_TEAM' && filterScope !== 'ME') {
            // filterScope is a Team ID
            return alert.targetTeamId === 'ALL' || alert.targetTeamId === filterScope;
        }
     }

     return true;
  });

  const myNotifications = notifications.filter(n => n.targetUserId === currentUser.id);
  const safeDate = (d: any) => (d instanceof Date && !isNaN(d.getTime())) ? d : (typeof d === 'string' ? new Date(d) : new Date());

  // --- RENDER ---

  if (!isAuthenticated) {
     return (
       <>
         <LoginScreen users={teamUsers} teams={teams} onLogin={handleLoginClick} isLoading={isLoadingInitial} />
         <UserAuthModal isOpen={isAuthModalOpen} onClose={() => setIsAuthModalOpen(false)} targetUser={authTargetUser} mode={authMode} onSuccess={handleLoginSuccess} />
       </>
     );
  }

  return (
    <div className="flex h-screen bg-slate-50 text-slate-900 font-sans overflow-hidden">

      {/* Sidebar */}
      <aside className="w-16 lg:w-72 bg-slate-900 text-slate-300 flex flex-col flex-shrink-0 shadow-xl z-20 transition-all">
        <div className="p-4 lg:p-6 border-b border-slate-800 flex items-center justify-center lg:justify-start gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg text-white shrink-0">
             <Layout size={24} />
          </div>
          <div className="hidden lg:flex flex-col">
             <h1 className="text-xl font-bold tracking-tight text-white leading-none mb-1">GestãoPRO</h1>
             <span className="text-[10px] text-slate-400 font-medium whitespace-nowrap">Organizador de Demandas</span>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          <button onClick={() => setViewMode('CALENDAR')} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'CALENDAR' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <CheckSquare size={20} />
            <span className="hidden lg:inline">Minhas Demandas</span>
          </button>

          <button onClick={() => { setViewMode('DASHBOARD'); setFilterStatus('ALL'); }} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${viewMode === 'DASHBOARD' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800 text-slate-400'}`}>
            <PieChart size={20} />
            <span className="hidden lg:inline">Indicadores</span>
          </button>

          <button onClick={() => setIsPresencialModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
            <MapPin size={20} />
            <span className="hidden lg:inline">Escala Presencial</span>
          </button>

          <button onClick={() => setIsNotesOpen(!isNotesOpen)} className={`w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors ${isNotesOpen ? 'bg-amber-100 text-amber-800' : 'hover:bg-slate-800 text-slate-400'}`}>
            <StickyNote size={20} />
            <span className="hidden lg:inline">Minhas Notas</span>
          </button>

          {isLeader && (
            <>
              <div className="my-2 border-t border-slate-800"></div>
              <button onClick={() => setIsTeamModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-slate-400">
                <Settings size={20} />
                <span className="hidden lg:inline">Gerenciar Equipe</span>
              </button>
              <button onClick={() => setIsAlertModalOpen(true)} className="w-full px-3 py-3 rounded-lg flex items-center justify-center lg:justify-start gap-3 font-medium transition-colors hover:bg-slate-800 text-orange-400">
                <AlertTriangle size={20} />
                <span className="hidden lg:inline">Criar Alerta</span>
              </button>
            </>
          )}
        </nav>

        <div className="p-2 bg-slate-950">
           <button 
             onClick={() => fetchData()}
             className="w-full flex items-center justify-center lg:justify-start gap-3 p-3 rounded-lg hover:bg-slate-800 transition-colors group cursor-pointer"
             title={connectionStatus === 'ERROR' ? 'Clique para reconectar' : 'Clique para atualizar'}
           >
              <div className="relative shrink-0">
                 <Database size={20} className="text-slate-400 group-hover:text-white transition-colors" />
                 <div className={`absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full border-2 border-slate-900 ${
                    connectionStatus === 'CONNECTED' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.6)]' : 
                    connectionStatus === 'ERROR' ? 'bg-red-500 animate-pulse' : 'bg-slate-600'
                 }`}></div>
              </div>
              <div className="hidden lg:flex flex-col items-start min-w-0">
                <span className={`text-sm font-medium truncate ${connectionStatus === 'ERROR' ? 'text-red-400' : 'text-slate-300'}`}>
                  {connectionStatus === 'CONNECTED' ? 'Conectado' : 'Desconectado'}
                </span>
                {connectionStatus === 'ERROR' && <span className="text-[10px] text-slate-500">Clique p/ reconectar</span>}
              </div>
              {isSyncing ? (
                 <Loader2 size={14} className="animate-spin ml-auto text-slate-500" />
              ) : (
                 <RefreshCw size={14} className={`ml-auto text-slate-500 opacity-0 group-hover:opacity-100 ${connectionStatus === 'ERROR' ? 'opacity-100 text-red-400' : ''}`} />
              )}
           </button>
        </div>

        <div className="relative border-t border-slate-800 bg-slate-950 p-2" ref={userSwitcherRef}>
           <button 
             onClick={() => {
                setIsUserSwitcherOpen(!isUserSwitcherOpen);
                setSwitcherTeamId(null);
             }}
             className="w-full flex items-center justify-center lg:justify-start gap-3 p-2 rounded hover:bg-slate-800 transition-colors"
           >
              <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center overflow-hidden">
                 <Users size={16} className="text-slate-300" />
              </div>
              <div className="hidden lg:block text-left">
                 <div className="text-xs font-bold text-slate-400">Alternar Usuário</div>
              </div>
           </button>

           {isUserSwitcherOpen && (
              <div className="absolute bottom-full left-2 w-64 bg-slate-800 border border-slate-700 rounded-lg shadow-xl mb-2 p-1 z-50 max-h-80 overflow-y-auto">

                 {/* 4. User Switcher Logic: Show Teams First, then Users */}
                 {!switcherTeamId ? (
                     <>
                        <div className="px-2 py-1 text-[10px] font-bold text-slate-500 uppercase">Selecione o Setor</div>
                        <button 
                             onClick={() => setSwitcherTeamId('ALL')}
                             className="w-full text-left px-2 py-2 text-sm text-slate-300 hover:bg-slate-700 rounded flex justify-between"
                        >
                            <span>Todos os Setores</span>
                            <ChevronRight size={14} />
                        </button>
                        {teams.map(team => (
                             <button
                                key={team.id}
                                onClick={() => setSwitcherTeamId(team.id)}
                                className="w-full text-left px-2 py-2 text-sm text-slate-300 hover:bg-slate-700 rounded flex justify-between"
                             >
                                 <span>{team.name}</span>
                                 <ChevronRight size={14} />
                             </button>
                        ))}
                     </>
                 ) : (
                     <>
                        <div className="flex items-center gap-2 px-2 py-1 border-b border-slate-700 mb-1">
                            <button onClick={() => setSwitcherTeamId(null)} className="text-slate-400 hover:text-white">
                                <ChevronLeft size={16} />
                            </button>
                            <span className="text-xs font-bold text-slate-300">
                                {switcherTeamId === 'ALL' ? 'Todos' : teams.find(t => t.id === switcherTeamId)?.name}
                            </span>
                        </div>
                        {teamUsers
                           .filter(u => switcherTeamId === 'ALL' || u.teamId === switcherTeamId)
                           .map(u => (
                            <button
                                key={u.id}
                                onClick={() => handleUserSwitchClick(u)}
                                className={`w-full flex items-center gap-2 p-2 rounded text-sm ${currentUser.id === u.id ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-700'}`}
                            >
                                <img src={u.avatar} className="w-6 h-6 rounded-full" alt=""/>
                                <span className="truncate">{u.name}</span>
                                {!u.password && <span className="ml-auto w-2 h-2 rounded-full bg-red-500" title="Sem senha"></span>}
                            </button>
                        ))}
                        {teamUsers.filter(u => switcherTeamId === 'ALL' || u.teamId === switcherTeamId).length === 0 && (
                            <div className="p-2 text-xs text-slate-500">Nenhum usuário.</div>
                        )}
                     </>
                 )}

                 <div className="border-t border-slate-700 mt-1 pt-1">
                    <button onClick={handleLogout} className="w-full flex items-center gap-2 p-2 text-red-400 hover:bg-slate-700 rounded text-sm">
                        <LogOut size={14} /> Sair do Sistema
                    </button>
                 </div>
              </div>
           )}
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shadow-sm z-10 gap-4">

          <div className="flex items-center gap-4">
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button onClick={() => setViewMode('CALENDAR')} className={`flex items-center gap-2 px-3 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${viewMode === 'CALENDAR' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}>
                <CalendarIcon size={16} /> <span className="hidden sm:inline">Calendário</span>
              </button>
              <button onClick={() => { setViewMode('LIST'); setFilterStatus('ALL'); }} className={`flex items-center gap-2 px-3 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${viewMode === 'LIST' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}>
                <List size={16} /> <span className="hidden sm:inline">Lista</span>
              </button>
            </div>
            <div className="h-6 w-px bg-slate-200 mx-2 hidden sm:block"></div>
            {(viewMode === 'CALENDAR' || viewMode === 'LIST' || viewMode === 'DASHBOARD') && (
               <div className="flex items-center gap-2">
                 <Filter size={16} className="text-slate-400" />
                 <select 
                   value={filterScope}
                   onChange={(e) => setFilterScope(e.target.value)}
                   className="bg-slate-50 border-none text-sm font-medium text-slate-700 rounded-md focus:ring-0 cursor-pointer hover:bg-slate-100 py-1.5 pl-2 pr-8"
                 >
                    <option value="ME">Apenas Minhas</option>
                    <option value="MY_TEAM">Minha Equipe</option>
                    {isCoordinator && (
                      <>
                        <option disabled>──────────</option>
                        <option value="ALL_TEAMS">Todas as Equipes</option>
                        {teams.map(team => <option key={team.id} value={team.id}>Equipe: {team.name}</option>)}
                      </>
                    )}
                 </select>
               </div>
            )}
          </div>

          <div className="flex items-center gap-6">
            <div className="relative" ref={notificationRef}>
              <button onClick={() => setIsNotificationsOpen(!isNotificationsOpen)} className="text-slate-400 hover:text-indigo-600 transition-colors relative">
                 <Bell size={20} />
                 {myNotifications.length > 0 && <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-bounce"></span>}
              </button>
              {isNotificationsOpen && (
                 <div className="absolute right-0 top-full mt-2 w-72 bg-white border border-slate-200 rounded-xl shadow-xl z-50 overflow-hidden">
                    <div className="bg-slate-50 px-4 py-2 border-b border-slate-100 text-xs font-bold text-slate-500">Notificações ({myNotifications.length})</div>
                    <div className="max-h-64 overflow-y-auto custom-scrollbar">
                       {myNotifications.length === 0 ? <div className="p-4 text-center text-xs text-slate-400">Nenhuma notificação nova.</div> : 
                        myNotifications.map(n => (
                           <div key={n.id} className="p-3 border-b border-slate-50 hover:bg-slate-50 transition-colors">
                              <p className={`text-sm mb-1 ${n.type === 'NUDGE' ? 'text-amber-700 font-bold' : 'text-slate-800'}`}>{n.message || 'Nova Notificação'}</p>
                              <span className="text-[10px] text-slate-400 font-medium">{format(safeDate(n.date), 'dd/MM HH:mm')}</span>
                           </div>
                         ))}
                    </div>
                    {myNotifications.length > 0 && <div className="bg-slate-50 p-2 text-center border-t border-slate-100"><button onClick={handleMarkAsRead} className="text-xs text-indigo-600 font-medium hover:underline">Marcar como lidas</button></div>}
                 </div>
              )}
            </div>

            <button onClick={handleChangePasswordClick} className="text-slate-400 hover:text-indigo-600 transition-colors" title="Alterar Senha">
               <KeyRound size={18} />
            </button>

            <div className="flex items-center gap-3 pl-6 border-l border-slate-200">
              <div className="text-right hidden sm:block">
                <div className="text-sm font-bold text-slate-800">{currentUser.name}</div>
                <div className="text-xs text-slate-500">
                   {currentUser.role === 'COORDINATOR' ? 'Coordenador' : currentUser.role === 'LEADER' ? 'Líder' : 'Membro'}
                </div>
              </div>
              <img src={currentUser.avatar} alt="User" className="w-9 h-9 rounded-full border border-slate-200 shadow-sm" />
            </div>
          </div>
        </header>

        <div className="flex-1 p-4 lg:p-6 overflow-hidden flex flex-col bg-slate-50 relative">

          {/* Notes Sidebar Modal */}
          <NotesModal 
             isOpen={isNotesOpen}
             onClose={() => setIsNotesOpen(false)}
             notes={notes}
             currentUser={currentUser}
             onSaveNote={handleSaveNote}
             onDeleteNote={handleDeleteNote}
          />

          <div className="flex-1 h-full min-h-0">
            {viewMode === 'CALENDAR' ? (
              <Calendar 
                tasks={displayedTasks} 
                users={teamUsers}
                teams={teams}
                alertPeriods={displayedAlerts}
                currentUser={currentUser}
                onAddTask={handleAddTask}
                onEditTask={handleEditTask}
              />
            ) : viewMode === 'LIST' ? (
              <TaskListView 
                tasks={displayedTasks}
                currentUser={currentUser}
                users={teamUsers}
                teams={teams}
                onEditTask={handleEditTask}
              />
            ) : (
              <DashboardView 
                tasks={displayedTasks} 
                users={teamUsers}
                onFilterRequest={(status) => {
                   setFilterStatus(status);
                   setViewMode('LIST');
                }}
              />
            )}
          </div>
        </div>
      </main>

      <UserAuthModal isOpen={isAuthModalOpen} onClose={() => setIsAuthModalOpen(false)} targetUser={authTargetUser} mode={authMode} onSuccess={handleAuthModalSuccess} />
      <TaskModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        onRequestTransfer={() => {}} 
        initialTask={selectedTask}
        selectedDate={selectedDate}
        currentUser={currentUser}
        users={teamUsers}
        teams={teams}
      />
      <TeamModal isOpen={isTeamModalOpen} onClose={() => setIsTeamModalOpen(false)} users={teamUsers} teams={teams} onAddUser={handleAddUser} onEditUser={handleEditUser} onRemoveUser={handleRemoveUser} onAddTeam={handleAddTeam} onRemoveTeam={handleRemoveTeam} />
      <AlertModal isOpen={isAlertModalOpen} onClose={() => setIsAlertModalOpen(false)} onSave={handleSaveAlert} onDelete={handleDeleteAlert} alertPeriods={alertPeriods} teams={teams} />
      <PresencialModal isOpen={isPresencialModalOpen} onClose={() => setIsPresencialModalOpen(false)} users={teamUsers} teams={teams} currentUser={currentUser} onSavePresence={handleBatchUpdatePresence} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { X, AlertTriangle, Check, Users, Trash2, Pencil } from 'lucide-react';
import { AlertPeriod, AlertColor, normalizeDate, ALERT_COLOR_MAP, Team } from '../types';
import { format } from 'date-fns';

interface AlertModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (alert: AlertPeriod) => void;
  onDelete?: (alertId: string) => void;
  teams: Team[];
  alertPeriods?: AlertPeriod[];
}

const AlertModal: React.FC<AlertModalProps> = ({ isOpen, onClose, onSave, onDelete, teams, alertPeriods = [] }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [label, setLabel] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [color, setColor] = useState<AlertColor>('ORANGE');
  const [targetTeamId, setTargetTeamId] = useState<string>('ALL');

  if (!isOpen) return null;

  // 2. Filter alerts: Only show active or future alerts (End date >= today)
  // We use normalizeDate to ignore time components.
  const today = normalizeDate(new Date());
  const activeAlerts = alertPeriods.filter(a => normalizeDate(a.endDate) >= today);

  const handleEdit = (alert: AlertPeriod) => {
     setEditingId(alert.id);
     setLabel(alert.label);
     setStartDate(format(alert.startDate, 'yyyy-MM-dd'));
     setEndDate(format(alert.endDate, 'yyyy-MM-dd'));
     setColor(alert.color);
     setTargetTeamId(alert.targetTeamId || 'ALL');
  };

  const resetForm = () => {
    setEditingId(null);
    setLabel('');
    setStartDate('');
    setEndDate('');
    setColor('ORANGE');
    setTargetTeamId('ALL');
  };

  const handleSave = () => {
    if (!label || !startDate || !endDate) return;

    const [sy, sm, sd] = startDate.split('-').map(Number);
    const [ey, em, ed] = endDate.split('-').map(Number);

    const newAlert: AlertPeriod = {
      id: editingId || crypto.randomUUID(),
      startDate: normalizeDate(new Date(sy, sm - 1, sd)),
      endDate: normalizeDate(new Date(ey, em - 1, ed)),
      label,
      color,
      targetTeamId
    };
    onSave(newAlert);

    resetForm();
    onClose(); 
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-200 flex flex-col max-h-[90vh]">
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 flex justify-between items-center shrink-0">
          <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
             <AlertTriangle size={20} className="text-orange-500" /> Gerenciar Alertas
          </h2>
          <button onClick={() => { onClose(); resetForm(); }} className="text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="p-6 space-y-4 overflow-y-auto custom-scrollbar">
           {/* Form Section */}
           <div className={`space-y-4 border-b border-slate-100 pb-6 rounded-lg p-2 ${editingId ? 'bg-indigo-50 border border-indigo-100' : ''}`}>
             <h3 className={`text-sm font-bold flex items-center gap-2 ${editingId ? 'text-indigo-700' : 'text-slate-700'}`}>
               {editingId ? <Pencil size={14} /> : <AlertTriangle size={14}/>}
               {editingId ? 'Editar Alerta' : 'Novo Alerta'}
             </h3>
             <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Motivo</label>
               <input 
                 type="text" 
                 value={label}
                 onChange={e => setLabel(e.target.value)}
                 placeholder="Ex: Fechamento, Escala de Fim de Ano..."
                 className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 bg-white"
               />
             </div>

             <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Visibilidade</label>
                <div className="relative">
                   <select
                     value={targetTeamId}
                     onChange={e => setTargetTeamId(e.target.value)}
                     className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm appearance-none bg-white"
                   >
                     <option value="ALL">Todas as Equipes</option>
                     {teams.map(t => (
                       <option key={t.id} value={t.id}>{t.name}</option>
                     ))}
                   </select>
                   <Users size={14} className="absolute right-3 top-3 text-slate-400 pointer-events-none"/>
                </div>
             </div>

             <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Cor</label>
               <div className="flex gap-3">
                  {(Object.keys(ALERT_COLOR_MAP) as AlertColor[]).map((c) => (
                    <button
                      key={c}
                      onClick={() => setColor(c)}
                      className={`w-8 h-8 rounded-full flex items-center justify-center transition-transform hover:scale-110 ${ALERT_COLOR_MAP[c].bg.replace('50', '500')}`}
                    >
                      {color === c && <Check size={16} className="text-white" />}
                    </button>
                  ))}
               </div>
             </div>

             <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Início</label>
                  <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 bg-white"/>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Fim</label>
                  <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full px-2 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 bg-white"/>
                </div>
             </div>

             <div className="flex gap-2">
                {editingId && (
                  <button onClick={resetForm} className="flex-1 bg-white border border-slate-300 text-slate-700 text-sm font-medium py-2 rounded-lg hover:bg-slate-50">
                    Cancelar
                  </button>
                )}
                <button 
                  onClick={handleSave}
                  className="flex-1 bg-slate-900 hover:bg-black text-white font-medium py-2 rounded-lg shadow-sm transition-colors"
                >
                  {editingId ? 'Salvar Alterações' : 'Criar Alerta'}
                </button>
             </div>
           </div>

           {/* List Section - Now only showing active alerts */}
           {activeAlerts.length > 0 && (
              <div className="space-y-2">
                 <h3 className="text-sm font-bold text-slate-700 mt-2">Alertas Ativos</h3>
                 {activeAlerts.map(alert => {
                   const styles = ALERT_COLOR_MAP[alert.color];
                   const isEditing = editingId === alert.id;
                   return (
                     <div 
                        key={alert.id} 
                        className={`flex items-center justify-between p-3 rounded-lg border transition-all ${styles.bg} ${isEditing ? 'border-indigo-500 ring-1 ring-indigo-500' : styles.border}`}
                     >
                        <div className="cursor-pointer flex-1" onClick={() => handleEdit(alert)}>
                           <div className={`text-sm font-bold ${styles.text}`}>{alert.label}</div>
                           <div className="text-xs text-slate-500">
                             {format(alert.startDate, 'dd/MM')} até {format(alert.endDate, 'dd/MM')}
                             {alert.targetTeamId && alert.targetTeamId !== 'ALL' && (
                               <span className="ml-1 opacity-75">• Equipe Específica</span>
                             )}
                           </div>
                        </div>

                        <div className="flex items-center gap-1 ml-2">
                          <button 
                             onClick={(e) => {
                                e.stopPropagation();
                                handleEdit(alert);
                             }}
                             className="p-2 text-slate-400 hover:text-indigo-600 transition-colors bg-white rounded-md border border-transparent hover:border-slate-200"
                             title="Editar"
                          >
                             <Pencil size={16} />
                          </button>
                          {onDelete && (
                            <button 
                               onClick={(e) => {
                                  e.stopPropagation(); 
                                  if(window.confirm('Excluir este alerta?')) onDelete(alert.id);
                               }}
                               className="p-2 text-slate-400 hover:text-red-500 transition-colors bg-white rounded-md border border-transparent hover:border-slate-200"
                               title="Excluir"
                            >
                               <Trash2 size={16} />
                            </button>
                          )}
                        </div>
                     </div>
                   );
                 })}
              </div>
           )}
           {activeAlerts.length === 0 && alertPeriods.length > 0 && (
              <div className="text-center text-xs text-slate-400 py-4">
                 Todos os alertas estão expirados.
              </div>
           )}
        </div>
      </div>
    </div>
  );
};

export default AlertModal;

import React, { useState } from 'react';
import { 
  startOfMonth, endOfMonth, startOfWeek, endOfWeek, 
  eachDayOfInterval, isSameMonth, isSameDay, addMonths, subMonths, 
  format, isToday, isWithinInterval 
} from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { ChevronLeft, ChevronRight, Plus, AlertTriangle, Users, X, Clock, Eye, EyeOff } from 'lucide-react';
import { Task, User, normalizeDate, AlertPeriod, ALERT_COLOR_MAP, Team } from '../types';
import { STATUS_COLORS, STATUS_LABELS } from '../constants';

interface CalendarProps {
  tasks: Task[];
  users: User[];
  teams: Team[];
  alertPeriods: AlertPeriod[];
  currentUser: User;
  onAddTask: (date: Date) => void;
  onEditTask: (task: Task) => void;
}

const Calendar: React.FC<CalendarProps> = ({ tasks, users, teams, alertPeriods, currentUser, onAddTask, onEditTask }) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [expandedDay, setExpandedDay] = useState<Date | null>(null);

  // 6. Option to hide completed demands
  const [showCompleted, setShowCompleted] = useState(true);

  const firstDayOfMonth = startOfMonth(currentDate);
  const lastDayOfMonth = endOfMonth(currentDate);
  const startDate = startOfWeek(firstDayOfMonth); 
  const endDate = endOfWeek(lastDayOfMonth);

  const days = eachDayOfInterval({ start: startDate, end: endDate });

  const nextMonth = () => setCurrentDate(addMonths(currentDate, 1));
  const prevMonth = () => setCurrentDate(subMonths(currentDate, 1));
  const goToToday = () => setCurrentDate(new Date());

  const getTasksForDay = (date: Date) => {
    return tasks
      .filter(task => {
         const sameDay = isSameDay(normalizeDate(task.date), normalizeDate(date));
         // Filter out done tasks if toggle is off
         if (!showCompleted && task.status === 'DONE') return false;
         return sameDay;
      })
      .sort((a, b) => (a.startTime || '').localeCompare(b.startTime || ''));
  };

  // Allow multiple alerts per day
  const getAlertsForDay = (date: Date) => {
    return alertPeriods.filter(period => 
      isWithinInterval(normalizeDate(date), { 
        start: normalizeDate(period.startDate), 
        end: normalizeDate(period.endDate) 
      })
    );
  };

  const DayExpandedModal = () => {
    if (!expandedDay) return null;
    const dayTasks = getTasksForDay(expandedDay);
    const dayAlerts = getAlertsForDay(expandedDay);

    return (
      <div className="absolute inset-0 z-40 bg-white/95 backdrop-blur-sm flex flex-col p-6 animate-in fade-in zoom-in duration-200">
         <div className="flex justify-between items-center mb-6 border-b border-slate-200 pb-4">
             <div>
                <h2 className="text-3xl font-bold text-slate-800 capitalize">
                    {format(expandedDay, "EEEE, d 'de' MMMM", { locale: ptBR })}
                </h2>
                {isToday(expandedDay) && <span className="text-sm font-bold text-indigo-600 uppercase">Hoje</span>}
             </div>
             <div className="flex gap-3">
                 <button 
                   onClick={() => onAddTask(expandedDay)}
                   className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg font-medium transition-colors shadow-lg"
                 >
                    <Plus size={18} /> Nova Demanda
                 </button>
                 <button 
                   onClick={() => setExpandedDay(null)}
                   className="bg-slate-100 hover:bg-slate-200 text-slate-600 p-2 rounded-lg transition-colors"
                 >
                    <X size={24} />
                 </button>
             </div>
         </div>

         <div className="flex-1 overflow-y-auto custom-scrollbar">
             {/* Alerts Section in Expanded View */}
             {dayAlerts.length > 0 && (
                <div className="mb-6 flex flex-wrap gap-2">
                   {dayAlerts.map(alert => (
                      <div key={alert.id} className={`${ALERT_COLOR_MAP[alert.color].bg} ${ALERT_COLOR_MAP[alert.color].text} border ${ALERT_COLOR_MAP[alert.color].border} px-3 py-1.5 rounded-full text-sm font-bold flex items-center gap-2`}>
                         <AlertTriangle size={16} /> {alert.label}
                      </div>
                   ))}
                </div>
             )}

             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                 {dayTasks.length === 0 && (
                    <div className="col-span-full text-center text-slate-400 py-12 text-lg">
                       Nenhuma demanda agendada para este dia.
                    </div>
                 )}
                 {dayTasks.map(task => {
                    const assignee = users.find(u => u.id === task.assigneeId);
                    const assignedTeam = !assignee ? teams.find(t => t.id === task.assigneeId) : null;
                    let progressPercent = 0;
                    if (assignedTeam) {
                        const teamMembers = users.filter(u => u.teamId === assignedTeam.id);
                        const doneCount = teamMembers.filter(u => task.teamProgress?.[u.id] === 'DONE').length;
                        progressPercent = teamMembers.length > 0 ? Math.round((doneCount / teamMembers.length) * 100) : 0;
                    }

                    return (
                       <div 
                         key={task.id}
                         onClick={() => onEditTask(task)}
                         className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm hover:shadow-md hover:border-indigo-300 transition-all cursor-pointer group"
                       >
                           <div className="flex justify-between items-start mb-2">
                               <div className="flex items-center gap-1.5 text-sm font-semibold text-slate-500 bg-slate-50 px-2 py-1 rounded">
                                   <Clock size={14} />
                                   {task.startTime || '--:--'} - {task.endTime || '--:--'}
                               </div>
                               <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold border ${STATUS_COLORS[task.status]}`}>
                                   {STATUS_LABELS[task.status]}
                               </span>
                           </div>

                           <h3 className="text-base font-bold text-slate-800 mb-2 group-hover:text-indigo-700 transition-colors">
                             {task.title}
                           </h3>

                           {assignedTeam ? (
                              <div className="mt-3">
                                 <div className="flex justify-between text-xs text-slate-500 mb-1">
                                    <span>Equipe: {assignedTeam.name}</span>
                                    <span>{progressPercent}%</span>
                                 </div>
                                 <div className="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
                                     <div className="bg-indigo-500 h-full" style={{ width: `${progressPercent}%` }}></div>
                                 </div>
                              </div>
                           ) : assignee && (
                              <div className="flex items-center gap-2 mt-3 pt-3 border-t border-slate-50">
                                 <img src={assignee.avatar} className="w-6 h-6 rounded-full" alt=""/>
                                 <span className="text-sm text-slate-600">{assignee.name}</span>
                              </div>
                           )}
                       </div>
                    )
                 })}
             </div>
         </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden relative">

      {/* Expanded Modal Overlay */}
      <DayExpandedModal />

      {/* Calendar Header */}
      <div className="flex-none flex items-center justify-between px-6 py-4 border-b border-slate-100 bg-white z-10">
        <div className="flex items-center gap-4">
          <h2 className="text-2xl font-bold text-slate-800 capitalize">
            {format(currentDate, 'MMMM yyyy', { locale: ptBR })}
          </h2>
          <div className="flex items-center bg-slate-100 rounded-lg p-1">
            <button onClick={prevMonth} className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-slate-600">
              <ChevronLeft size={20} />
            </button>
            <button onClick={nextMonth} className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-slate-600">
              <ChevronRight size={20} />
            </button>
          </div>
        </div>

        <div className="flex gap-2">
            <button
               onClick={() => setShowCompleted(!showCompleted)}
               className={`flex items-center gap-2 px-3 py-2 text-sm font-medium border rounded-lg transition-colors ${showCompleted ? 'text-indigo-600 bg-indigo-50 border-indigo-200' : 'text-slate-500 bg-white border-slate-200'}`}
               title={showCompleted ? "Ocultar Concluídas" : "Mostrar Concluídas"}
            >
               {showCompleted ? <Eye size={18} /> : <EyeOff size={18} />}
               <span className="hidden sm:inline">{showCompleted ? 'Ocultar Concluídas' : 'Mostrar Concluídas'}</span>
            </button>

            <button 
                onClick={goToToday}
                className="px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-200 hover:bg-slate-50 hover:border-slate-300 rounded-lg transition-colors"
            >
                Hoje
            </button>
        </div>
      </div>

      {/* Days of Week Header */}
      <div className="flex-none grid grid-cols-7 border-b border-slate-100 bg-slate-50">
        {['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'].map((day) => (
          <div key={day} className="py-3 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">
            {day}
          </div>
        ))}
      </div>

      {/* Calendar Grid - Scrollable Area */}
      <div className="flex-1 overflow-y-auto custom-scrollbar">
        <div className="grid grid-cols-7 min-h-full auto-rows-[minmax(120px,1fr)] bg-slate-100 gap-[1px]">
          {days.map((day) => {
            const dayTasks = getTasksForDay(day);
            const isCurrentMonth = isSameMonth(day, currentDate);
            const isDayToday = isToday(day);
            const dayAlerts = getAlertsForDay(day);

            return (
              <div 
                key={day.toISOString()} 
                onClick={() => setExpandedDay(day)}
                className={`
                  relative flex flex-col p-1 transition-colors min-h-[140px] cursor-pointer hover:bg-slate-50
                  ${!isCurrentMonth ? 'bg-slate-50/50' : 'bg-white'}
                `}
              >
                {/* 3. Multi-Alert Stack Header - Now with Text inside */}
                <div className="flex flex-col gap-[2px] w-full mb-1">
                    {dayAlerts.map(alert => (
                        <div 
                            key={alert.id} 
                            className={`h-4 w-full rounded-full ${ALERT_COLOR_MAP[alert.color].bar} flex items-center px-1 overflow-hidden`} 
                            title={alert.label}
                        >
                            <span className="text-[9px] font-bold text-white truncate w-full leading-none">
                                {alert.label}
                            </span>
                        </div>
                    ))}
                </div>

                {/* Day Number */}
                <div className="flex justify-between items-center px-1">
                  <span className={`
                    text-sm font-medium w-6 h-6 flex items-center justify-center rounded-full
                    ${isDayToday 
                      ? 'bg-indigo-600 text-white' 
                      : isCurrentMonth ? 'text-slate-700' : 'text-slate-400'}
                  `}>
                    {format(day, 'd')}
                  </span>
                </div>

                {/* Tasks List */}
                <div className="flex flex-col gap-1 mt-1 overflow-hidden">
                  {dayTasks.slice(0, 4).map(task => {
                    const assignee = users.find(u => u.id === task.assigneeId);
                    const assignedTeam = !assignee ? teams.find(t => t.id === task.assigneeId) : null;

                    return (
                      <div
                        key={task.id}
                        className={`
                          text-left text-[9px] px-1 py-0.5 rounded border truncate relative
                          ${!assignedTeam ? STATUS_COLORS[task.status] : 'bg-white border-slate-200 text-slate-700'}
                        `}
                      >
                         <span className="font-semibold">{task.startTime}</span> {task.title}
                      </div>
                    );
                  })}
                  {dayTasks.length > 4 && (
                      <div className="text-[9px] text-slate-400 text-center font-medium">+ {dayTasks.length - 4} mais</div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Calendar;

import React, { useState } from 'react';
import { Task, User, Team, normalizeDate, TaskStatus } from '../types';
import { STATUS_LABELS, STATUS_COLORS } from '../constants';
import { format, isSameDay } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { Clock, CheckCircle2, Users, PlayCircle, Circle, Filter, X } from 'lucide-react';

interface TaskListViewProps {
  tasks: Task[];
  currentUser: User;
  users: User[];
  teams: Team[];
  onEditTask: (task: Task) => void;
}

const TaskListView: React.FC<TaskListViewProps> = ({ tasks, currentUser, users, teams, onEditTask }) => {
  // 5. Date Filter State
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // Sort tasks by date and then by start time
  let filteredTasks = [...tasks];

  // Apply Date Filter if set
  if (startDate) {
      const start = normalizeDate(new Date(startDate + 'T00:00:00'));
      filteredTasks = filteredTasks.filter(t => normalizeDate(t.date) >= start);
  }
  if (endDate) {
      const end = normalizeDate(new Date(endDate + 'T00:00:00'));
      filteredTasks = filteredTasks.filter(t => normalizeDate(t.date) <= end);
  }

  const sortedTasks = filteredTasks.sort((a, b) => {
    const dateComp = a.date.getTime() - b.date.getTime();
    if (dateComp !== 0) return dateComp;
    return (a.startTime || '').localeCompare(b.startTime || '');
  });

  // Group by Date
  const groupedTasks: Record<string, Task[]> = {};
  sortedTasks.forEach(task => {
    const dateKey = task.date.toISOString();
    if (!groupedTasks[dateKey]) groupedTasks[dateKey] = [];
    groupedTasks[dateKey].push(task);
  });

  const handleQuickStatusUpdate = (e: React.MouseEvent, task: Task) => {
     e.stopPropagation();
     // If it's a team task, toggle MY status
     const team = teams.find(t => t.id === task.assigneeId);
     if (team) {
         // It's a team task
         const currentMyStatus = (task.teamProgress?.[currentUser.id] || 'TODO') as TaskStatus;
         let nextStatus: TaskStatus = 'TODO';
         if (currentMyStatus === 'TODO') nextStatus = 'IN_PROGRESS';
         else if (currentMyStatus === 'IN_PROGRESS') nextStatus = 'DONE';
         else nextStatus = 'TODO'; // Cycle back

         const updatedTask: Task = {
             ...task,
             teamProgress: {
                 ...(task.teamProgress || {}),
                 [currentUser.id]: nextStatus
             }
         };
         onEditTask(updatedTask);
     } else {
         onEditTask(task);
     }
  };

  const clearFilters = () => {
      setStartDate('');
      setEndDate('');
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 h-full overflow-y-auto custom-scrollbar p-6 flex flex-col">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
          <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
            <Clock className="text-indigo-600" /> Cronograma de Demandas
          </h2>

          <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-lg border border-slate-200">
             <div className="flex items-center gap-2">
                <span className="text-xs font-bold text-slate-500 uppercase">De:</span>
                <input 
                   type="date" 
                   value={startDate} 
                   onChange={e => setStartDate(e.target.value)}
                   className="text-sm border-slate-300 rounded px-2 py-1 bg-white focus:ring-1 focus:ring-indigo-500"
                />
             </div>
             <div className="flex items-center gap-2">
                <span className="text-xs font-bold text-slate-500 uppercase">Até:</span>
                <input 
                   type="date" 
                   value={endDate} 
                   onChange={e => setEndDate(e.target.value)}
                   className="text-sm border-slate-300 rounded px-2 py-1 bg-white focus:ring-1 focus:ring-indigo-500"
                />
             </div>
             {(startDate || endDate) && (
                <button 
                  onClick={clearFilters}
                  className="p-1 hover:bg-slate-200 rounded text-slate-500"
                  title="Limpar Filtro"
                >
                    <X size={16} />
                </button>
             )}
          </div>
      </div>

      {Object.keys(groupedTasks).length === 0 ? (
        <div className="text-center py-12 text-slate-400">
          Nenhuma demanda encontrada neste período.
        </div>
      ) : (
        <div className="space-y-8">
          {Object.entries(groupedTasks).map(([dateStr, dayTasks]) => {
            const date = new Date(dateStr);
            const isToday = isSameDay(date, new Date());

            return (
              <div key={dateStr} className="relative pl-6 border-l-2 border-indigo-100">
                <div className={`
                  absolute -left-[9px] top-0 w-4 h-4 rounded-full border-2 border-white
                  ${isToday ? 'bg-indigo-600 shadow-md shadow-indigo-200' : 'bg-slate-300'}
                `}></div>

                <h3 className={`text-sm font-bold uppercase tracking-wide mb-4 ${isToday ? 'text-indigo-600' : 'text-slate-500'}`}>
                  {format(date, "dd/MM/yy ' - ' EEEE", { locale: ptBR })} {isToday && '(Hoje)'}
                </h3>

                <div className="space-y-3">
                  {dayTasks.map(task => {
                    const assignee = users.find(u => u.id === task.assigneeId);
                    const assignedTeam = !assignee ? teams.find(t => t.id === task.assigneeId) : null;

                    // Calculate progress for team task
                    let progressPercent = 0;
                    if (assignedTeam) {
                        const teamMembers = users.filter(u => u.teamId === assignedTeam.id);
                        const doneCount = teamMembers.filter(u => task.teamProgress?.[u.id] === 'DONE').length;
                        progressPercent = teamMembers.length > 0 ? Math.round((doneCount / teamMembers.length) * 100) : 0;
                    }

                    return (
                      <div 
                        key={task.id}
                        onClick={() => onEditTask(task)}
                        className="group flex items-center justify-between p-4 bg-slate-50 hover:bg-white rounded-xl border border-slate-100 hover:border-indigo-200 hover:shadow-md transition-all cursor-pointer"
                      >
                        <div className="flex items-start gap-4 w-full">
                          <div className="flex flex-col items-center min-w-[60px]">
                            <span className="text-sm font-bold text-slate-700">{task.startTime || '--:--'}</span>
                            <span className="text-xs text-slate-400">às {task.endTime || '--:--'}</span>
                          </div>

                          <div className="flex-1">
                            <h4 className="font-semibold text-slate-800 group-hover:text-indigo-700 transition-colors flex items-center gap-2">
                              {task.title}
                              {assignedTeam && (
                                <span className="bg-slate-200 text-slate-700 text-[10px] px-1.5 py-0.5 rounded font-bold uppercase flex items-center gap-1">
                                    <Users size={10} /> TIME
                                </span>
                              )}
                            </h4>
                            <div className="flex items-center gap-2 mt-1">
                              {assignee && (
                                <div className="flex items-center gap-1.5 bg-white px-2 py-0.5 rounded-full border border-slate-200">
                                  <img src={assignee.avatar} className="w-4 h-4 rounded-full" alt="" />
                                  <span className="text-xs text-slate-600">{assignee.name.split(' ')[0]}</span>
                                </div>
                              )}
                              {assignedTeam && (
                                <div className="flex items-center gap-1.5 bg-indigo-50 px-2 py-0.5 rounded-full border border-indigo-100">
                                   <Users size={12} className="text-indigo-600" />
                                   <span className="text-xs font-bold text-indigo-700">Toda a Equipe</span>
                                </div>
                              )}

                              {!assignedTeam ? (
                                <span className={`text-[10px] px-2 py-0.5 rounded-full border font-medium ${STATUS_COLORS[task.status]}`}>
                                    {STATUS_LABELS[task.status]}
                                </span>
                              ) : (
                                 <div className="flex items-center gap-2">
                                     <div className="w-20 h-2 bg-slate-200 rounded-full overflow-hidden">
                                        <div className="bg-indigo-600 h-full" style={{ width: `${progressPercent}%` }}></div>
                                     </div>
                                     <span className="text-[10px] font-bold text-slate-500">{progressPercent}%</span>
                                 </div>
                              )}
                            </div>
                          </div>
                        </div>

                        {/* Quick Action Button Hint */}
                        <div 
                          className="opacity-0 group-hover:opacity-100 transition-opacity ml-4 text-slate-400"
                          onClick={(e) => handleQuickStatusUpdate(e, task)}
                        >
                           <PlayCircle size={20} className="hover:text-indigo-600" />
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default TaskListView;

import React, { useState } from 'react';
import { 
  startOfMonth, endOfMonth, startOfWeek, endOfWeek, 
  eachDayOfInterval, isSameMonth, isSameDay, addMonths, subMonths, 
  format, isToday, isWithinInterval 
} from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { ChevronLeft, ChevronRight, Plus, AlertTriangle, Users, X, Clock, Eye, EyeOff } from 'lucide-react';
import { Task, User, normalizeDate, AlertPeriod, ALERT_COLOR_MAP, Team } from '../types';
import { STATUS_COLORS, STATUS_LABELS } from '../constants';

interface CalendarProps {
  tasks: Task[];
  users: User[];
  teams: Team[];
  alertPeriods: AlertPeriod[];
  currentUser: User;
  onAddTask: (date: Date) => void;
  onEditTask: (task: Task) => void;
}

const Calendar: React.FC<CalendarProps> = ({ tasks, users, teams, alertPeriods, currentUser, onAddTask, onEditTask }) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [expandedDay, setExpandedDay] = useState<Date | null>(null);

  // 6. Option to hide completed demands
  const [showCompleted, setShowCompleted] = useState(true);

  const firstDayOfMonth = startOfMonth(currentDate);
  const lastDayOfMonth = endOfMonth(currentDate);
  const startDate = startOfWeek(firstDayOfMonth); 
  const endDate = endOfWeek(lastDayOfMonth);

  const days = eachDayOfInterval({ start: startDate, end: endDate });

  const nextMonth = () => setCurrentDate(addMonths(currentDate, 1));
  const prevMonth = () => setCurrentDate(subMonths(currentDate, 1));
  const goToToday = () => setCurrentDate(new Date());

  const getTasksForDay = (date: Date) => {
    return tasks
      .filter(task => {
         const sameDay = isSameDay(normalizeDate(task.date), normalizeDate(date));
         // Filter out done tasks if toggle is off
         if (!showCompleted && task.status === 'DONE') return false;
         return sameDay;
      })
      .sort((a, b) => (a.startTime || '').localeCompare(b.startTime || ''));
  };

  // Allow multiple alerts per day
  const getAlertsForDay = (date: Date) => {
    return alertPeriods.filter(period => 
      isWithinInterval(normalizeDate(date), { 
        start: normalizeDate(period.startDate), 
        end: normalizeDate(period.endDate) 
      })
    );
  };

  const DayExpandedModal = () => {
    if (!expandedDay) return null;
    const dayTasks = getTasksForDay(expandedDay);
    const dayAlerts = getAlertsForDay(expandedDay);

    return (
      <div className="absolute inset-0 z-40 bg-white/95 backdrop-blur-sm flex flex-col p-6 animate-in fade-in zoom-in duration-200">
         <div className="flex justify-between items-center mb-6 border-b border-slate-200 pb-4">
             <div>
                <h2 className="text-3xl font-bold text-slate-800 capitalize">
                    {format(expandedDay, "EEEE, d 'de' MMMM", { locale: ptBR })}
                </h2>
                {isToday(expandedDay) && <span className="text-sm font-bold text-indigo-600 uppercase">Hoje</span>}
             </div>
             <div className="flex gap-3">
                 <button 
                   onClick={() => onAddTask(expandedDay)}
                   className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg font-medium transition-colors shadow-lg"
                 >
                    <Plus size={18} /> Nova Demanda
                 </button>
                 <button 
                   onClick={() => setExpandedDay(null)}
                   className="bg-slate-100 hover:bg-slate-200 text-slate-600 p-2 rounded-lg transition-colors"
                 >
                    <X size={24} />
                 </button>
             </div>
         </div>

         <div className="flex-1 overflow-y-auto custom-scrollbar">
             {/* Alerts Section in Expanded View */}
             {dayAlerts.length > 0 && (
                <div className="mb-6 flex flex-wrap gap-2">
                   {dayAlerts.map(alert => (
                      <div key={alert.id} className={`${ALERT_COLOR_MAP[alert.color].bg} ${ALERT_COLOR_MAP[alert.color].text} border ${ALERT_COLOR_MAP[alert.color].border} px-3 py-1.5 rounded-full text-sm font-bold flex items-center gap-2`}>
                         <AlertTriangle size={16} /> {alert.label}
                      </div>
                   ))}
                </div>
             )}

             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                 {dayTasks.length === 0 && (
                    <div className="col-span-full text-center text-slate-400 py-12 text-lg">
                       Nenhuma demanda agendada para este dia.
                    </div>
                 )}
                 {dayTasks.map(task => {
                    const assignee = users.find(u => u.id === task.assigneeId);
                    const assignedTeam = !assignee ? teams.find(t => t.id === task.assigneeId) : null;
                    let progressPercent = 0;
                    if (assignedTeam) {
                        const teamMembers = users.filter(u => u.teamId === assignedTeam.id);
                        const doneCount = teamMembers.filter(u => task.teamProgress?.[u.id] === 'DONE').length;
                        progressPercent = teamMembers.length > 0 ? Math.round((doneCount / teamMembers.length) * 100) : 0;
                    }

                    return (
                       <div 
                         key={task.id}
                         onClick={() => onEditTask(task)}
                         className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm hover:shadow-md hover:border-indigo-300 transition-all cursor-pointer group"
                       >
                           <div className="flex justify-between items-start mb-2">
                               <div className="flex items-center gap-1.5 text-sm font-semibold text-slate-500 bg-slate-50 px-2 py-1 rounded">
                                   <Clock size={14} />
                                   {task.startTime || '--:--'} - {task.endTime || '--:--'}
                               </div>
                               <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold border ${STATUS_COLORS[task.status]}`}>
                                   {STATUS_LABELS[task.status]}
                               </span>
                           </div>

                           <h3 className="text-base font-bold text-slate-800 mb-2 group-hover:text-indigo-700 transition-colors">
                             {task.title}
                           </h3>

                           {assignedTeam ? (
                              <div className="mt-3">
                                 <div className="flex justify-between text-xs text-slate-500 mb-1">
                                    <span>Equipe: {assignedTeam.name}</span>
                                    <span>{progressPercent}%</span>
                                 </div>
                                 <div className="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
                                     <div className="bg-indigo-500 h-full" style={{ width: `${progressPercent}%` }}></div>
                                 </div>
                              </div>
                           ) : assignee && (
                              <div className="flex items-center gap-2 mt-3 pt-3 border-t border-slate-50">
                                 <img src={assignee.avatar} className="w-6 h-6 rounded-full" alt=""/>
                                 <span className="text-sm text-slate-600">{assignee.name}</span>
                              </div>
                           )}
                       </div>
                    )
                 })}
             </div>
         </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden relative">

      {/* Expanded Modal Overlay */}
      <DayExpandedModal />

      {/* Calendar Header */}
      <div className="flex-none flex items-center justify-between px-6 py-4 border-b border-slate-100 bg-white z-10">
        <div className="flex items-center gap-4">
          <h2 className="text-2xl font-bold text-slate-800 capitalize">
            {format(currentDate, 'MMMM yyyy', { locale: ptBR })}
          </h2>
          <div className="flex items-center bg-slate-100 rounded-lg p-1">
            <button onClick={prevMonth} className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-slate-600">
              <ChevronLeft size={20} />
            </button>
            <button onClick={nextMonth} className="p-1 hover:bg-white hover:shadow-sm rounded-md transition-all text-slate-600">
              <ChevronRight size={20} />
            </button>
          </div>
        </div>

        <div className="flex gap-2">
            <button
               onClick={() => setShowCompleted(!showCompleted)}
               className={`flex items-center gap-2 px-3 py-2 text-sm font-medium border rounded-lg transition-colors ${showCompleted ? 'text-indigo-600 bg-indigo-50 border-indigo-200' : 'text-slate-500 bg-white border-slate-200'}`}
               title={showCompleted ? "Ocultar Concluídas" : "Mostrar Concluídas"}
            >
               {showCompleted ? <Eye size={18} /> : <EyeOff size={18} />}
               <span className="hidden sm:inline">{showCompleted ? 'Ocultar Concluídas' : 'Mostrar Concluídas'}</span>
            </button>

            <button 
                onClick={goToToday}
                className="px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-200 hover:bg-slate-50 hover:border-slate-300 rounded-lg transition-colors"
            >
                Hoje
            </button>
        </div>
      </div>

      {/* Days of Week Header */}
      <div className="flex-none grid grid-cols-7 border-b border-slate-100 bg-slate-50">
        {['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'].map((day) => (
          <div key={day} className="py-3 text-center text-xs font-semibold text-slate-500 uppercase tracking-wider">
            {day}
          </div>
        ))}
      </div>

      {/* Calendar Grid - Scrollable Area */}
      <div className="flex-1 overflow-y-auto custom-scrollbar">
        <div className="grid grid-cols-7 min-h-full auto-rows-[minmax(120px,1fr)] bg-slate-100 gap-[1px]">
          {days.map((day) => {
            const dayTasks = getTasksForDay(day);
            const isCurrentMonth = isSameMonth(day, currentDate);
            const isDayToday = isToday(day);
            const dayAlerts = getAlertsForDay(day);

            return (
              <div 
                key={day.toISOString()} 
                onClick={() => setExpandedDay(day)}
                className={`
                  relative flex flex-col p-1 transition-colors min-h-[140px] cursor-pointer hover:bg-slate-50
                  ${!isCurrentMonth ? 'bg-slate-50/50' : 'bg-white'}
                `}
              >
                {/* Header Row: Day Number + Alerts next to it */}
                <div className="flex justify-between items-start px-1 pt-1 mb-1 gap-1">

                  {/* Day Number */}
                  <span className={`
                    text-sm font-medium w-6 h-6 flex items-center justify-center rounded-full shrink-0
                    ${isDayToday 
                      ? 'bg-indigo-600 text-white' 
                      : isCurrentMonth ? 'text-slate-700' : 'text-slate-400'}
                  `}>
                    {format(day, 'd')}
                  </span>

                  {/* Alerts Container (Next to Number) */}
                  <div className="flex flex-col gap-0.5 items-end flex-1 min-w-0 max-w-[80%]">
                      {dayAlerts.map(alert => (
                          <div 
                              key={alert.id} 
                              className={`
                                  w-full text-right ${ALERT_COLOR_MAP[alert.color].bg} ${ALERT_COLOR_MAP[alert.color].text} 
                                  border ${ALERT_COLOR_MAP[alert.color].border}
                                  text-[9px] font-bold px-1.5 py-0.5 rounded-md truncate
                              `}
                              title={alert.label}
                          >
                              {alert.label}
                          </div>
                      ))}
                  </div>
                </div>

                {/* Tasks List */}
                <div className="flex flex-col gap-1 mt-1 overflow-hidden">
                  {dayTasks.slice(0, 4).map(task => {
                    const assignee = users.find(u => u.id === task.assigneeId);
                    const assignedTeam = !assignee ? teams.find(t => t.id === task.assigneeId) : null;

                    return (
                      <div
                        key={task.id}
                        className={`
                          text-left text-[9px] px-1 py-0.5 rounded border truncate relative
                          ${!assignedTeam ? STATUS_COLORS[task.status] : 'bg-white border-slate-200 text-slate-700'}
                        `}
                      >
                         <span className="font-semibold">{task.startTime}</span> {task.title}
                      </div>
                    );
                  })}
                  {dayTasks.length > 4 && (
                      <div className="text-[9px] text-slate-400 text-center font-medium">+ {dayTasks.length - 4} mais</div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Calendar;

