function responseJSON(data) {
  return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
}

// --- SETUP INICIAL ---
function setup() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheets = ['Tasks', 'Users', 'Teams', 'Alerts', 'Notes']; // Adicionado Notes

  sheets.forEach(name => {
    if (!ss.getSheetByName(name)) {
      ss.insertSheet(name);
      const sheet = ss.getSheetByName(name);
      if (name === 'Tasks') sheet.appendRow(['id', 'title', 'description', 'assigneeId', 'targetTeamId', 'date', 'startTime', 'endTime', 'status', 'priority', 'isNudged', 'teamProgress']);
      if (name === 'Users') sheet.appendRow(['id', 'name', 'email', 'role', 'teamId', 'avatar', 'presencialDates', 'password']);
      if (name === 'Teams') sheet.appendRow(['id', 'name', 'color']);
      if (name === 'Alerts') sheet.appendRow(['id', 'startDate', 'endDate', 'label', 'color', 'targetTeamId']);
      if (name === 'Notes') sheet.appendRow(['id', 'userId', 'content', 'updatedAt']);
    }
  });
}

// --- READ ALL ---
function handleRead() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // Helper para ler planilhas
  const readSheet = (name) => {
    const sheet = ss.getSheetByName(name);
    if (!sheet || sheet.getLastRow() <= 1) return [];
    const data = sheet.getDataRange().getValues();
    const headers = data[0];
    const rows = data.slice(1);
    return rows.map(row => {
      let obj = {};
      headers.forEach((h, i) => obj[h] = row[i]);
      // Tratamento especial para arrays JSON
      if (obj.presencialDates) {
         try { obj.presencialDates = JSON.parse(obj.presencialDates); } catch(e) { obj.presencialDates = []; }
      }
      return obj;
    });
  };

  const tasks = readSheet('Tasks');
  const users = readSheet('Users');
  const teams = readSheet('Teams');
  const alerts = readSheet('Alerts');
  const notes = readSheet('Notes');

  return responseJSON({ tasks, users, teams, alerts, notes });
}

// --- GENERIC SAVE ---
function saveData(sheetName, data, uniqueKey = 'id') {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(sheetName);

  if (!sheet) { setup(); sheet = ss.getSheetByName(sheetName); }

  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
  const allIds = sheet.getDataRange().getValues().map(r => r[0]); // Assume ID na coluna 1

  // Preparar linha
  const row = headers.map(h => {
    let val = data[h];
    if (Array.isArray(val) || typeof val === 'object') return JSON.stringify(val);
    return val;
  });

  const existingIndex = allIds.indexOf(data[uniqueKey]);

  if (existingIndex > 0) {
    // Update
    sheet.getRange(existingIndex + 1, 1, 1, row.length).setValues([row]);
  } else {
    // Insert
    sheet.appendRow(row);
  }
  return responseJSON({ success: true });
}

// --- GENERIC DELETE ---
function deleteData(sheetName, id) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);
  const data = sheet.getDataRange().getValues();

  for (let i = 1; i < data.length; i++) {
    if (data[i][0] == id) {
      sheet.deleteRow(i + 1);
      return responseJSON({ success: true });
    }
  }
  return responseJSON({ error: 'Not found' });
}

// --- HANDLERS ESPECÍFICOS ---

function handleSaveTask(data) { return saveData('Tasks', data); }
function handleDeleteTask(data) { return deleteData('Tasks', data.id); }

// Nova Função: Batch Save (Recorrência)
function handleSaveTasksBatch(dataArray) {
  if (!Array.isArray(dataArray)) return responseJSON({ error: 'Data must be an array' });

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName('Tasks');
  if (!sheet) { setup(); sheet = ss.getSheetByName('Tasks'); }

  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

  // Convert array of objects to array of rows
  const rowsToAdd = dataArray.map(task => {
     return headers.map(h => {
        let val = task[h];
        if (Array.isArray(val) || typeof val === 'object') return JSON.stringify(val);
        return val;
     });
  });

  // Append all rows at once
  if (rowsToAdd.length > 0) {
     sheet.getRange(sheet.getLastRow() + 1, 1, rowsToAdd.length, rowsToAdd[0].length).setValues(rowsToAdd);
  }

  return responseJSON({ success: true, count: rowsToAdd.length });
}

function handleSaveUser(data) { return saveData('Users', data); }
function handleDeleteUser(data) { return deleteData('Users', data.id); }

// Batch Users (para salvar presença em lote)
function handleSaveUsersBatch(usersArray) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName('Users');
  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
  const allData = sheet.getDataRange().getValues();

  usersArray.forEach(user => {
     const row = headers.map(h => {
        let val = user[h];
        if (Array.isArray(val) || typeof val === 'object') return JSON.stringify(val);
        return val;
     });

     // Find by ID
     let found = false;
     for(let i=1; i<allData.length; i++) {
        if(allData[i][0] === user.id) {
           sheet.getRange(i+1, 1, 1, row.length).setValues([row]);
           found = true;
           break;
        }
     }
     if(!found) sheet.appendRow(row);
  });

  return responseJSON({ success: true });
}

